import { EventType, NewsItem, PopupConfig, FormTemplate, Step, QuickLink, ContactInfo, UserAccount, UserRole } from '../types';
import { 
  ADMIN_CREDENTIALS, 
  CREATOR_CREDENTIALS,
  NEWS_DATA,
  EVENTS_DATA,
  DEFAULT_POPUPS,
  DEFAULT_FORMS,
  DEFAULT_QUICK_LINKS,
  DEFAULT_CONTACT_INFO
} from '../constants';

const KEYS = {
  USERS: 'sepri_users',
  EVENTS: 'sepri_events',
  NEWS: 'sepri_news',
  POPUPS: 'sepri_popups',
  FORMS: 'sepri_forms',
  QUICK_LINKS: 'sepri_quick_links',
  CONTACT: 'sepri_contact'
};

// --- USER AUTH (LOCAL ONLY) ---

async function hashPassword(password: string): Promise<string> {
  if (window.crypto && window.crypto.subtle) {
    try {
      const msgBuffer = new TextEncoder().encode(password);
      const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
      const hashArray = Array.from(new Uint8Array(hashBuffer));
      return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    } catch (e) {
      console.warn("Crypto subtle failed", e);
    }
  }
  let hash = 0;
  for (let i = 0; i < password.length; i++) {
    hash = ((hash << 5) - hash) + password.charCodeAt(i);
    hash = hash & hash;
  }
  return "insecure_hash_" + Math.abs(hash).toString(16);
}

function generateSecurePassword(): string {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+";
  let password = "";
  for (let i = 0; i < 12; i++) {
    password += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return password;
}

const getLocal = <T>(key: string, defaultVal: T): T => {
  try {
    const item = localStorage.getItem(key);
    return item ? JSON.parse(item) : defaultVal;
  } catch {
    return defaultVal;
  }
};

const setLocal = (key: string, val: any) => {
  localStorage.setItem(key, JSON.stringify(val));
};

export const initUsers = async () => {
  const existingUsers = localStorage.getItem(KEYS.USERS);
  if (!existingUsers) {
    const adminHash = await hashPassword(ADMIN_CREDENTIALS.password);
    const creatorHash = await hashPassword(CREATOR_CREDENTIALS.password);
    const initialUsers: UserAccount[] = [
      { id: 'user-admin', name: 'Administrador SEPRI', email: ADMIN_CREDENTIALS.username, passwordHash: adminHash, role: 'ADMIN' },
      { id: 'user-creator', name: 'Creador del Sistema', email: CREATOR_CREDENTIALS.username, passwordHash: creatorHash, role: 'CREATOR' }
    ];
    setLocal(KEYS.USERS, initialUsers);
  }
};

export const getUsers = (): UserAccount[] => getLocal(KEYS.USERS, []);

export const authenticateUser = async (email: string, passwordPlain: string): Promise<UserRole | null> => {
  if (!localStorage.getItem(KEYS.USERS)) await initUsers();
  const users = getUsers();
  const inputHash = await hashPassword(passwordPlain);
  const user = users.find(u => u.email === email && u.passwordHash === inputHash);
  return user ? user.role : null;
};

export const resetUserPassword = async (userId: string): Promise<string | null> => {
  try {
    const users = getUsers();
    const index = users.findIndex(u => u.id === userId);
    if (index !== -1) {
      const newPassword = generateSecurePassword();
      users[index].passwordHash = await hashPassword(newPassword);
      setLocal(KEYS.USERS, users);
      return newPassword;
    }
  } catch (error) { console.error(error); }
  return null;
};

export const saveUsers = (users: UserAccount[]) => setLocal(KEYS.USERS, users);

// --- HYBRID DATA MANAGEMENT (BACKEND + LOCAL FALLBACK) ---

async function getHybridData<T>(endpoint: string, key: string, defaultData: T): Promise<T> {
  try {
    const response = await fetch(`/.netlify/functions/${endpoint}`);
    if (response.ok) {
      const data = await response.json();
      return data as T;
    }
  } catch (e) {
    console.warn(`Backend no disponible para ${endpoint}`, e);
  }
  return defaultData;
}

async function saveHybridData<T>(endpoint: string, key: string, data: T): Promise<void> {
  const role = localStorage.getItem('sepri_user_role') || 'USER';
  try {
    const res = await fetch(`/.netlify/functions/${endpoint}`, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        'x-sepri-role': role // Add security header for backend check
      },
      body: JSON.stringify(data),
    });
    if (!res.ok) {
      const err = await res.text();
      alert(`Error del servidor: ${err}`);
      throw new Error(err);
    }
  } catch (e) {
    console.warn(`Error al sincronizar ${endpoint} con el backend`, e);
    throw e;
  }
}

// EVENTS
export const getEvents = async () => {
  const data = await getHybridData<EventType[]>('events', KEYS.EVENTS, EVENTS_DATA as any);
  // Ensure steps are sorted when loaded
  return data.map(event => ({
    ...event,
    baseSteps: [...event.baseSteps].sort((a, b) => (a.order || 0) - (b.order || 0))
  }));
};

export const saveEvents = (data: EventType[]) => saveHybridData('events', KEYS.EVENTS, data);

export const addEvent = async (event: EventType) => {
  const items = await getEvents();
  items.push(event);
  await saveEvents(items);
};

export const deleteEvent = async (id: string) => {
  let items = await getEvents();
  items = items.filter(i => i.id !== id);
  await saveEvents(items);
};

export const updateEventStep = async (eventId: string, updatedStep: Step) => {
  const events = await getEvents();
  const event = events.find(e => e.id === eventId);
  if (event) {
    const idx = event.baseSteps.findIndex(s => s.id === updatedStep.id);
    if (idx !== -1) {
      event.baseSteps[idx] = updatedStep;
    } else {
      // If new, set order to last
      const maxOrder = event.baseSteps.reduce((max, s) => Math.max(max, s.order || 0), -1);
      updatedStep.order = maxOrder + 1;
      event.baseSteps.push(updatedStep);
    }
    // Re-normalize orders to be safe
    event.baseSteps.sort((a, b) => a.order - b.order).forEach((s, i) => s.order = i);
    await saveEvents(events);
  }
};

// NEWS
export const getNews = () => getHybridData('news', KEYS.NEWS, NEWS_DATA);
export const saveNews = (data: NewsItem[]) => saveHybridData('news', KEYS.NEWS, data);

// POPUPS
export const getPopups = () => getHybridData('popups', KEYS.POPUPS, DEFAULT_POPUPS);
export const savePopups = (data: PopupConfig[]) => saveHybridData('popups', KEYS.POPUPS, data);
export const togglePopup = async (id: string, isEnabled: boolean) => {
  const items = await getPopups();
  const item = items.find(i => i.id === id);
  if (item) { item.isEnabled = isEnabled; await savePopups(items); }
};
export const updatePopup = async (updated: PopupConfig) => {
  const items = await getPopups();
  const idx = items.findIndex(i => i.id === updated.id);
  if (idx !== -1) { items[idx] = updated; await savePopups(items); }
};

// FORMS
export const getForms = () => getHybridData('forms', KEYS.FORMS, DEFAULT_FORMS);
export const saveForms = (data: FormTemplate[]) => saveHybridData('forms', KEYS.FORMS, data);
export const addForm = async (form: FormTemplate) => {
  const items = await getForms();
  items.push(form);
  await saveForms(items);
};
export const deleteForm = async (id: string) => {
  const items = await getForms();
  await saveForms(items.filter(i => i.id !== id));
};

// QUICK LINKS
export const getQuickLinks = () => getHybridData('quickLinks', KEYS.QUICK_LINKS, DEFAULT_QUICK_LINKS);
export const saveQuickLinks = (data: QuickLink[]) => saveHybridData('quickLinks', KEYS.QUICK_LINKS, data);
export const addQuickLink = async (link: QuickLink) => {
  const items = await getQuickLinks();
  items.push(link);
  await saveQuickLinks(items);
};
export const deleteQuickLink = async (id: string) => {
  const items = await getQuickLinks();
  await saveQuickLinks(items.filter(i => i.id !== id));
};
export const updateQuickLink = async (link: QuickLink) => {
  const items = await getQuickLinks();
  const idx = items.findIndex(i => i.id === link.id);
  if (idx !== -1) { items[idx] = link; await saveQuickLinks(items); }
};

// CONTACT
export const getContactInfo = () => getHybridData('contact', KEYS.CONTACT, DEFAULT_CONTACT_INFO);
export const saveContactInfo = (data: ContactInfo) => saveHybridData('contact', KEYS.CONTACT, data);

import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ArrowLeft, Download, CheckCircle, AlertCircle, FileText, Plus, Save, Clock, Edit2, File } from 'lucide-react';
import { EXTRA_STEPS } from '../constants';
import { Step, UserRole, FormTemplate, EventType } from '../types';
import { getEvents, updateEventStep, getForms } from '../services/dataService';

const EventProcessPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [answers, setAnswers] = useState<Record<string, boolean>>({});
  const [currentSteps, setCurrentSteps] = useState<Step[]>([]);
  const [downloadedItems, setDownloadedItems] = useState<Set<string>>(new Set());

  // Data State
  const [event, setEvent] = useState<EventType | null>(null);
  const [loading, setLoading] = useState(true);

  // Admin Management State
  const [userRole, setUserRole] = useState<UserRole>('USER');
  const [editingStep, setEditingStep] = useState<Step | null>(null);

  // Forms State
  const [availableForms, setAvailableForms] = useState<FormTemplate[]>([]);
  const [activeForm, setActiveForm] = useState<FormTemplate | null>(null);
  const [formResponses, setFormResponses] = useState<Record<string, string>>({});

  // Load Data
  useEffect(() => {
    const loadData = async () => {
        const storedRole = localStorage.getItem('sepri_user_role') as UserRole;
        if (storedRole) setUserRole(storedRole);

        if (id) {
            const allEvents = await getEvents();
            const foundEvent = allEvents.find(e => e.id === id);
            setEvent(foundEvent || null);

            const allForms = await getForms();
            setAvailableForms(allForms.filter(f => f.eventId === id));
        }
        setLoading(false);
    };
    loadData();
  }, [id]);

  // Logic to calculate steps
  useEffect(() => {
    if (!event) return;

    let steps = [...event.baseSteps];

    // Check answers to trigger extra steps
    Object.keys(answers).forEach((questionId) => {
      if (answers[questionId]) {
        const question = event.questions.find(q => q.id === questionId);
        if (question) {
          question.triggerSteps.forEach(stepId => {
            if (EXTRA_STEPS[stepId] && !steps.find(s => s.id === stepId)) {
              // Note: extra steps don't have orders in constants, we assign 99 to put them at the end
              const extraStep = { ...EXTRA_STEPS[stepId], order: 99 };
              steps.push(extraStep);
            }
          });
        }
      }
    });

    // Sort steps by order
    steps.sort((a, b) => (a.order || 0) - (b.order || 0));
    setCurrentSteps(steps);
  }, [answers, event]);

  if (loading) {
      return <div className="min-h-screen flex justify-center items-center">Cargando...</div>;
  }

  const canManage = userRole === 'ADMIN' || userRole === 'CREATOR';

  if (!event) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center text-center px-4">
        <AlertCircle size={64} className="text-red-500 mb-4" />
        <h1 className="text-2xl font-bold text-gray-800">Evento no encontrado</h1>
        <Link to="/" className="mt-4 text-sepri-medium hover:underline">Volver al inicio</Link>
      </div>
    );
  }

  const handleAnswer = (questionId: string, value: boolean) => {
    setAnswers(prev => ({ ...prev, [questionId]: value }));
  };

  const handleDownload = (stepId: string, url?: string) => {
    const newDownloads = new Set(downloadedItems);
    newDownloads.add(stepId);
    setDownloadedItems(newDownloads);

    if (url) {
      window.open(url, '_blank');
    } else {
      alert("Este formato estará disponible pronto o no tiene enlace configurado.");
    }
  };

  const handleDownloadGeneralDoc = () => {
     if (event.documentUrl) {
       window.open(event.documentUrl, '_blank');
     } else {
       alert('No hay documento adjunto.');
     }
  };

  // --- Admin Functions ---

  const handleSaveStep = async (step: Step) => {
    if (!canManage) return;
    if (!step.title) {
        alert("El título del ítem es obligatorio.");
        return;
    }

    if (step.downloadUrl && !step.downloadUrl.match(/^https?:\/\//)) {
        alert("La URL debe comenzar con http:// o https://");
        return;
    }

    try {
      await updateEventStep(event.id, step);
      setEditingStep(null);
      // Reload data
      const allEvents = await getEvents();
      const foundEvent = allEvents.find(e => e.id === id);
      setEvent(foundEvent || null);
    } catch (e) {
      alert("No se pudo guardar el cambio. Verifica tus permisos.");
    }
  };

  // --- Form Filling Functions ---
  const handleOpenForm = (form: FormTemplate) => {
    setActiveForm(form);
    setFormResponses({});
  };

  const handleDownloadForm = () => {
    if (!activeForm) return;

    let content = `FORMULARIO: ${activeForm.title}\nEVENTO: ${event.title}\nFECHA: ${new Date().toLocaleString()}\n\nRESPUESTAS:\n----------------\n`;

    activeForm.fields.forEach(field => {
       content += `${field.label}: ${formResponses[field.id] || 'N/A'}\n`;
    });

    const element = document.createElement("a");
    const file = new Blob([content], {type: 'text/plain'});
    element.href = URL.createObjectURL(file);
    element.download = `${activeForm.title.replace(/\s+/g, '_')}_diligenciado.txt`;
    document.body.appendChild(element); 
    element.click();
    document.body.removeChild(element);

    setActiveForm(null);
    alert("Formulario descargado correctamente.");
  };

  return (
    <div className="min-h-screen bg-sepri-bg pb-20">
      {/* Header for the process */}
      <div className="bg-sepri-medium text-white py-10">
        <div className="container mx-auto px-4">
          <div className="flex justify-between items-start">
            <div>
              <Link to="/" className="inline-flex items-center text-blue-200 hover:text-white mb-4 transition-colors">
                <ArrowLeft size={18} className="mr-2" /> Volver
              </Link>
              <h1 className="text-3xl md:text-4xl font-bold mb-2">Protocolo: {event.title}</h1>
              <p className="text-blue-100 max-w-2xl">{event.description}</p>

              {event.documentUrl && (
                <button onClick={handleDownloadGeneralDoc} className="mt-4 bg-sepri-yellow text-sepri-dark px-4 py-2 rounded-lg font-bold text-sm inline-flex items-center hover:bg-yellow-400 transition-colors shadow-md">
                   <File size={16} className="mr-2"/> Descargar Protocolo General
                </button>
              )}
            </div>
            {canManage && (
              <div className="bg-sepri-yellow text-sepri-dark px-4 py-2 rounded-lg font-bold text-xs shadow-lg">
                MODO EDICIÓN ACTIVO
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="container mx-auto px-4 -mt-8">
        <div className="flex flex-col lg:flex-row gap-8">

          {/* Left Column: Questions & Forms */}
          <div className="lg:w-1/3 space-y-8">
            <div className="bg-white rounded-xl shadow-lg p-6 sticky top-24">
              <h2 className="text-xl font-bold text-sepri-dark mb-6 flex items-center">
                <AlertCircle className="mr-2 text-sepri-yellow" />
                Detalles del Evento
              </h2>
              <div className="space-y-6">
                {event.questions.filter(q => q.isEnabled !== false).map((q) => (
                  <div key={q.id} className="p-4 border border-gray-100 rounded-lg bg-gray-50">
                    <p className="font-medium text-gray-700 mb-3 text-sm">{q.text}</p>
                    <div className="flex gap-3">
                      <button onClick={() => handleAnswer(q.id, true)} className={`flex-1 py-2 rounded-lg text-sm font-semibold transition-all ${answers[q.id] === true ? 'bg-sepri-green text-white shadow-md' : 'bg-white border border-gray-300 text-gray-600 hover:bg-gray-100'}`}>SÍ</button>
                      <button onClick={() => handleAnswer(q.id, false)} className={`flex-1 py-2 rounded-lg text-sm font-semibold transition-all ${answers[q.id] === false ? 'bg-gray-700 text-white shadow-md' : 'bg-white border border-gray-300 text-gray-600 hover:bg-gray-100'}`}>NO</button>
                    </div>
                  </div>
                ))}
                {event.questions.filter(q => q.isEnabled !== false).length === 0 && (
                   <p className="text-gray-400 text-sm text-center">No hay preguntas adicionales para este protocolo.</p>
                )}
              </div>
            </div>

            {/* Available Forms Section */}
            {availableForms.length > 0 && (
              <div className="bg-white rounded-xl shadow-lg p-6">
                 <h2 className="text-xl font-bold text-sepri-dark mb-4 flex items-center">
                   <FileText className="mr-2 text-blue-500" /> Formularios Disponibles
                 </h2>
                 <ul className="space-y-3">
                   {availableForms.map(form => (
                     <li key={form.id} className="p-3 border rounded hover:bg-gray-50 flex justify-between items-center">
                       <div>
                         <p className="font-bold text-sm text-gray-800">{form.title}</p>
                         <p className="text-xs text-gray-500">{form.description}</p>
                       </div>
                       <button onClick={() => handleOpenForm(form)} className="text-sepri-medium text-sm font-semibold hover:underline">
                         Diligenciar
                       </button>
                     </li>
                   ))}
                 </ul>
              </div>
            )}
          </div>

          {/* Right Column: Steps/Checklist */}
          <div className="lg:w-2/3">
            <div className="bg-white rounded-xl shadow-lg overflow-hidden">
              <div className="bg-gray-50 p-6 border-b border-gray-100 flex justify-between items-center">
                <h2 className="text-xl font-bold text-sepri-dark">Ruta de Cumplimiento</h2>
                <div className="flex items-center gap-3">
                  {canManage && (
                    <button onClick={() => { setEditingStep({ id: `new-${Date.now()}`, title: '', description: '', isCustom: true, order: currentSteps.length } as Step); }} className="bg-sepri-dark text-white p-2 rounded-full hover:bg-gray-800 transition-colors" title="Agregar Ítem">
                      <Plus size={18} />
                    </button>
                  )}
                  <span className="bg-sepri-medium text-white px-3 py-1 rounded-full text-xs font-bold">
                    {currentSteps.length} Pasos
                  </span>
                </div>
              </div>

              {/* Edit/Add Step Modal (Inline) */}
              {editingStep && canManage && (
                <div className="p-6 bg-blue-50 border-b border-blue-100 animate-fade-in">
                  <h3 className="font-bold text-sepri-dark mb-4">{editingStep.id.startsWith('new') ? 'Agregar Ítem' : 'Editar Ítem'}</h3>
                  <div className="space-y-4">
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-1">Título</label>
                        <input type="text" placeholder="Ej: Documentación Vehículo" className="w-full p-2 border rounded" value={editingStep.title} onChange={e => setEditingStep({...editingStep, title: e.target.value})} />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-1">Descripción</label>
                        <input type="text" placeholder="Ej: Copia de SOAT y Tecnomecánica" className="w-full p-2 border rounded" value={editingStep.description} onChange={e => setEditingStep({...editingStep, description: e.target.value})} />
                    </div>

                    <div className="bg-white p-3 border rounded-lg border-blue-200">
                        <label className="block text-sm font-bold text-sepri-dark mb-1">URL del Documento del Ítem (Drive / OneDrive / URL)</label>
                        <input 
                            type="text" 
                            placeholder="https://drive.google.com/..." 
                            className="w-full p-2 border rounded border-gray-300 focus:border-sepri-medium focus:ring-1 focus:ring-sepri-medium outline-none" 
                            value={editingStep.downloadUrl || ''} 
                            onChange={e => setEditingStep({...editingStep, downloadUrl: e.target.value, isDownloadable: !!e.target.value})} 
                        />
                        <p className="text-xs text-gray-500 mt-1">Este enlace se abrirá cuando el usuario haga clic en "Descargar Formato".</p>
                    </div>

                    <div className="flex justify-end gap-2 pt-2">
                      <button onClick={() => setEditingStep(null)} className="px-4 py-2 text-gray-600 text-sm hover:bg-gray-100 rounded">Cancelar</button>
                      <button onClick={() => handleSaveStep(editingStep)} className="px-4 py-2 bg-sepri-medium text-white rounded text-sm flex items-center hover:bg-sepri-dark shadow-sm">
                        <Save size={16} className="mr-2" /> Guardar Ítem
                      </button>
                    </div>
                  </div>
                </div>
              )}

              {/* Steps List */}
              <div className="divide-y divide-gray-100">
                {currentSteps.map((step, index) => {
                  const isDownloaded = downloadedItems.has(step.id);
                  return (
                    <div key={step.id} className="p-6 hover:bg-gray-50 transition-colors relative group">
                      {canManage && (
                        <button onClick={() => setEditingStep(step)} className="absolute top-4 right-4 text-blue-400 hover:text-blue-600 opacity-0 group-hover:opacity-100 transition-opacity bg-white p-1 rounded-full shadow-sm" title="Editar Ítem">
                          <Edit2 size={18} />
                        </button>
                      )}

                      <div className="flex items-start gap-4">
                        <div className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm shadow-sm transition-colors ${isDownloaded ? 'bg-sepri-green text-white' : 'bg-sepri-medium text-white'}`}>
                          {isDownloaded ? <CheckCircle size={18} /> : index + 1}
                        </div>
                        <div className="flex-1">
                          <div className="flex flex-col md:flex-row md:justify-between md:items-start gap-2">
                            <h3 className="text-lg font-bold text-gray-800 flex items-center">
                              {step.title}
                              {isDownloaded && <span className="ml-2 text-xs text-sepri-green bg-green-50 px-2 py-0.5 rounded border border-green-100">Descargado</span>}
                            </h3>
                            {step.deadline && <span className="inline-flex items-center text-xs font-semibold text-red-500 bg-red-50 px-2 py-1 rounded border border-red-100 whitespace-nowrap"><Clock size={12} className="mr-1" /> {step.deadline}</span>}
                          </div>
                          <p className="text-gray-600 text-sm mt-2 mb-4">{step.description}</p>

                          <div className="flex flex-wrap gap-3">
                            {step.isDownloadable && (
                              <button onClick={() => handleDownload(step.id, step.downloadUrl)} className={`inline-flex items-center px-4 py-2 rounded-lg text-sm font-medium transition-colors ${isDownloaded ? 'bg-green-100 text-green-700 hover:bg-green-200' : 'bg-sepri-light/10 text-sepri-medium hover:bg-sepri-light/20'}`}>
                                {isDownloaded ? <><CheckCircle size={16} className="mr-2" /> Descargar Nuevamente</> : <><Download size={16} className="mr-2" /> Descargar Formato</>}
                              </button>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
                {currentSteps.length === 0 && <p className="p-8 text-center text-gray-500">No hay pasos definidos para este protocolo.</p>}
              </div>
            </div>
          </div>

        </div>
      </div>

      {/* Form Filling Modal */}
      {activeForm && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg p-6 animate-fade-in-up max-h-[90vh] overflow-y-auto">
             <div className="flex justify-between items-center mb-4">
               <h3 className="text-xl font-bold text-sepri-dark">{activeForm.title}</h3>
               <button onClick={() => setActiveForm(null)} className="text-gray-400 hover:text-gray-600"><Plus className="rotate-45" size={24}/></button>
             </div>
             <p className="text-gray-600 text-sm mb-6">{activeForm.description}</p>

             <div className="space-y-4">
               {activeForm.fields.map(field => (
                 <div key={field.id}>
                   <label className="block text-sm font-bold text-gray-700 mb-1">{field.label}</label>
                   {field.type === 'textarea' ? (
                     <textarea className="w-full border p-2 rounded" rows={3} onChange={(e) => setFormResponses({...formResponses, [field.id]: e.target.value})} />
                   ) : field.type === 'checkbox' ? (
                     <input type="checkbox" className="h-5 w-5" onChange={(e) => setFormResponses({...formResponses, [field.id]: e.target.checked ? 'Si' : 'No'})} />
                   ) : (
                     <input type="text" className="w-full border p-2 rounded" onChange={(e) => setFormResponses({...formResponses, [field.id]: e.target.value})} />
                   )}
                 </div>
               ))}
             </div>

             <div className="mt-8 flex justify-end gap-3">
               <button onClick={() => setActiveForm(null)} className="px-4 py-2 text-gray-500">Cancelar</button>
               <button onClick={handleDownloadForm} className="bg-sepri-medium text-white px-6 py-2 rounded-lg font-bold hover:bg-sepri-dark">
                 Descargar Diligenciado
               </button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default EventProcessPage;

import React, { useState, useEffect } from 'react';
import { Lock, User, ChevronRight, Key, LogOut, Settings, Newspaper, MessageSquare, FileText, Plus, Trash2, Edit2, Save, ToggleLeft, ToggleRight, Check, Image as ImageIcon, Briefcase, File, X, List, ExternalLink, Link as LinkIcon, Phone, Share2, ShieldAlert, Copy, ChevronUp, ChevronDown } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { DEFAULT_CONTACT_INFO } from '../constants';
import { UserRole, NewsItem, PopupConfig, FormTemplate, FormField, EventType, Question, Step, QuickLink, ContactInfo, UserAccount } from '../types';
import { getNews, saveNews, getPopups, togglePopup, updatePopup, getForms, addForm, deleteForm, getEvents, saveEvents, addEvent, deleteEvent, getQuickLinks, addQuickLink, deleteQuickLink, updateQuickLink, getContactInfo, saveContactInfo, authenticateUser, getUsers, resetUserPassword, initUsers } from '../services/dataService';

const AdminLogin: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentRole, setCurrentRole] = useState<UserRole>('USER');
  const navigate = useNavigate();

  // Dashboard State
  const [activeTab, setActiveTab] = useState<'news' | 'popups' | 'forms' | 'protocols' | 'links' | 'config' | 'creator'>('news');
  const [news, setNews] = useState<NewsItem[]>([]);
  const [popups, setPopups] = useState<PopupConfig[]>([]);
  const [forms, setForms] = useState<FormTemplate[]>([]);
  const [events, setEvents] = useState<EventType[]>([]);
  const [quickLinks, setQuickLinks] = useState<QuickLink[]>([]);
  const [contactInfo, setContactInfo] = useState<ContactInfo>(DEFAULT_CONTACT_INFO);

  // User Management State (Creator)
  const [users, setUsers] = useState<UserAccount[]>([]);
  const [newGeneratedPassword, setNewGeneratedPassword] = useState<string | null>(null);
  const [isResetting, setIsResetting] = useState<string | null>(null); // Track ID of user being reset

  // Form Builder State
  const [isCreatingForm, setIsCreatingForm] = useState(false);
  const [newForm, setNewForm] = useState<Partial<FormTemplate>>({ title: '', fields: [] });
  const [newField, setNewField] = useState<Partial<FormField>>({ label: '', type: 'text' });

  // News Editor State
  const [isEditingNews, setIsEditingNews] = useState(false);
  const [currentNews, setCurrentNews] = useState<Partial<NewsItem>>({});

  // Protocol (Event) Editor State
  const [isEditingProtocol, setIsEditingProtocol] = useState(false);
  const [currentProtocol, setCurrentProtocol] = useState<Partial<EventType>>({ baseSteps: [], questions: [] });
  const [newQuestionText, setNewQuestionText] = useState('');

  // Protocol Steps (Items) State for adding new
  const [newStep, setNewStep] = useState<Partial<Step>>({ title: '', description: '', deadline: '', downloadUrl: '' });

  // Quick Links State
  const [newLink, setNewLink] = useState<Partial<QuickLink>>({ title: '', url: '' });
  const [editingLinkId, setEditingLinkId] = useState<string | null>(null);
  const [tempLinkData, setTempLinkData] = useState<Partial<QuickLink>>({});

  // Popup Editing State
  const [editingPopupId, setEditingPopupId] = useState<string | null>(null);
  const [tempPopupData, setTempPopupData] = useState<Partial<PopupConfig>>({});

  useEffect(() => {
    // Check login
    const storedRole = localStorage.getItem('sepri_user_role');
    if (storedRole && (storedRole === 'ADMIN' || storedRole === 'CREATOR')) {
      setIsLoggedIn(true);
      setCurrentRole(storedRole as UserRole);
      loadData();
    }
  }, []);

  const loadData = async () => {
    setNews(await getNews());
    setPopups(await getPopups());
    setForms(await getForms());
    setEvents(await getEvents());
    setQuickLinks(await getQuickLinks());
    const contact = await getContactInfo();
    if(contact) setContactInfo(contact);

    if (currentRole === 'CREATOR') {
      setUsers(getUsers()); 
    }
  };

  // Reload users when tab switches to creator
  useEffect(() => {
    if (activeTab === 'creator') {
        setUsers(getUsers());
    }
  }, [activeTab]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
        const role = await authenticateUser(email, password);
        if (role) {
            localStorage.setItem('sepri_user_role', role);
            setCurrentRole(role);
            setIsLoggedIn(true);
            loadData();
        } else {
            alert("Credenciales incorrectas.");
        }
    } catch (error) {
        console.error(error);
        alert("Error al iniciar sesión.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('sepri_user_role');
    setIsLoggedIn(false);
    setCurrentRole('USER');
    navigate('/');
  };

  const canManage = currentRole === 'ADMIN' || currentRole === 'CREATOR';

  // --- REORDERING LOGIC ---
  const handleMoveStep = (index: number, direction: 'up' | 'down') => {
    if (!currentProtocol.baseSteps) return;
    const newSteps = [...currentProtocol.baseSteps];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;

    if (targetIndex < 0 || targetIndex >= newSteps.length) return;

    // Swap elements
    [newSteps[index], newSteps[targetIndex]] = [newSteps[targetIndex], newSteps[index]];

    // Normalize order values
    newSteps.forEach((s, i) => s.order = i);

    setCurrentProtocol(prev => ({ ...prev, baseSteps: newSteps }));
  };

  // --- USER MANAGEMENT (CREATOR) ---
  const handleResetPassword = async (userId: string, userName: string) => {
    if (!confirm(`¿Estás seguro de resetear la contraseña para ${userName}? La contraseña anterior dejará de funcionar.`)) {
        return;
    }

    setIsResetting(userId);
    try {
        await new Promise(resolve => setTimeout(resolve, 800)); 
        const newPwd = await resetUserPassword(userId);
        if (newPwd) {
            setNewGeneratedPassword(newPwd);
        } else {
            alert("Error: No se pudo generar la contraseña.");
        }
    } catch (error) {
        console.error("Reset password failed:", error);
        alert("Ocurrió un error inesperado al resetear la clave.");
    } finally {
        setIsResetting(null);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("Contraseña copiada al portapapeles");
  };

  // --- NEWS MANAGEMENT ---
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'news' | 'protocol_image') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        if (target === 'news') {
          setCurrentNews(prev => ({ ...prev, imageUrl: result }));
        } else if (target === 'protocol_image') {
          setCurrentProtocol(prev => ({ ...prev, imageUrl: result }));
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveNews = async () => {
    if (!canManage) return;
    if (!currentNews.title || !currentNews.summary) return;

    let updatedNews = [...news];
    if (currentNews.id) {
      updatedNews = updatedNews.map(n => n.id === currentNews.id ? { ...n, ...currentNews } as NewsItem : n);
    } else {
      const newItem: NewsItem = {
        id: Date.now().toString(),
        title: currentNews.title,
        summary: currentNews.summary,
        category: currentNews.category || 'Novedad',
        date: new Date().toLocaleDateString('es-CO'),
        ...currentNews
      } as NewsItem;
      updatedNews.unshift(newItem);
    }

    try {
      await saveNews(updatedNews);
      setNews(updatedNews);
      setIsEditingNews(false);
      setCurrentNews({});
    } catch (e) {
      alert("No se pudo guardar la noticia.");
    }
  };

  const handleDeleteNews = async (id: string) => {
    if (!canManage) return;
    if (confirm('¿Eliminar esta noticia?')) {
      const updated = news.filter(n => n.id !== id);
      try {
        await saveNews(updated);
        setNews(updated);
      } catch (e) { alert("Error al eliminar."); }
    }
  };

  // --- PROTOCOLS (EVENTS) MANAGEMENT ---
  const handleSaveProtocol = async () => {
    if (!canManage) return;
    if (!currentProtocol.title?.trim() || !currentProtocol.description?.trim()) {
      alert("Título y descripción requeridos");
      return;
    }

    try {
      const protocolToSave: EventType = {
        id: currentProtocol.id || `evt-${Date.now()}`,
        title: currentProtocol.title!,
        description: currentProtocol.description!,
        iconName: currentProtocol.iconName || 'FileText',
        imageUrl: currentProtocol.imageUrl,
        documentUrl: currentProtocol.documentUrl,
        baseSteps: (currentProtocol.baseSteps || []).map((s, i) => ({ ...s, order: i })),
        questions: currentProtocol.questions || []
      };

      if (currentProtocol.id) {
        const updatedEvents = events.map(e => e.id === currentProtocol.id ? protocolToSave : e);
        await saveEvents(updatedEvents);
        setEvents(updatedEvents);
      } else {
        await addEvent(protocolToSave);
        setEvents(await getEvents());
      }
      setIsEditingProtocol(false);
      setCurrentProtocol({ baseSteps: [], questions: [] });
      alert("Protocolo guardado exitosamente.");
    } catch (error) {
      console.error("Error saving protocol:", error);
      alert("Error al guardar: Revisa tu conexión y permisos.");
    }
  };

  const handleDeleteProtocol = async (id: string) => {
    if (!canManage) return;
    if (confirm('¿Eliminar este protocolo completo y todos sus datos?')) {
      try {
        await deleteEvent(id);
        setEvents(await getEvents());
      } catch (e) { alert("Error al eliminar."); }
    }
  };

  // Protocol Questions Management
  const handleAddQuestion = () => {
    if (!newQuestionText) return;
    const newQ: Question = {
      id: `q-${Date.now()}`,
      text: newQuestionText,
      triggerSteps: [], 
      isEnabled: true
    };
    setCurrentProtocol(prev => ({
      ...prev,
      questions: [...(prev.questions || []), newQ]
    }));
    setNewQuestionText('');
  };

  const handleToggleQuestion = (qId: string) => {
    setCurrentProtocol(prev => {
      const updatedQs = prev.questions?.map(q => 
        q.id === qId ? { ...q, isEnabled: !q.isEnabled } : q
      ) || [];
      return { ...prev, questions: updatedQs };
    });
  };

  const handleDeleteQuestion = (qId: string) => {
    setCurrentProtocol(prev => {
      const updatedQs = prev.questions?.filter(q => q.id !== qId) || [];
      return { ...prev, questions: updatedQs };
    });
  };

  const handleEditQuestionText = (qId: string, text: string) => {
    setCurrentProtocol(prev => {
      const updatedQs = prev.questions?.map(q => 
        q.id === qId ? { ...q, text } : q
      ) || [];
      return { ...prev, questions: updatedQs };
    });
  };

  // Protocol Steps (Items) Management
  const handleAddStepLocal = () => {
    if (!newStep.title) return;

    if (newStep.downloadUrl && !/^https?:\/\//.test(newStep.downloadUrl)) {
      alert("La URL debe comenzar con http:// o https://");
      return;
    }

    const step: Step = {
      id: `step-${Date.now()}`,
      title: newStep.title!,
      description: newStep.description || '',
      deadline: newStep.deadline,
      downloadUrl: newStep.downloadUrl,
      isDownloadable: !!newStep.downloadUrl,
      order: (currentProtocol.baseSteps?.length || 0)
    };

    setCurrentProtocol(prev => ({
      ...prev,
      baseSteps: [...(prev.baseSteps || []), step]
    }));
    setNewStep({ title: '', description: '', deadline: '', downloadUrl: '' });
  };

  const handleUpdateStepLocal = (id: string, field: keyof Step, value: any) => {
    setCurrentProtocol(prev => ({
      ...prev,
      baseSteps: prev.baseSteps?.map(s => {
        if (s.id === id) {
           const updated = { ...s, [field]: value };
           if (field === 'downloadUrl') {
             updated.isDownloadable = !!value;
           }
           return updated;
        }
        return s;
      })
    }));
  };

  const handleDeleteStepLocal = (id: string) => {
    if(confirm("¿Eliminar este ítem?")) {
      setCurrentProtocol(prev => {
        const remaining = prev.baseSteps?.filter(s => s.id !== id) || [];
        remaining.forEach((s, i) => s.order = i);
        return { ...prev, baseSteps: remaining };
      });
    }
  };

  // --- POPUP MANAGEMENT ---
  const handleTogglePopup = async (id: string, currentStatus: boolean) => {
    if (!canManage) return;
    try {
      await togglePopup(id, !currentStatus);
      setPopups(await getPopups());
    } catch (e) { alert("Error al cambiar estado."); }
  };

  const startEditingPopup = (popup: PopupConfig) => {
    setEditingPopupId(popup.id);
    setTempPopupData({ ...popup });
  };

  const cancelEditingPopup = () => {
    setEditingPopupId(null);
    setTempPopupData({});
  };

  const saveEditingPopup = async () => {
    if (!canManage) return;
    if (editingPopupId && tempPopupData.title && tempPopupData.content && tempPopupData.type) {
      try {
        await updatePopup({ ...tempPopupData } as PopupConfig);
        setPopups(await getPopups());
        setEditingPopupId(null);
        setTempPopupData({});
      } catch (e) { alert("Error al guardar."); }
    }
  };

  // --- FORM MANAGEMENT ---
  const addFieldToForm = () => {
    if (!newField.label) return;
    const field: FormField = {
      id: `field-${Date.now()}`,
      label: newField.label,
      type: newField.type || 'text',
      required: false
    };
    setNewForm(prev => ({ ...prev, fields: [...(prev.fields || []), field] }));
    setNewField({ label: '', type: 'text' });
  };

  const handleSaveForm = async () => {
    if (!canManage) return;
    if (!newForm.title || !newForm.eventId) {
      alert("Debes asignar un título y un evento al formulario");
      return;
    }
    const template: FormTemplate = {
      id: `form-${Date.now()}`,
      eventId: newForm.eventId,
      title: newForm.title,
      description: newForm.description,
      fields: newForm.fields || []
    };
    try {
      await addForm(template);
      setForms(await getForms());
      setIsCreatingForm(false);
      setNewForm({ title: '', fields: [] });
    } catch (e) { alert("Error al guardar formulario."); }
  };

  const handleDeleteForm = async (id: string) => {
    if (!canManage) return;
    if (confirm('¿Eliminar este formulario?')) {
      try {
        await deleteForm(id);
        setForms(await getForms());
      } catch (e) { alert("Error al eliminar."); }
    }
  };

  // --- QUICK LINKS MANAGEMENT ---
  const handleSaveQuickLink = async () => {
    if (!canManage) return;
    if (!newLink.title || !newLink.url) return;
    const link: QuickLink = {
        id: `ql-${Date.now()}`,
        title: newLink.title!,
        url: newLink.url!,
        isEnabled: true
    };
    try {
      await addQuickLink(link);
      setQuickLinks(await getQuickLinks());
      setNewLink({ title: '', url: '' });
    } catch (e) { alert("Error al agregar link."); }
  };

  const handleDeleteQuickLink = async (id: string) => {
    if (!canManage) return;
    if (confirm("¿Eliminar este enlace?")) {
      try {
        await deleteQuickLink(id);
        setQuickLinks(await getQuickLinks());
      } catch (e) { alert("Error al eliminar."); }
    }
  };

  const handleToggleQuickLink = async (id: string) => {
    if (!canManage) return;
    const link = quickLinks.find(l => l.id === id);
    if (link) {
      try {
        await updateQuickLink({ ...link, isEnabled: !link.isEnabled });
        setQuickLinks(await getQuickLinks());
      } catch (e) { alert("Error al cambiar estado."); }
    }
  };

  const startEditingLink = (link: QuickLink) => {
    setEditingLinkId(link.id);
    setTempLinkData({ ...link });
  };

  const cancelEditingLink = () => {
    setEditingLinkId(null);
    setTempLinkData({});
  };

  const saveEditingLink = async () => {
    if (!canManage) return;
    if (editingLinkId && tempLinkData.title && tempLinkData.url) {
      try {
        await updateQuickLink({ ...tempLinkData } as QuickLink);
        setQuickLinks(await getQuickLinks());
        setEditingLinkId(null);
        setTempLinkData({});
      } catch (e) { alert("Error al guardar."); }
    }
  };

  // --- CONTACT CONFIG MANAGEMENT ---
  const handleSaveContactInfo = async () => {
    if (!canManage) return;
    try {
      await saveContactInfo(contactInfo);
      alert("Información de contacto actualizada correctamente.");
    } catch (e) { alert("Error al guardar configuración."); }
  };

  if (isLoggedIn) {
    return (
      <div className="min-h-screen bg-gray-50 flex">
        {/* Sidebar */}
        <div className="w-64 bg-sepri-dark text-white p-6 hidden md:block">
          <div className="flex items-center gap-3 mb-8">
            <Settings className="text-sepri-yellow" />
            <h1 className="font-bold text-lg">Panel Admin</h1>
          </div>

          <nav className="space-y-2">
            <button onClick={() => setActiveTab('news')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'news' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}>
              <Newspaper size={18} /> Noticias
            </button>
            <button onClick={() => setActiveTab('protocols')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'protocols' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}>
              <Briefcase size={18} /> Protocolos
            </button>
            <button onClick={() => setActiveTab('popups')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'popups' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}>
              <MessageSquare size={18} /> Popups
            </button>
            <button onClick={() => setActiveTab('forms')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'forms' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}>
              <FileText size={18} /> Formularios
            </button>
            <button onClick={() => setActiveTab('links')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'links' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}>
              <LinkIcon size={18} /> Enlaces Rápidos
            </button>
            <button onClick={() => setActiveTab('config')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'config' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}>
              <Settings size={18} /> Configuración
            </button>
            {currentRole === 'CREATOR' && (
              <button onClick={() => setActiveTab('creator')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'creator' ? 'bg-purple-700' : 'hover:bg-gray-800'}`}>
                <Key size={18} /> Roles
              </button>
            )}
          </nav>

          <button onClick={handleLogout} className="mt-8 text-red-400 flex items-center gap-2 hover:text-red-300">
            <LogOut size={18} /> Cerrar Sesión
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 p-8 overflow-y-auto relative">
          <h2 className="text-2xl font-bold text-gray-800 mb-6 border-b pb-4">
            {activeTab === 'news' && 'Gestión de Noticias'}
            {activeTab === 'protocols' && 'Gestión de Protocolos (Eventos)'}
            {activeTab === 'popups' && 'Gestión de Popups'}
            {activeTab === 'forms' && 'Creador de Formularios'}
            {activeTab === 'links' && 'Gestión de Enlaces Rápidos (Footer)'}
            {activeTab === 'config' && 'Configuración General / Contacto'}
            {activeTab === 'creator' && 'Zona de Creador'}
          </h2>

          {/* NEWS TAB */}
          {activeTab === 'news' && (
            <div>
               <div className="mb-4">
                 <button onClick={() => { setCurrentNews({}); setIsEditingNews(true); }} className="bg-sepri-medium text-white px-4 py-2 rounded flex items-center gap-2">
                   <Plus size={18} /> Nueva Noticia
                 </button>
               </div>

               {isEditingNews && (
                 <div className="bg-white p-6 rounded-lg shadow-md mb-6 border border-gray-200">
                   <h3 className="font-bold mb-4">{currentNews.id ? 'Editar Noticia' : 'Nueva Noticia'}</h3>
                   <div className="grid grid-cols-1 gap-4">
                     <input 
                        type="text" placeholder="Título" className="border p-2 rounded" 
                        value={currentNews.title || ''} onChange={e => setCurrentNews({...currentNews, title: e.target.value})}
                     />
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <select 
                            className="border p-2 rounded"
