               </Link>
            </div>
          </div>

          <div className="relative overflow-hidden">
            <div 
              className="flex transition-transform duration-700 ease-in-out"
              style={{ transform: `translateX(-${currentNewsIndex * 100}%)` }}
            >
              {news.map((n) => (
                <div key={n.id} className="min-w-full flex-shrink-0 px-1">
                  <div className="bg-gray-50 rounded-xl p-5 md:p-8 border border-gray-100 flex flex-col md:flex-row gap-6 items-center md:items-stretch min-h-[300px] md:min-h-[220px]">
                    {/* Fixed size image container */}
                    <div className="w-full md:w-56 h-48 md:h-auto bg-gray-200 rounded-lg overflow-hidden flex-shrink-0 shadow-sm border border-gray-200">
                      {n.imageUrl ? (
                        <img src={n.imageUrl} alt={n.title} className="w-full h-full object-cover" />
                      ) : (
                        <div className="w-full h-full flex flex-col items-center justify-center text-gray-400 bg-gray-100 p-4">
                          <Newspaper size={32} className="opacity-30 mb-2" />
                          <span className="text-[10px] uppercase font-bold tracking-widest">Sin Imagen</span>
                        </div>
                      )}
                    </div>

                    {/* Content area with fixed layout */}
                    <div className="flex-1 flex flex-col justify-center text-center md:text-left py-2">
                      <div className="flex items-center justify-center md:justify-start gap-2 mb-3">
                        <span className={`text-[10px] uppercase tracking-widest font-black px-3 py-1 rounded-full shadow-sm ${
                          n.category === 'Importante' ? 'bg-red-600 text-white' : 'bg-sepri-medium text-white'
                        }`}>
                          {n.category}
                        </span>
                        <span className="text-xs text-gray-400 font-bold">{n.date}</span>
                      </div>

                      <h3 className="font-bold text-sepri-dark mb-2 text-xl md:text-2xl leading-tight line-clamp-1">
                        {n.title}
                      </h3>

                      <div className="text-sm md:text-base text-gray-600 mb-6 flex-grow">
                        <p className="line-clamp-2 md:line-clamp-3">
                          {truncateText(n.summary.split('\n')[0], 85)}
                        </p>
                      </div>

                      <div className="mt-auto">
                        <Link 
                          to="/noticias" 
                          className="inline-flex items-center bg-sepri-medium hover:bg-sepri-dark text-white px-6 py-3 rounded-xl font-bold text-xs uppercase tracking-widest transition-all shadow-md active:scale-95 group"
                        >
                          Leer noticia principal <ArrowRight size={14} className="ml-2 group-hover:translate-x-1 transition-transform" />
                        </Link>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
              {news.length === 0 && (
                <div className="min-w-full text-gray-500 text-center py-20 bg-gray-50 rounded-xl border border-dashed">
                   No hay noticias recientes para mostrar.
                </div>
              )}
            </div>

            {/* Dots indicator */}
            {news.length > 1 && (
              <div className="flex justify-center gap-2 mt-8">
                {news.map((_, idx) => (
                  <button 
                    key={idx} 
                    onClick={() => setCurrentNewsIndex(idx)}
                    className={`h-2 rounded-full transition-all duration-300 ${currentNewsIndex === idx ? 'w-10 bg-sepri-yellow' : 'w-2 bg-gray-300 hover:bg-gray-400'}`}
                    aria-label={`Ir a noticia ${idx + 1}`}
                  />
                ))}
              </div>
            )}
          </div>
        </div>
      </section>

      {/* Event Grid Section */}
      <section className="container mx-auto px-4 mb-20">
        <div className="text-center mb-12">
          <h2 className="text-3xl font-bold text-sepri-dark mb-4">Gestión de Protocolos</h2>
          <p className="text-gray-600 max-w-2xl mx-auto">
            Selecciona el tipo de evento que vas a realizar para iniciar el proceso de autorización y conocer los requisitos de seguridad.
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {events.map((event) => (
            <div key={event.id} className="bg-white rounded-2xl p-8 shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-gray-100 flex flex-col items-center text-center group overflow-hidden relative">
              <div className="mb-6 relative z-10">
                 {event.imageUrl ? (
                    <div className="w-24 h-24 rounded-full overflow-hidden border-4 border-sepri-bg shadow-md">
                        <img src={event.imageUrl} alt={event.title} className="w-full h-full object-cover" />
                    </div>
                 ) : (
                    <div className="bg-sepri-bg p-4 rounded-full group-hover:bg-sepri-yellow transition-colors duration-300">
                        <DynamicIcon name={event.iconName} className="w-10 h-10 text-sepri-medium group-hover:text-sepri-dark" />
                    </div>
                 )}
              </div>

              <h3 className="text-xl font-bold text-sepri-dark mb-3 relative z-10">{event.title}</h3>
              <p className="text-gray-500 text-sm mb-8 flex-grow relative z-10">
                {event.description}
              </p>
              <Link 
                to={`/event/${event.id}`} 
                className="w-full bg-sepri-medium hover:bg-sepri-dark text-white font-bold py-3 px-6 rounded-xl transition-colors flex justify-center items-center relative z-10 shadow-md"
              >
                Iniciar Proceso <ChevronRight size={18} className="ml-2" />
              </Link>
            </div>
          ))}
        </div>
      </section>

      {/* Moto Banner */}
      <section className="bg-sepri-dark py-16 text-center">
        <div className="container mx-auto px-4">
          <Icons.Quote className="w-12 h-12 text-sepri-yellow mx-auto mb-6 opacity-50" />
          <h2 className="text-2xl md:text-4xl font-bold text-white max-w-4xl mx-auto leading-tight">
            "La seguridad se trata de hacer lo correcto, incluso si nadie está mirando"
          </h2>
        </div>
      </section>
    </div>
  );
};

export default Home;

export interface NewsItem {
  id: string;
  title: string;
  date: string;
  summary: string;
  category: 'Importante' | 'Evento' | 'Novedad';
  imageUrl?: string;
}

export interface Step {
  id: string;
  title: string;
  description: string;
  deadline?: string;
  isDownloadable?: boolean;
  downloadUrl?: string;
  requiresUpload?: boolean;
  isCustom?: boolean; 
  order: number;
}

export interface Question {
  id: string;
  text: string;
  triggerSteps: string[]; 
  isEnabled?: boolean;
  yesContent?: string; // Nuevo: Contenido si la respuesta es SÍ
  noContent?: string;  // Nuevo: Contenido si la respuesta es NO
}

export interface ProtocolAlert { // Nuevo: Modelo de alerta para protocolos
  id: string;
  message: string;
  type: 'info' | 'warning' | 'danger';
  active: boolean;
}

export interface EventType {
  id: string;
  title: string;
  iconName: string;
  description: string;
  baseSteps: Step[];
  questions: Question[];
  imageUrl?: string;
  documentUrl?: string;
  alerts?: ProtocolAlert[]; // Nuevo: Alertas asociadas al protocolo
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export type UserRole = 'USER' | 'ADMIN' | 'CREATOR';

export interface User {
  username: string;
  role: UserRole;
}

export interface UserAccount {
  id: string;
  name: string;
  email: string;
  passwordHash: string;
  role: UserRole;
}

export interface PopupConfig {
  id: string;
  title: string;
  content: string;
  isEnabled: boolean;
  type: 'info' | 'warning' | 'alert';
}

export type FormFieldType = 'text' | 'textarea' | 'checkbox' | 'select';

export interface FormField {
  id: string;
  label: string;
  type: FormFieldType;
  options?: string[];
  required?: boolean;
}

export interface FormTemplate {
  id: string;
  eventId: string;
  title: string;
  description?: string;
  fields: FormField[];
}

export interface QuickLink {
  id: string;
  title: string;
  url: string;
  isEnabled: boolean;
}

export interface ContactInfo {
  coordinatorName: string;
  coordinatorPhone: string;
  assistantName: string;
  assistantPhone: string;
  email: string;
  address: string;
  facebookUrl?: string;
  instagramUrl?: string;
  youtubeUrl?: string;
  logoUrl?: string;
  heroImageUrl?: string;
}

import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ArrowLeft, Download, CheckCircle, AlertCircle, FileText, Plus, Save, Clock, Edit2, File, AlertTriangle, Info } from 'lucide-react';
import { EXTRA_STEPS } from '../constants';
import { Step, UserRole, FormTemplate, EventType, ProtocolAlert } from '../types';
import { getEvents, updateEventStep, getForms } from '../services/dataService';

const EventProcessPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [answers, setAnswers] = useState<Record<string, boolean>>({});
  const [currentSteps, setCurrentSteps] = useState<Step[]>([]);
  const [downloadedItems, setDownloadedItems] = useState<Set<string>>(new Set());

  const [event, setEvent] = useState<EventType | null>(null);
  const [loading, setLoading] = useState(true);

  const [userRole, setUserRole] = useState<UserRole>('USER');
  const [editingStep, setEditingStep] = useState<Step | null>(null);

  const [availableForms, setAvailableForms] = useState<FormTemplate[]>([]);
  const [activeForm, setActiveForm] = useState<FormTemplate | null>(null);
  const [formResponses, setFormResponses] = useState<Record<string, string>>({});

  useEffect(() => {
    const loadData = async () => {
        const storedRole = localStorage.getItem('sepri_user_role') as UserRole;
        if (storedRole) setUserRole(storedRole);

        if (id) {
            const allEvents = await getEvents();
            const foundEvent = allEvents.find(e => e.id === id);
            setEvent(foundEvent || null);

            const allForms = await getForms();
            setAvailableForms(allForms.filter(f => f.eventId === id));
        }
        setLoading(false);
    };
    loadData();
  }, [id]);

  useEffect(() => {
    if (!event) return;

    let steps = [...event.baseSteps];

    Object.keys(answers).forEach((questionId) => {
      if (answers[questionId]) {
        const question = event.questions.find(q => q.id === questionId);
        if (question) {
          question.triggerSteps.forEach(stepId => {
            if (EXTRA_STEPS[stepId] && !steps.find(s => s.id === stepId)) {
              const extraStep = { ...EXTRA_STEPS[stepId], order: 99 };
              steps.push(extraStep);
            }
          });
        }
      }
    });

    steps.sort((a, b) => (a.order || 0) - (b.order || 0));
    setCurrentSteps(steps);
  }, [answers, event]);

  if (loading) {
      return <div className="min-h-screen flex justify-center items-center">Cargando...</div>;
  }

  const canManage = userRole === 'ADMIN' || userRole === 'CREATOR';

  if (!event) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center text-center px-4">
        <AlertCircle size={64} className="text-red-500 mb-4" />
        <h1 className="text-2xl font-bold text-gray-800">Evento no encontrado</h1>
        <Link to="/" className="mt-4 text-sepri-medium hover:underline">Volver al inicio</Link>
      </div>
    );
  }

  const handleAnswer = (questionId: string, value: boolean) => {
    setAnswers(prev => ({ ...prev, [questionId]: value }));
  };

  const handleDownload = (stepId: string, url?: string) => {
    const newDownloads = new Set(downloadedItems);
    newDownloads.add(stepId);
    setDownloadedItems(newDownloads);

    if (url) {
      window.open(url, '_blank');
    } else {
      alert("Este formato estará disponible pronto o no tiene enlace configurado.");
    }
  };

  const handleDownloadGeneralDoc = () => {
     if (event.documentUrl) {
       window.open(event.documentUrl, '_blank');
     } else {
       alert('No hay documento adjunto.');
     }
  };

  const handleSaveStep = async (step: Step) => {
    if (!canManage) return;
    if (!step.title) {
        alert("El título del ítem es obligatorio.");
        return;
    }

    if (step.downloadUrl && !step.downloadUrl.match(/^https?:\/\//)) {
        alert("La URL debe comenzar con http:// o https://");
        return;
    }

    try {
      await updateEventStep(event.id, step);
      setEditingStep(null);
      const allEvents = await getEvents();
      const foundEvent = allEvents.find(e => e.id === id);
      setEvent(foundEvent || null);
    } catch (e) {
      alert("No se pudo guardar el cambio. Verifica tus permisos.");
    }
  };

  const handleOpenForm = (form: FormTemplate) => {
    setActiveForm(form);
    setFormResponses({});
  };

  const handleDownloadForm = () => {
    if (!activeForm) return;

    let content = `FORMULARIO: ${activeForm.title}\nEVENTO: ${event.title}\nFECHA: ${new Date().toLocaleString()}\n\nRESPUESTAS:\n----------------\n`;

    activeForm.fields.forEach(field => {
       content += `${field.label}: ${formResponses[field.id] || 'N/A'}\n`;
    });

    const element = document.createElement("a");
    const file = new Blob([content], {type: 'text/plain'});
    element.href = URL.createObjectURL(file);
    element.download = `${activeForm.title.replace(/\s+/g, '_')}_diligenciado.txt`;
    document.body.appendChild(element); 
    element.click();
    document.body.removeChild(element);

    setActiveForm(null);
    alert("Formulario descargado correctamente.");
  };

  const AlertIcon = ({ type }: { type: string }) => {
    switch (type) {
      case 'danger': return <AlertCircle className="text-red-500" size={20} />;
      case 'warning': return <AlertTriangle className="text-sepri-yellow" size={20} />;
      default: return <Info className="text-sepri-medium" size={20} />;
    }
  };

  return (
    <div className="min-h-screen bg-sepri-bg pb-20">
      <div className="bg-sepri-medium text-white py-10">
        <div className="container mx-auto px-4">
          <div className="flex justify-between items-start">
            <div>
              <Link to="/" className="inline-flex items-center text-blue-200 hover:text-white mb-4 transition-colors">
                <ArrowLeft size={18} className="mr-2" /> Volver
              </Link>
              <h1 className="text-3xl md:text-4xl font-bold mb-2">Protocolo: {event.title}</h1>
              <p className="text-blue-100 max-w-2xl">{event.description}</p>

              {event.documentUrl && (
                <button onClick={handleDownloadGeneralDoc} className="mt-4 bg-sepri-yellow text-sepri-dark px-4 py-2 rounded-lg font-bold text-sm inline-flex items-center hover:bg-yellow-400 transition-colors shadow-md">
                   <File size={16} className="mr-2"/> Descargar Protocolo General
                </button>
              )}
            </div>
            {canManage && (
              <div className="bg-sepri-yellow text-sepri-dark px-4 py-2 rounded-lg font-bold text-xs shadow-lg">
                MODO EDICIÓN ACTIVO
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="container mx-auto px-4 -mt-8">
        {/* Sección de Alertas Dinámicas */}
        {event.alerts && event.alerts.some(a => a.active) && (
          <div className="mb-8 space-y-3">
            {event.alerts.filter(a => a.active).map(alert => (
              <div key={alert.id} className={`flex items-center gap-3 p-4 rounded-xl shadow-md border-l-4 bg-white animate-fade-in ${
                alert.type === 'danger' ? 'border-red-500' : alert.type === 'warning' ? 'border-sepri-yellow' : 'border-sepri-medium'
              }`}>
                <AlertIcon type={alert.type} />
                <p className="text-gray-800 font-medium text-sm">{alert.message}</p>
              </div>
            ))}
          </div>
        )}

        <div className="flex flex-col lg:flex-row gap-8">

          <div className="lg:w-1/3 space-y-8">
            <div className="bg-white rounded-xl shadow-lg p-6 sticky top-24">
              <h2 className="text-xl font-bold text-sepri-dark mb-6 flex items-center">
                <AlertCircle className="mr-2 text-sepri-yellow" />
                Detalles del Evento
              </h2>
              <div className="space-y-6">
                {event.questions.filter(q => q.isEnabled !== false).map((q) => (
                  <div key={q.id} className="p-4 border border-gray-100 rounded-lg bg-gray-50 transition-all">
                    <p className="font-medium text-gray-700 mb-3 text-sm">{q.text}</p>
                    <div className="flex gap-3 mb-3">
                      <button onClick={() => handleAnswer(q.id, true)} className={`flex-1 py-2 rounded-lg text-sm font-semibold transition-all ${answers[q.id] === true ? 'bg-sepri-green text-white shadow-md' : 'bg-white border border-gray-300 text-gray-600 hover:bg-gray-100'}`}>SÍ</button>
                      <button onClick={() => handleAnswer(q.id, false)} className={`flex-1 py-2 rounded-lg text-sm font-semibold transition-all ${answers[q.id] === false ? 'bg-gray-700 text-white shadow-md' : 'bg-white border border-gray-300 text-gray-600 hover:bg-gray-100'}`}>NO</button>
                    </div>

                    {/* Contenido Condicional "Si Entonces / No Entonces" */}
                    {answers[q.id] === true && q.yesContent && (
                      <div className="mt-3 p-3 bg-green-50 text-green-800 text-xs rounded-lg border border-green-100 animate-fade-in">
                        <div className="font-bold mb-1 uppercase tracking-tighter">Instrucción Adicional (SÍ):</div>
                        {q.yesContent}
                      </div>
                    )}
                    {answers[q.id] === false && q.noContent && (
                      <div className="mt-3 p-3 bg-gray-100 text-gray-700 text-xs rounded-lg border border-gray-200 animate-fade-in">
                        <div className="font-bold mb-1 uppercase tracking-tighter">Nota (NO):</div>
                        {q.noContent}
                      </div>
                    )}
                  </div>
                ))}
                {event.questions.filter(q => q.isEnabled !== false).length === 0 && (
                   <p className="text-gray-400 text-sm text-center">No hay preguntas adicionales para este protocolo.</p>
                )}
              </div>
            </div>

            {availableForms.length > 0 && (
              <div className="bg-white rounded-xl shadow-lg p-6">
                 <h2 className="text-xl font-bold text-sepri-dark mb-4 flex items-center">
                   <FileText className="mr-2 text-blue-500" /> Formularios Disponibles
                 </h2>
                 <ul className="space-y-3">
                   {availableForms.map(form => (
                     <li key={form.id} className="p-3 border rounded hover:bg-gray-50 flex justify-between items-center">
                       <div>
                         <p className="font-bold text-sm text-gray-800">{form.title}</p>
                         <p className="text-xs text-gray-500">{form.description}</p>
                       </div>
                       <button onClick={() => handleOpenForm(form)} className="text-sepri-medium text-sm font-semibold hover:underline">
                         Diligenciar
                       </button>
                     </li>
                   ))}
                 </ul>
              </div>
            )}
          </div>

          <div className="lg:w-2/3">
            <div className="bg-white rounded-xl shadow-lg overflow-hidden">
              <div className="bg-gray-50 p-6 border-b border-gray-100 flex justify-between items-center">
                <h2 className="text-xl font-bold text-sepri-dark">Ruta de Cumplimiento</h2>
                <div className="flex items-center gap-3">
                  {canManage && (
                    <button onClick={() => { setEditingStep({ id: `new-${Date.now()}`, title: '', description: '', isCustom: true, order: currentSteps.length } as Step); }} className="bg-sepri-dark text-white p-2 rounded-full hover:bg-gray-800 transition-colors" title="Agregar Ítem">
                      <Plus size={18} />
                    </button>
                  )}
                  <span className="bg-sepri-medium text-white px-3 py-1 rounded-full text-xs font-bold">
                    {currentSteps.length} Pasos
                  </span>
                </div>
              </div>

              {editingStep && canManage && (
                <div className="p-6 bg-blue-50 border-b border-blue-100 animate-fade-in">
                  <h3 className="font-bold text-sepri-dark mb-4">{editingStep.id.startsWith('new') ? 'Agregar Ítem' : 'Editar Ítem'}</h3>
                  <div className="space-y-4">
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-1">Título</label>
                        <input type="text" placeholder="Ej: Documentación Vehículo" className="w-full p-2 border rounded" value={editingStep.title} onChange={e => setEditingStep({...editingStep, title: e.target.value})} />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-1">Descripción</label>
                        <input type="text" placeholder="Ej: Copia de SOAT y Tecnomecánica" className="w-full p-2 border rounded" value={editingStep.description} onChange={e => setEditingStep({...editingStep, description: e.target.value})} />
                    </div>

                    <div className="bg-white p-3 border rounded-lg border-blue-200">
                        <label className="block text-sm font-bold text-sepri-dark mb-1">URL del Documento del Ítem (Drive / OneDrive / URL)</label>
                        <input 
                            type="text" 
                            placeholder="https://drive.google.com/..." 
                            className="w-full p-2 border rounded border-gray-300 focus:border-sepri-medium focus:ring-1 focus:ring-sepri-medium outline-none" 
                            value={editingStep.downloadUrl || ''} 
                            onChange={e => setEditingStep({...editingStep, downloadUrl: e.target.value, isDownloadable: !!e.target.value})} 
                        />
                        <p className="text-xs text-gray-500 mt-1">Este enlace se abrirá cuando el usuario haga clic en "Descargar Formato".</p>
                    </div>

                    <div className="flex justify-end gap-2 pt-2">
                      <button onClick={() => setEditingStep(null)} className="px-4 py-2 text-gray-600 text-sm hover:bg-gray-100 rounded">Cancelar</button>
                      <button onClick={() => handleSaveStep(editingStep)} className="px-4 py-2 bg-sepri-medium text-white rounded text-sm flex items-center hover:bg-sepri-dark shadow-sm">
                        <Save size={16} className="mr-2" /> Guardar Ítem
                      </button>
                    </div>
                  </div>
                </div>
              )}

              <div className="divide-y divide-gray-100">
                {currentSteps.map((step, index) => {
                  const isDownloaded = downloadedItems.has(step.id);
                  return (
                    <div key={step.id} className="p-6 hover:bg-gray-50 transition-colors relative group">
                      {canManage && (
                        <button onClick={() => setEditingStep(step)} className="absolute top-4 right-4 text-blue-400 hover:text-blue-600 opacity-0 group-hover:opacity-100 transition-opacity bg-white p-1 rounded-full shadow-sm" title="Editar Ítem">
                          <Edit2 size={18} />
                        </button>
                      )}

                      <div className="flex items-start gap-4">
                        <div className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm shadow-sm transition-colors ${isDownloaded ? 'bg-sepri-green text-white' : 'bg-sepri-medium text-white'}`}>
                          {isDownloaded ? <CheckCircle size={18} /> : index + 1}
                        </div>
                        <div className="flex-1">
                          <div className="flex flex-col md:flex-row md:justify-between md:items-start gap-2">
                            <h3 className="text-lg font-bold text-gray-800 flex items-center">
                              {step.title}
                              {isDownloaded && <span className="ml-2 text-xs text-sepri-green bg-green-50 px-2 py-0.5 rounded border border-green-100">Descargado</span>}
                            </h3>
                            {step.deadline && <span className="inline-flex items-center text-xs font-semibold text-red-500 bg-red-50 px-2 py-1 rounded border border-red-100 whitespace-nowrap"><Clock size={12} className="mr-1" /> {step.deadline}</span>}
                          </div>
                          <p className="text-gray-600 text-sm mt-2 mb-4">{step.description}</p>

                          <div className="flex flex-wrap gap-3">
                            {step.isDownloadable && (
                              <button onClick={() => handleDownload(step.id, step.downloadUrl)} className={`inline-flex items-center px-4 py-2 rounded-lg text-sm font-medium transition-colors ${isDownloaded ? 'bg-green-100 text-green-700 hover:bg-green-200' : 'bg-sepri-light/10 text-sepri-medium hover:bg-sepri-light/20'}`}>
                                {isDownloaded ? <><CheckCircle size={16} className="mr-2" /> Descargar Nuevamente</> : <><Download size={16} className="mr-2" /> Descargar Formato</>}
                              </button>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
                {currentSteps.length === 0 && <p className="p-8 text-center text-gray-500">No hay pasos definidos para este protocolo.</p>}
              </div>
            </div>
          </div>

        </div>
      </div>

      {activeForm && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg p-6 animate-fade-in-up max-h-[90vh] overflow-y-auto">
             <div className="flex justify-between items-center mb-4">
               <h3 className="text-xl font-bold text-sepri-dark">{activeForm.title}</h3>
               <button onClick={() => setActiveForm(null)} className="text-gray-400 hover:text-gray-600"><Plus className="rotate-45" size={24}/></button>
             </div>
             <p className="text-gray-600 text-sm mb-6">{activeForm.description}</p>

             <div className="space-y-4">
               {activeForm.fields.map(field => (
                 <div key={field.id}>
                   <label className="block text-sm font-bold text-gray-700 mb-1">{field.label}</label>
                   {field.type === 'textarea' ? (
                     <textarea className="w-full border p-2 rounded" rows={3} onChange={(e) => setFormResponses({...formResponses, [field.id]: e.target.value})} />
                   ) : field.type === 'checkbox' ? (
                     <input type="checkbox" className="h-5 w-5" onChange={(e) => setFormResponses({...formResponses, [field.id]: e.target.checked ? 'Si' : 'No'})} />
                   ) : (
                     <input type="text" className="w-full border p-2 rounded" onChange={(e) => setFormResponses({...formResponses, [field.id]: e.target.value})} />
                   )}
                 </div>
               ))}
             </div>

             <div className="mt-8 flex justify-end gap-3">
               <button onClick={() => setActiveForm(null)} className="px-4 py-2 text-gray-500">Cancelar</button>
               <button onClick={handleDownloadForm} className="bg-sepri-medium text-white px-6 py-2 rounded-lg font-bold hover:bg-sepri-dark">
                 Descargar Diligenciado
               </button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default EventProcessPage;

import React, { useState, useEffect } from 'react';
import { Lock, User, ChevronRight, Key, LogOut, Settings, Newspaper, MessageSquare, FileText, Plus, Trash2, Edit2, Save, ToggleLeft, ToggleRight, Check, Image as ImageIcon, Briefcase, File, X, List, ExternalLink, Link as LinkIcon, Phone, Share2, ShieldAlert, Copy, ChevronUp, ChevronDown, Upload, AlertCircle } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { DEFAULT_CONTACT_INFO } from '../constants';
import { UserRole, NewsItem, PopupConfig, FormTemplate, FormField, EventType, Question, Step, QuickLink, ContactInfo, UserAccount, ProtocolAlert } from '../types';
import { getNews, saveNews, getPopups, togglePopup, updatePopup, getForms, addForm, deleteForm, getEvents, saveEvents, addEvent, deleteEvent, getQuickLinks, addQuickLink, deleteQuickLink, updateQuickLink, getContactInfo, saveContactInfo, authenticateUser, getUsers, resetUserPassword, initUsers } from '../services/dataService';

const AdminLogin: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentRole, setCurrentRole] = useState<UserRole>('USER');
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState<'news' | 'popups' | 'forms' | 'protocols' | 'links' | 'config' | 'creator'>('news');
  const [news, setNews] = useState<NewsItem[]>([]);
  const [popups, setPopups] = useState<PopupConfig[]>([]);
  const [forms, setForms] = useState<FormTemplate[]>([]);
  const [events, setEvents] = useState<EventType[]>([]);
  const [quickLinks, setQuickLinks] = useState<QuickLink[]>([]);
  const [contactInfo, setContactInfo] = useState<ContactInfo>(DEFAULT_CONTACT_INFO);

  const [users, setUsers] = useState<UserAccount[]>([]);
  const [newGeneratedPassword, setNewGeneratedPassword] = useState<string | null>(null);
  const [isResetting, setIsResetting] = useState<string | null>(null);

  const [isCreatingForm, setIsCreatingForm] = useState(false);
  const [newForm, setNewForm] = useState<Partial<FormTemplate>>({ title: '', fields: [] });
  const [newField, setNewField] = useState<Partial<FormField>>({ label: '', type: 'text' });

  const [isEditingNews, setIsEditingNews] = useState(false);
  const [currentNews, setCurrentNews] = useState<Partial<NewsItem>>({});

  const [isEditingProtocol, setIsEditingProtocol] = useState(false);
  const [currentProtocol, setCurrentProtocol] = useState<Partial<EventType>>({ baseSteps: [], questions: [], alerts: [] });
  const [newQuestion, setNewQuestion] = useState<Partial<Question>>({ text: '', yesContent: '', noContent: '' });

  // Alertas locales para el protocolo en edición
  const [newAlert, setNewAlert] = useState<Partial<ProtocolAlert>>({ message: '', type: 'info', active: true });

  const [newStep, setNewStep] = useState<Partial<Step>>({ title: '', description: '', deadline: '', downloadUrl: '' });

  const [newLink, setNewLink] = useState<Partial<QuickLink>>({ title: '', url: '' });
  const [editingLinkId, setEditingLinkId] = useState<string | null>(null);
  const [tempLinkData, setTempLinkData] = useState<Partial<QuickLink>>({});

  const [editingPopupId, setEditingPopupId] = useState<string | null>(null);
  const [tempPopupData, setTempPopupData] = useState<Partial<PopupConfig>>({});

  useEffect(() => {
    const storedRole = localStorage.getItem('sepri_user_role');
    if (storedRole && (storedRole === 'ADMIN' || storedRole === 'CREATOR')) {
      setIsLoggedIn(true);
      setCurrentRole(storedRole as UserRole);
      loadData();
    }
  }, []);

  const loadData = async () => {
    setNews(await getNews());
    setPopups(await getPopups());
    setForms(await getForms());
    setEvents(await getEvents());
    setQuickLinks(await getQuickLinks());
    const contact = await getContactInfo();
    if(contact) setContactInfo(contact);

    if (currentRole === 'CREATOR') {
      setUsers(getUsers()); 
    }
  };

  useEffect(() => {
    if (activeTab === 'creator') {
        setUsers(getUsers());
    }
  }, [activeTab]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
        const role = await authenticateUser(email, password);
        if (role) {
            localStorage.setItem('sepri_user_role', role);
            setCurrentRole(role);
            setIsLoggedIn(true);
            loadData();
        } else {
            alert("Credenciales incorrectas.");
        }
    } catch (error) {
        console.error(error);
        alert("Error al iniciar sesión.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('sepri_user_role');
    setIsLoggedIn(false);
    setCurrentRole('USER');
    navigate('/');
  };

  const canManage = currentRole === 'ADMIN' || currentRole === 'CREATOR';

  const handleMoveStep = (index: number, direction: 'up' | 'down') => {
    if (!currentProtocol.baseSteps) return;
    const newSteps = [...currentProtocol.baseSteps];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;

    if (targetIndex < 0 || targetIndex >= newSteps.length) return;
    [newSteps[index], newSteps[targetIndex]] = [newSteps[targetIndex], newSteps[index]];
    newSteps.forEach((s, i) => s.order = i);
    setCurrentProtocol(prev => ({ ...prev, baseSteps: newSteps }));
  };

  const handleSaveProtocol = async () => {
    if (!canManage) return;
    if (!currentProtocol.title?.trim() || !currentProtocol.description?.trim()) {
      alert("Título y descripción requeridos");
      return;
    }

    try {
      const protocolToSave: EventType = {
        id: currentProtocol.id || `evt-${Date.now()}`,
        title: currentProtocol.title!,
        description: currentProtocol.description!,
        iconName: currentProtocol.iconName || 'FileText',
        imageUrl: currentProtocol.imageUrl,
        documentUrl: currentProtocol.documentUrl,
        baseSteps: (currentProtocol.baseSteps || []).map((s, i) => ({ ...s, order: i })),
        questions: currentProtocol.questions || [],
        alerts: currentProtocol.alerts || []
      };

      if (currentProtocol.id) {
        const updatedEvents = events.map(e => e.id === currentProtocol.id ? protocolToSave : e);
        await saveEvents(updatedEvents);
        setEvents(updatedEvents);
      } else {
        await addEvent(protocolToSave);
        setEvents(await getEvents());
      }
      setIsEditingProtocol(false);
      setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] });
      alert("Protocolo guardado exitosamente.");
    } catch (error) {
      console.error("Error saving protocol:", error);
      alert("Error al guardar: Revisa tu conexión y permisos.");
    }
  };

  // Gestión de Alertas del Protocolo
  const handleAddAlert = () => {
    if (!newAlert.message) return;
    const alert: ProtocolAlert = {
      id: `alert-${Date.now()}`,
      message: newAlert.message,
      type: newAlert.type as any || 'info',
      active: true
    };
    setCurrentProtocol(prev => ({ ...prev, alerts: [...(prev.alerts || []), alert] }));
    setNewAlert({ message: '', type: 'info', active: true });
  };

  const handleDeleteAlert = (id: string) => {
    setCurrentProtocol(prev => ({ ...prev, alerts: prev.alerts?.filter(a => a.id !== id) || [] }));
  };

  // Gestión de Preguntas
  const handleAddQuestionLocal = () => {
    if (!newQuestion.text) return;
    const q: Question = {
      id: `q-${Date.now()}`,
      text: newQuestion.text,
      yesContent: newQuestion.yesContent,
      noContent: newQuestion.noContent,
      triggerSteps: [], 
      isEnabled: true
    };
    setCurrentProtocol(prev => ({ ...prev, questions: [...(prev.questions || []), q] }));
    setNewQuestion({ text: '', yesContent: '', noContent: '' });
  };

  // --- RESTO DE FUNCIONES MANTENIDAS ---
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'news' | 'protocol_image' | 'hero' | 'logo') => {
    const file = e.target.files?.[0];
    if (file) {
      const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
      if (!validTypes.includes(file.type)) {
        alert("Por favor sube una imagen válida."); return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        if (target === 'news') setCurrentNews(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'protocol_image') setCurrentProtocol(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'hero') setContactInfo(prev => ({ ...prev, heroImageUrl: result }));
        else if (target === 'logo') setContactInfo(prev => ({ ...prev, logoUrl: result }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveNews = async () => {
    if (!canManage) return;
    if (!currentNews.title || !currentNews.summary) return;
    let updatedNews = [...news];
    if (currentNews.id) updatedNews = updatedNews.map(n => n.id === currentNews.id ? { ...n, ...currentNews } as NewsItem : n);
    else {
      updatedNews.unshift({
        id: Date.now().toString(), title: currentNews.title!, summary: currentNews.summary!,
        category: (currentNews.category as any) || 'Novedad', date: new Date().toLocaleDateString('es-CO'), ...currentNews
      } as NewsItem);
    }
    await saveNews(updatedNews); setNews(updatedNews); setIsEditingNews(false); setCurrentNews({});
  };

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <div className="w-64 bg-sepri-dark text-white p-6 hidden md:block">
        <div className="flex items-center gap-3 mb-8">
          <Settings className="text-sepri-yellow" />
          <h1 className="font-bold text-lg">Panel Admin</h1>
        </div>
        <nav className="space-y-2">
          <button onClick={() => setActiveTab('news')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'news' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Newspaper size={18} /> Noticias</button>
          <button onClick={() => setActiveTab('protocols')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'protocols' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Briefcase size={18} /> Protocolos</button>
          <button onClick={() => setActiveTab('popups')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'popups' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><MessageSquare size={18} /> Popups Gral</button>
          <button onClick={() => setActiveTab('forms')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'forms' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><FileText size={18} /> Formularios</button>
          <button onClick={() => setActiveTab('links')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'links' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><LinkIcon size={18} /> Enlaces</button>
          <button onClick={() => setActiveTab('config')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'config' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Settings size={18} /> Configuración</button>
        </nav>
        <button onClick={handleLogout} className="mt-8 text-red-400 flex items-center gap-2 hover:text-red-300"><LogOut size={18} /> Cerrar Sesión</button>
      </div>

      <div className="flex-1 p-8 overflow-y-auto relative">
        <h2 className="text-2xl font-bold text-gray-800 mb-6 border-b pb-4">
          {activeTab === 'news' && 'Gestión de Noticias'}
          {activeTab === 'protocols' && 'Gestión de Protocolos y Alertas'}
          {activeTab === 'popups' && 'Gestión de Popups Generales'}
          {activeTab === 'config' && 'Configuración General'}
        </h2>

        {activeTab === 'protocols' && (
          <div>
            {!isEditingProtocol ? (
              <>
                <div className="mb-6">
                  <button onClick={() => { setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] }); setIsEditingProtocol(true); }} className="bg-sepri-medium text-white px-4 py-2 rounded flex items-center gap-2 hover:bg-sepri-dark shadow-md transition-all">
                    <Plus size={18} /> Nuevo Protocolo
                  </button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {events.map(event => (
                    <div key={event.id} className="bg-white p-6 rounded-xl shadow border border-gray-100 flex flex-col hover:shadow-lg transition-shadow">
                      <h3 className="font-bold text-lg mb-2">{event.title}</h3>
                      <p className="text-xs text-gray-500 mb-4 flex-grow line-clamp-2">{event.description}</p>
                      <div className="flex justify-end gap-2 border-t pt-4">
                        <button onClick={() => { setCurrentProtocol(event); setIsEditingProtocol(true); }} className="text-blue-500 p-2 hover:bg-blue-50 rounded"><Edit2 size={18}/></button>
                        <button onClick={() => deleteEvent(event.id).then(() => getEvents().then(setEvents))} className="text-red-500 p-2 hover:bg-red-50 rounded"><Trash2 size={18}/></button>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            ) : (
              <div className="bg-white p-8 rounded-2xl shadow-xl border border-gray-200 animate-fade-in-up">
                <h3 className="text-xl font-bold mb-8 flex items-center gap-2"><Edit2 className="text-sepri-medium"/> {currentProtocol.id ? 'Editar Protocolo' : 'Nuevo Protocolo'}</h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
                  <div className="space-y-4">
                    <label className="block text-sm font-bold text-gray-700">Información Básica</label>
                    <input type="text" placeholder="Título del Protocolo" className="w-full border p-3 rounded-lg" value={currentProtocol.title || ''} onChange={e => setCurrentProtocol({...currentProtocol, title: e.target.value})} />
                    <textarea placeholder="Descripción detallada" className="w-full border p-3 rounded-lg" rows={3} value={currentProtocol.description || ''} onChange={e => setCurrentProtocol({...currentProtocol, description: e.target.value})} />
                  </div>

                  <div className="space-y-4">
                    <label className="block text-sm font-bold text-gray-700">Documentación y Medios</label>
                    <div className="flex flex-col gap-3">
                       <input type="text" placeholder="URL Documento General (Drive/OneDrive)" className="w-full border p-3 rounded-lg text-sm" value={currentProtocol.documentUrl || ''} onChange={e => setCurrentProtocol({...currentProtocol, documentUrl: e.target.value})} />
                       <label className="flex items-center justify-center border-2 border-dashed border-gray-200 p-4 rounded-xl cursor-pointer hover:bg-gray-50 text-gray-500 text-sm">
                          <ImageIcon size={20} className="mr-2" /> {currentProtocol.imageUrl ? 'Cambiar Imagen de Cabecera' : 'Subir Imagen de Cabecera'}
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleImageUpload(e, 'protocol_image')} />
                       </label>
                    </div>
                  </div>
                </div>

                {/* NUEVO: GESTIÓN DE ALERTAS DEL PROTOCOLO */}
                <div className="mb-10 p-6 bg-red-50 rounded-2xl border border-red-100">
                  <h4 className="font-bold text-red-800 mb-4 flex items-center gap-2"><AlertCircle size={20}/> Alertas del Protocolo</h4>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-4">
                    <input type="text" placeholder="Mensaje de la alerta..." className="md:col-span-2 border p-2 rounded-lg" value={newAlert.message || ''} onChange={e => setNewAlert({...newAlert, message: e.target.value})} />
                    <select className="border p-2 rounded-lg" value={newAlert.type || 'info'} onChange={e => setNewAlert({...newAlert, type: e.target.value as any})}>
                      <option value="info">Información (Azul)</option>
                      <option value="warning">Advertencia (Amarillo)</option>
                      <option value="danger">Crítica/Peligro (Rojo)</option>
                    </select>
                  </div>
                  <button onClick={handleAddAlert} className="bg-red-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-red-700 shadow-sm">Agregar Alerta</button>

                  <div className="mt-4 space-y-2">
                    {currentProtocol.alerts?.map(alert => (
                      <div key={alert.id} className="bg-white p-3 rounded-lg flex justify-between items-center border shadow-sm">
                        <span className={`text-xs font-bold px-2 py-1 rounded ${alert.type === 'danger' ? 'bg-red-100 text-red-600' : alert.type === 'warning' ? 'bg-yellow-100 text-yellow-600' : 'bg-blue-100 text-blue-600'}`}>
                          {alert.type.toUpperCase()}
                        </span>
                        <p className="flex-1 mx-4 text-sm text-gray-700">{alert.message}</p>
                        <button onClick={() => handleDeleteAlert(alert.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                      </div>
                    ))}
                  </div>
                </div>

                {/* NUEVO: GESTIÓN DE PREGUNTAS CON RAMIFICACIÓN SÍ/NO */}
                <div className="mb-10 p-6 bg-blue-50 rounded-2xl border border-blue-100">
                  <h4 className="font-bold text-sepri-dark mb-4 flex items-center gap-2"><List size={20}/> Preguntas y Ramificación (SÍ/NO)</h4>
                  <div className="space-y-4 mb-6">
                    <input type="text" placeholder="¿Pregunta para el usuario?" className="w-full border p-3 rounded-lg" value={newQuestion.text || ''} onChange={e => setNewQuestion({...newQuestion, text: e.target.value})} />
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="text-xs font-bold text-green-700 uppercase">Si responde SÍ, mostrar:</label>
                        <textarea placeholder="Instrucción si elige SÍ..." className="w-full border p-2 rounded-lg text-sm mt-1" rows={2} value={newQuestion.yesContent || ''} onChange={e => setNewQuestion({...newQuestion, yesContent: e.target.value})} />
                      </div>
                      <div>
                        <label className="text-xs font-bold text-gray-500 uppercase">Si responde NO, mostrar:</label>
                        <textarea placeholder="Instrucción si elige NO..." className="w-full border p-2 rounded-lg text-sm mt-1" rows={2} value={newQuestion.noContent || ''} onChange={e => setNewQuestion({...newQuestion, noContent: e.target.value})} />
                      </div>
                    </div>
                  </div>
                  <button onClick={handleAddQuestionLocal} className="bg-sepri-medium text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-sepri-dark">Agregar Pregunta</button>

                  <div className="mt-6 space-y-4">
                    {currentProtocol.questions?.map(q => (
                      <div key={q.id} className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm relative group">
                        <button onClick={() => handleDeleteQuestion(q.id)} className="absolute top-2 right-2 text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={16}/></button>
                        <p className="font-bold text-gray-800 mb-2">{q.text}</p>
                        <div className="flex gap-4">
                          <div className="flex-1 text-[10px] bg-green-50 p-2 rounded border border-green-100">
                             <span className="font-black text-green-700">SI → </span> {q.yesContent || <span className="italic text-gray-400">Sin contenido configurado</span>}
                          </div>
                          <div className="flex-1 text-[10px] bg-gray-50 p-2 rounded border border-gray-200">
                             <span className="font-black text-gray-600">NO → </span> {q.noContent || <span className="italic text-gray-400">Sin contenido configurado</span>}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="flex justify-end gap-3 mt-10 pt-6 border-t">
                  <button onClick={() => setIsEditingProtocol(false)} className="px-6 py-2 text-gray-500 hover:bg-gray-100 rounded-lg">Cancelar</button>
                  <button onClick={handleSaveProtocol} className="bg-green-600 text-white px-10 py-2 rounded-lg font-bold shadow-lg hover:bg-green-700 transition-all flex items-center gap-2"><Save size={18}/> Guardar Protocolo</button>
                </div>
              </div>
            )}
          </div>
        )}

        {/* TAB NEWS (Igual que el código anterior) */}
        {activeTab === 'news' && (
           <div className="space-y-6">
              <div className="flex justify-between items-center">
                 <button onClick={() => { setCurrentNews({}); setIsEditingNews(true); }} className="bg-sepri-medium text-white px-6 py-2 rounded-lg flex items-center gap-2 shadow hover:bg-sepri-dark transition-all">
                    <Plus size={18} /> Nueva Noticia
                 </button>
              </div>
              {isEditingNews && (
                 <div className="bg-white p-8 rounded-2xl shadow-xl border mb-10">
                    <h3 className="text-xl font-bold mb-6">{currentNews.id ? 'Editar Noticia' : 'Crear Noticia'}</h3>
                    <div className="grid grid-cols-1 gap-6">
                        <input type="text" placeholder="Título impactante" className="w-full border p-3 rounded-lg" value={currentNews.title || ''} onChange={e => setCurrentNews({...currentNews, title: e.target.value})} />
                        <div className="grid grid-cols-2 gap-4">
                           <select className="border p-3 rounded-lg" value={currentNews.category || 'Novedad'} onChange={e => setCurrentNews({...currentNews, category: e.target.value as any})}>
                              <option value="Novedad">Novedad</option>
                              <option value="Evento">Evento</option>
                              <option value="Importante">Importante</option>
                           </select>
                           <label className="flex items-center justify-center border-2 border-dashed border-gray-200 p-3 rounded-lg cursor-pointer hover:bg-gray-50 text-gray-400 text-xs">
                              <ImageIcon size={16} className="mr-2" /> {currentNews.imageUrl ? 'Cambiar Imagen' : 'Subir Imagen'}
                              <input type="file" accept="image/*" className="hidden" onChange={(e) => handleImageUpload(e, 'news')} />
                           </label>
                        </div>
                        <textarea placeholder="Resumen descriptivo de la noticia..." className="w-full border p-3 rounded-lg" rows={4} value={currentNews.summary || ''} onChange={e => setCurrentNews({...currentNews, summary: e.target.value})} />
                        <div className="flex justify-end gap-3 mt-4">
                           <button onClick={() => setIsEditingNews(false)} className="px-6 py-2 text-gray-400">Cancelar</button>
                           <button onClick={handleSaveNews} className="bg-sepri-medium text-white px-8 py-2 rounded-lg font-bold shadow-lg">Guardar Publicación</button>
                        </div>
                    </div>
                 </div>
              )}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {news.map(n => (
                  <div key={n.id} className="bg-white p-6 rounded-2xl shadow border flex gap-4">
                     <div className="w-20 h-20 bg-gray-100 rounded-xl overflow-hidden flex-shrink-0">
                        {n.imageUrl ? <img src={n.imageUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-gray-300"><Newspaper size={24}/></div>}
                     </div>
                     <div className="flex-1">
                        <span className="text-[10px] font-black uppercase tracking-widest text-sepri-medium">{n.category}</span>
                        <h3 className="font-bold text-gray-800 line-clamp-1 mb-2">{n.title}</h3>
                        <div className="flex gap-2">
                           <button onClick={() => { setCurrentNews(n); setIsEditingNews(true); }} className="text-blue-500 hover:bg-blue-50 p-2 rounded-lg transition-colors"><Edit2 size={16}/></button>
                           <button onClick={() => handleDeleteNews(n.id)} className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors"><Trash2 size={16}/></button>
                        </div>
                     </div>
                  </div>
                ))}
              </div>
           </div>
        )}
      </div>
    </div>
  );
};

export default AdminLogin;

import React, { useState, useEffect } from 'react';
import { Lock, User, ChevronRight, Key, LogOut, Settings, Newspaper, MessageSquare, FileText, Plus, Trash2, Edit2, Save, ToggleLeft, ToggleRight, Check, Image as ImageIcon, Briefcase, File, X, List, ExternalLink, Link as LinkIcon, Phone, Share2, ShieldAlert, Copy, ChevronUp, ChevronDown, Upload, AlertCircle } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { DEFAULT_CONTACT_INFO } from '../constants';
import { UserRole, NewsItem, PopupConfig, FormTemplate, FormField, EventType, Question, Step, QuickLink, ContactInfo, UserAccount, ProtocolAlert } from '../types';
import { getNews, saveNews, getPopups, togglePopup, updatePopup, getForms, addForm, deleteForm, getEvents, saveEvents, addEvent, deleteEvent, getQuickLinks, addQuickLink, deleteQuickLink, updateQuickLink, getContactInfo, saveContactInfo, authenticateUser, getUsers, resetUserPassword, initUsers } from '../services/dataService';

const AdminLogin: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentRole, setCurrentRole] = useState<UserRole>('USER');
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState<'news' | 'popups' | 'forms' | 'protocols' | 'links' | 'config' | 'creator'>('news');
  const [news, setNews] = useState<NewsItem[]>([]);
  const [popups, setPopups] = useState<PopupConfig[]>([]);
  const [forms, setForms] = useState<FormTemplate[]>([]);
  const [events, setEvents] = useState<EventType[]>([]);
  const [quickLinks, setQuickLinks] = useState<QuickLink[]>([]);
  const [contactInfo, setContactInfo] = useState<ContactInfo>(DEFAULT_CONTACT_INFO);

  const [users, setUsers] = useState<UserAccount[]>([]);
  const [newGeneratedPassword, setNewGeneratedPassword] = useState<string | null>(null);
  const [isResetting, setIsResetting] = useState<string | null>(null);

  const [isCreatingForm, setIsCreatingForm] = useState(false);
  const [newForm, setNewForm] = useState<Partial<FormTemplate>>({ title: '', fields: [] });
  const [newField, setNewField] = useState<Partial<FormField>>({ label: '', type: 'text' });

  const [isEditingNews, setIsEditingNews] = useState(false);
  const [currentNews, setCurrentNews] = useState<Partial<NewsItem>>({});

  const [isEditingProtocol, setIsEditingProtocol] = useState(false);
  const [currentProtocol, setCurrentProtocol] = useState<Partial<EventType>>({ baseSteps: [], questions: [], alerts: [] });
  const [newQuestion, setNewQuestion] = useState<Partial<Question>>({ text: '', yesContent: '', noContent: '' });

  // Alertas locales para el protocolo en edición
  const [newAlert, setNewAlert] = useState<Partial<ProtocolAlert>>({ message: '', type: 'info', active: true });

  const [newStep, setNewStep] = useState<Partial<Step>>({ title: '', description: '', deadline: '', downloadUrl: '' });

  const [newLink, setNewLink] = useState<Partial<QuickLink>>({ title: '', url: '' });
  const [editingLinkId, setEditingLinkId] = useState<string | null>(null);
  const [tempLinkData, setTempLinkData] = useState<Partial<QuickLink>>({});

  const [editingPopupId, setEditingPopupId] = useState<string | null>(null);
  const [tempPopupData, setTempPopupData] = useState<Partial<PopupConfig>>({});

  useEffect(() => {
    const storedRole = localStorage.getItem('sepri_user_role');
    if (storedRole && (storedRole === 'ADMIN' || storedRole === 'CREATOR')) {
      setIsLoggedIn(true);
      setCurrentRole(storedRole as UserRole);
      loadData();
    }
  }, []);

  const loadData = async () => {
    setNews(await getNews());
    setPopups(await getPopups());
    setForms(await getForms());
    setEvents(await getEvents());
    setQuickLinks(await getQuickLinks());
    const contact = await getContactInfo();
    if(contact) setContactInfo(contact);

    if (currentRole === 'CREATOR') {
      const allUsers = getUsers();
      setUsers(allUsers); 
    }
  };

  useEffect(() => {
    if (activeTab === 'creator') {
        setUsers(getUsers());
    }
  }, [activeTab]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
        const role = await authenticateUser(email, password);
        if (role) {
            localStorage.setItem('sepri_user_role', role);
            setCurrentRole(role);
            setIsLoggedIn(true);
            loadData();
        } else {
            alert("Credenciales incorrectas.");
        }
    } catch (error) {
        console.error(error);
        alert("Error al iniciar sesión.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('sepri_user_role');
    setIsLoggedIn(false);
    setCurrentRole('USER');
    navigate('/');
  };

  const canManage = currentRole === 'ADMIN' || currentRole === 'CREATOR';

  const handleMoveStep = (index: number, direction: 'up' | 'down') => {
    if (!currentProtocol.baseSteps) return;
    const newSteps = [...currentProtocol.baseSteps];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;

    if (targetIndex < 0 || targetIndex >= newSteps.length) return;
    [newSteps[index], newSteps[targetIndex]] = [newSteps[targetIndex], newSteps[index]];
    newSteps.forEach((s, i) => s.order = i);
    setCurrentProtocol(prev => ({ ...prev, baseSteps: newSteps }));
  };

  const handleSaveProtocol = async () => {
    if (!canManage) return;
    if (!currentProtocol.title?.trim() || !currentProtocol.description?.trim()) {
      alert("Título y descripción requeridos");
      return;
    }

    try {
      const protocolToSave: EventType = {
        id: currentProtocol.id || `evt-${Date.now()}`,
        title: currentProtocol.title!,
        description: currentProtocol.description!,
        iconName: currentProtocol.iconName || 'FileText',
        imageUrl: currentProtocol.imageUrl,
        documentUrl: currentProtocol.documentUrl,
        baseSteps: (currentProtocol.baseSteps || []).map((s, i) => ({ ...s, order: i })),
        questions: currentProtocol.questions || [],
        alerts: currentProtocol.alerts || []
      };

      if (currentProtocol.id) {
        const updatedEvents = events.map(e => e.id === currentProtocol.id ? protocolToSave : e);
        await saveEvents(updatedEvents);
        setEvents(updatedEvents);
      } else {
        await addEvent(protocolToSave);
        setEvents(await getEvents());
      }
      setIsEditingProtocol(false);
      setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] });
      alert("Protocolo guardado exitosamente.");
    } catch (error) {
      console.error("Error saving protocol:", error);
      alert("Error al guardar: Revisa tu conexión y permisos.");
    }
  };

  // Gestión de Alertas del Protocolo
  const handleAddAlert = () => {
    if (!newAlert.message) return;
    const alert: ProtocolAlert = {
      id: `alert-${Date.now()}`,
      message: newAlert.message,
      type: newAlert.type as any || 'info',
      active: true
    };
    setCurrentProtocol(prev => ({ ...prev, alerts: [...(prev.alerts || []), alert] }));
    setNewAlert({ message: '', type: 'info', active: true });
  };

  const handleDeleteAlert = (id: string) => {
    setCurrentProtocol(prev => ({ ...prev, alerts: prev.alerts?.filter(a => a.id !== id) || [] }));
  };

  // Gestión de Preguntas
  const handleAddQuestionLocal = () => {
    if (!newQuestion.text) return;
    const q: Question = {
      id: `q-${Date.now()}`,
      text: newQuestion.text,
      yesContent: newQuestion.yesContent,
      noContent: newQuestion.noContent,
      triggerSteps: [], 
      isEnabled: true
    };
    setCurrentProtocol(prev => ({ ...prev, questions: [...(prev.questions || []), q] }));
    setNewQuestion({ text: '', yesContent: '', noContent: '' });
  };

  // Fix: Added missing handleDeleteQuestion function
  const handleDeleteQuestion = (id: string) => {
    setCurrentProtocol(prev => ({ ...prev, questions: prev.questions?.filter(q => q.id !== id) || [] }));
  };

  // Fix: Added missing handleDeleteNews function
  const handleDeleteNews = async (id: string) => {
    if (!window.confirm("¿Estás seguro de eliminar esta noticia?")) return;
    const updatedNews = news.filter(n => n.id !== id);
    await saveNews(updatedNews);
    setNews(updatedNews);
  };

  // --- RESTO DE FUNCIONES MANTENIDAS ---
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'news' | 'protocol_image' | 'hero' | 'logo') => {
    const file = e.target.files?.[0];
    if (file) {
      const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
      if (!validTypes.includes(file.type)) {
        alert("Por favor sube una imagen válida."); return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        if (target === 'news') setCurrentNews(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'protocol_image') setCurrentProtocol(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'hero') setContactInfo(prev => ({ ...prev, heroImageUrl: result }));
        else if (target === 'logo') setContactInfo(prev => ({ ...prev, logoUrl: result }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveNews = async () => {
    if (!canManage) return;
    if (!currentNews.title || !currentNews.summary) return;
    let updatedNews = [...news];
    if (currentNews.id) updatedNews = updatedNews.map(n => n.id === currentNews.id ? { ...n, ...currentNews } as NewsItem : n);
    else {
      updatedNews.unshift({
        id: Date.now().toString(), title: currentNews.title!, summary: currentNews.summary!,
        category: (currentNews.category as any) || 'Novedad', date: new Date().toLocaleDateString('es-CO'), ...currentNews
      } as NewsItem);
    }
    await saveNews(updatedNews); setNews(updatedNews); setIsEditingNews(false); setCurrentNews({});
  };

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <div className="w-64 bg-sepri-dark text-white p-6 hidden md:block">
        <div className="flex items-center gap-3 mb-8">
          <Settings className="text-sepri-yellow" />
          <h1 className="font-bold text-lg">Panel Admin</h1>
        </div>
        <nav className="space-y-2">
          <button onClick={() => setActiveTab('news')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'news' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Newspaper size={18} /> Noticias</button>
          <button onClick={() => setActiveTab('protocols')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'protocols' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Briefcase size={18} /> Protocolos</button>
          <button onClick={() => setActiveTab('popups')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'popups' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><MessageSquare size={18} /> Popups Gral</button>
          <button onClick={() => setActiveTab('forms')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'forms' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><FileText size={18} /> Formularios</button>
          <button onClick={() => setActiveTab('links')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'links' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><LinkIcon size={18} /> Enlaces</button>
          <button onClick={() => setActiveTab('config')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'config' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Settings size={18} /> Configuración</button>
        </nav>
        <button onClick={handleLogout} className="mt-8 text-red-400 flex items-center gap-2 hover:text-red-300"><LogOut size={18} /> Cerrar Sesión</button>
      </div>

      <div className="flex-1 p-8 overflow-y-auto relative">
        <h2 className="text-2xl font-bold text-gray-800 mb-6 border-b pb-4">
          {activeTab === 'news' && 'Gestión de Noticias'}
          {activeTab === 'protocols' && 'Gestión de Protocolos y Alertas'}
          {activeTab === 'popups' && 'Gestión de Popups Generales'}
          {activeTab === 'config' && 'Configuración General'}
        </h2>

        {activeTab === 'protocols' && (
          <div>
            {!isEditingProtocol ? (
              <>
                <div className="mb-6">
                  <button onClick={() => { setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] }); setIsEditingProtocol(true); }} className="bg-sepri-medium text-white px-4 py-2 rounded flex items-center gap-2 hover:bg-sepri-dark shadow-md transition-all">
                    <Plus size={18} /> Nuevo Protocolo
                  </button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {events.map(event => (
                    <div key={event.id} className="bg-white p-6 rounded-xl shadow border border-gray-100 flex flex-col hover:shadow-lg transition-shadow">
                      <h3 className="font-bold text-lg mb-2">{event.title}</h3>
                      <p className="text-xs text-gray-500 mb-4 flex-grow line-clamp-2">{event.description}</p>
                      <div className="flex justify-end gap-2 border-t pt-4">
                        <button onClick={() => { setCurrentProtocol(event); setIsEditingProtocol(true); }} className="text-blue-500 p-2 hover:bg-blue-50 rounded"><Edit2 size={18}/></button>
                        <button onClick={() => deleteEvent(event.id).then(() => getEvents().then(setEvents))} className="text-red-500 p-2 hover:bg-red-50 rounded"><Trash2 size={18}/></button>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            ) : (
              <div className="bg-white p-8 rounded-2xl shadow-xl border border-gray-200 animate-fade-in-up">
                <h3 className="text-xl font-bold mb-8 flex items-center gap-2"><Edit2 className="text-sepri-medium"/> {currentProtocol.id ? 'Editar Protocolo' : 'Nuevo Protocolo'}</h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
                  <div className="space-y-4">
                    <label className="block text-sm font-bold text-gray-700">Información Básica</label>
                    <input type="text" placeholder="Título del Protocolo" className="w-full border p-3 rounded-lg" value={currentProtocol.title || ''} onChange={e => setCurrentProtocol({...currentProtocol, title: e.target.value})} />
                    <textarea placeholder="Descripción detallada" className="w-full border p-3 rounded-lg" rows={3} value={currentProtocol.description || ''} onChange={e => setCurrentProtocol({...currentProtocol, description: e.target.value})} />
                  </div>

                  <div className="space-y-4">
                    <label className="block text-sm font-bold text-gray-700">Documentación y Medios</label>
                    <div className="flex flex-col gap-3">
                       <input type="text" placeholder="URL Documento General (Drive/OneDrive)" className="w-full border p-3 rounded-lg text-sm" value={currentProtocol.documentUrl || ''} onChange={e => setCurrentProtocol({...currentProtocol, documentUrl: e.target.value})} />
                       <label className="flex items-center justify-center border-2 border-dashed border-gray-200 p-4 rounded-xl cursor-pointer hover:bg-gray-50 text-gray-500 text-sm">
                          <ImageIcon size={20} className="mr-2" /> {currentProtocol.imageUrl ? 'Cambiar Imagen de Cabecera' : 'Subir Imagen de Cabecera'}
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleImageUpload(e, 'protocol_image')} />
                       </label>
                    </div>
                  </div>
                </div>

                {/* NUEVO: GESTIÓN DE ALERTAS DEL PROTOCOLO */}
                <div className="mb-10 p-6 bg-red-50 rounded-2xl border border-red-100">
                  <h4 className="font-bold text-red-800 mb-4 flex items-center gap-2"><AlertCircle size={20}/> Alertas del Protocolo</h4>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-4">
                    <input type="text" placeholder="Mensaje de la alerta..." className="md:col-span-2 border p-2 rounded-lg" value={newAlert.message || ''} onChange={e => setNewAlert({...newAlert, message: e.target.value})} />
                    <select className="border p-2 rounded-lg" value={newAlert.type || 'info'} onChange={e => setNewAlert({...newAlert, type: e.target.value as any})}>
                      <option value="info">Información (Azul)</option>
                      <option value="warning">Advertencia (Amarillo)</option>
                      <option value="danger">Crítica/Peligro (Rojo)</option>
                    </select>
                  </div>
                  <button onClick={handleAddAlert} className="bg-red-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-red-700 shadow-sm">Agregar Alerta</button>

                  <div className="mt-4 space-y-2">
                    {currentProtocol.alerts?.map(alert => (
                      <div key={alert.id} className="bg-white p-3 rounded-lg flex justify-between items-center border shadow-sm">
                        <span className={`text-xs font-bold px-2 py-1 rounded ${alert.type === 'danger' ? 'bg-red-100 text-red-600' : alert.type === 'warning' ? 'bg-yellow-100 text-yellow-600' : 'bg-blue-100 text-blue-600'}`}>
                          {alert.type.toUpperCase()}
                        </span>
                        <p className="flex-1 mx-4 text-sm text-gray-700">{alert.message}</p>
                        <button onClick={() => handleDeleteAlert(alert.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                      </div>
                    ))}
                  </div>
                </div>

                {/* NUEVO: GESTIÓN DE PREGUNTAS CON RAMIFICACIÓN SÍ/NO */}
                <div className="mb-10 p-6 bg-blue-50 rounded-2xl border border-blue-100">
                  <h4 className="font-bold text-sepri-dark mb-4 flex items-center gap-2"><List size={20}/> Preguntas y Ramificación (SÍ/NO)</h4>
                  <div className="space-y-4 mb-6">
                    <input type="text" placeholder="¿Pregunta para el usuario?" className="w-full border p-3 rounded-lg" value={newQuestion.text || ''} onChange={e => setNewQuestion({...newQuestion, text: e.target.value})} />
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="text-xs font-bold text-green-700 uppercase">Si responde SÍ, mostrar:</label>
                        <textarea placeholder="Instrucción si elige SÍ..." className="w-full border p-2 rounded-lg text-sm mt-1" rows={2} value={newQuestion.yesContent || ''} onChange={e => setNewQuestion({...newQuestion, yesContent: e.target.value})} />
                      </div>
                      <div>
                        <label className="text-xs font-bold text-gray-500 uppercase">Si responde NO, mostrar:</label>
                        <textarea placeholder="Instrucción si elige NO..." className="w-full border p-2 rounded-lg text-sm mt-1" rows={2} value={newQuestion.noContent || ''} onChange={e => setNewQuestion({...newQuestion, noContent: e.target.value})} />
                      </div>
                    </div>
                  </div>
                  <button onClick={handleAddQuestionLocal} className="bg-sepri-medium text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-sepri-dark">Agregar Pregunta</button>

                  <div className="mt-6 space-y-4">
                    {currentProtocol.questions?.map(q => (
                      <div key={q.id} className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm relative group">
                        <button onClick={() => handleDeleteQuestion(q.id)} className="absolute top-2 right-2 text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={16}/></button>
                        <p className="font-bold text-gray-800 mb-2">{q.text}</p>
                        <div className="flex gap-4">
                          <div className="flex-1 text-[10px] bg-green-50 p-2 rounded border border-green-100">
                             <span className="font-black text-green-700">SI → </span> {q.yesContent || <span className="italic text-gray-400">Sin contenido configurado</span>}
                          </div>
                          <div className="flex-1 text-[10px] bg-gray-50 p-2 rounded border border-gray-200">
                             <span className="font-black text-gray-600">NO → </span> {q.noContent || <span className="italic text-gray-400">Sin contenido configurado</span>}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="flex justify-end gap-3 mt-10 pt-6 border-t">
                  <button onClick={() => setIsEditingProtocol(false)} className="px-6 py-2 text-gray-500 hover:bg-gray-100 rounded-lg">Cancelar</button>
                  <button onClick={handleSaveProtocol} className="bg-green-600 text-white px-10 py-2 rounded-lg font-bold shadow-lg hover:bg-green-700 transition-all flex items-center gap-2"><Save size={18}/> Guardar Protocolo</button>
                </div>
              </div>
            )}
          </div>
        )}

        {/* TAB NEWS */}
        {activeTab === 'news' && (
           <div className="space-y-6">
              <div className="flex justify-between items-center">
                 <button onClick={() => { setCurrentNews({}); setIsEditingNews(true); }} className="bg-sepri-medium text-white px-6 py-2 rounded-lg flex items-center gap-2 shadow hover:bg-sepri-dark transition-all">
                    <Plus size={18} /> Nueva Noticia
                 </button>
              </div>
              {isEditingNews && (
                 <div className="bg-white p-8 rounded-2xl shadow-xl border mb-10">
                    <h3 className="text-xl font-bold mb-6">{currentNews.id ? 'Editar Noticia' : 'Crear Noticia'}</h3>
                    <div className="grid grid-cols-1 gap-6">
                        <input type="text" placeholder="Título impactante" className="w-full border p-3 rounded-lg" value={currentNews.title || ''} onChange={e => setCurrentNews({...currentNews, title: e.target.value})} />
                        <div className="grid grid-cols-2 gap-4">
                           <select className="border p-3 rounded-lg" value={currentNews.category || 'Novedad'} onChange={e => setCurrentNews({...currentNews, category: e.target.value as any})}>
                              <option value="Novedad">Novedad</option>
                              <option value="Evento">Evento</option>
                              <option value="Importante">Importante</option>
                           </select>
                           <label className="flex items-center justify-center border-2 border-dashed border-gray-200 p-3 rounded-lg cursor-pointer hover:bg-gray-50 text-gray-400 text-xs">
                              <ImageIcon size={16} className="mr-2" /> {currentNews.imageUrl ? 'Cambiar Imagen' : 'Subir Imagen'}
                              <input type="file" accept="image/*" className="hidden" onChange={(e) => handleImageUpload(e, 'news')} />
                           </label>
                        </div>
                        <textarea placeholder="Resumen descriptivo de la noticia..." className="w-full border p-3 rounded-lg" rows={4} value={currentNews.summary || ''} onChange={e => setCurrentNews({...currentNews, summary: e.target.value})} />
                        <div className="flex justify-end gap-3 mt-4">
                           <button onClick={() => setIsEditingNews(false)} className="px-6 py-2 text-gray-400">Cancelar</button>
                           <button onClick={handleSaveNews} className="bg-sepri-medium text-white px-8 py-2 rounded-lg font-bold shadow-lg">Guardar Publicación</button>
                        </div>
                    </div>
                 </div>
              )}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {news.map(n => (
                  <div key={n.id} className="bg-white p-6 rounded-2xl shadow border flex gap-4">
                     <div className="w-20 h-20 bg-gray-100 rounded-xl overflow-hidden flex-shrink-0">
                        {n.imageUrl ? <img src={n.imageUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-gray-300"><Newspaper size={24}/></div>}
                     </div>
                     <div className="flex-1">
                        <span className="text-[10px] font-black uppercase tracking-widest text-sepri-medium">{n.category}</span>
                        <h3 className="font-bold text-gray-800 line-clamp-1 mb-2">{n.title}</h3>
                        <div className="flex gap-2">
                           <button onClick={() => { setCurrentNews(n); setIsEditingNews(true); }} className="text-blue-500 hover:bg-blue-50 p-2 rounded-lg transition-colors"><Edit2 size={16}/></button>
                           <button onClick={() => handleDeleteNews(n.id)} className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors"><Trash2 size={16}/></button>
                        </div>
                     </div>
                  </div>
                ))}
              </div>
           </div>
        )}
      </div>
    </div>
  );
};

