// Always use @google/genai as the library name
import { GoogleGenAI } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { ChatMessage } from "../types";

/**
 * Sends a message to the Gemini model and retrieves the response.
 * Follows the latest SDK guidelines for initialization and content generation.
 */
export const sendMessageToGemini = async (
  history: ChatMessage[],
  newMessage: string
): Promise<string> => {
  try {
    // Initialize the AI client exactly as required: MUST use new GoogleGenAI({ apiKey: process.env.API_KEY })
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Use gemini-3-flash-preview for general text tasks as per model selection rules
    const model = 'gemini-3-flash-preview';

    // Map the conversation history to the Content format.
    const contents = history.map((msg) => ({
      role: msg.role === 'user' ? 'user' : 'model',
      parts: [{ text: msg.text }],
    }));

    // Call generateContent with the full history as contents and system instruction in config
    const response = await ai.models.generateContent({
      model: model,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });

    // Access the response text property directly (getter, not a function)
    const text = response.text;

    return (
      text ||
      "Lo siento, no pude generar una respuesta en este momento."
    );
  } catch (error) {
    console.error("Error calling Gemini:", error);
    // Silent generic error handling as mandated: do not ask user for API keys
    return "Hubo un error al conectar con el asistente. Por favor intenta más tarde.";
  }
};

