                       <option value="warning">Advertencia (Amarillo)</option>
                       <option value="alert">Alerta Crítica (Rojo)</option>
                    </select>
                 </div>
                 <textarea placeholder="Contenido del mensaje..." className="w-full border p-2 rounded text-sm" rows={2} value={newPopup.content || ''} onChange={e => setNewPopup({...newPopup, content: e.target.value})} />
                 <button onClick={handleAddPopup} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold hover:bg-sepri-dark">Crear Aviso</button>
              </div>
              <div className="space-y-3">
                 {popups.map(p => (
                    <div key={p.id} className="flex items-center justify-between p-4 border rounded-xl bg-white shadow-sm">
                       <div className="flex items-center gap-4">
                          <input type="checkbox" checked={p.isEnabled} onChange={() => handleTogglePopup(p.id)} className="w-5 h-5 accent-sepri-medium" />
                          <div>
                             <div className="flex items-center gap-2">
                                <span className={`w-2 h-2 rounded-full ${p.type === 'alert' ? 'bg-red-500' : p.type === 'warning' ? 'bg-yellow-500' : 'bg-blue-500'}`}></span>
                                <p className="text-sm font-bold">{p.title}</p>
                             </div>
                             <p className="text-xs text-gray-500 line-clamp-1">{p.content}</p>
                          </div>
                       </div>
                       <button onClick={() => handleRemovePopup(p.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* Privacy Policy */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Lock size={20}/> Políticas y Privacidad</h3>
              <textarea 
                className="w-full border p-4 rounded-xl min-h-[150px] text-sm leading-relaxed" 
                value={contactInfo.privacyPolicy || ''} 
                onChange={e => setContactInfo({...contactInfo, privacyPolicy: e.target.value})}
                placeholder="Escribe la política de privacidad oficial aquí..."
              />
            </section>

            {/* Team Members */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><User size={20}/> Equipo SEPRI</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-4">
                 <div className="grid grid-cols-2 gap-4">
                    <input type="text" placeholder="Nombre" className="border p-2 rounded text-sm" value={newMember.name || ''} onChange={e => setNewMember({...newMember, name: e.target.value})} />
                    <input type="text" placeholder="Cargo" className="border p-2 rounded text-sm" value={newMember.role || ''} onChange={e => setNewMember({...newMember, role: e.target.value})} />
                 </div>
                 <div className="flex gap-4">
                    <label className="bg-white px-4 py-2 border rounded cursor-pointer text-xs font-bold">
                       {newMember.imageUrl ? "Foto lista" : "Subir Foto"}
                       <input type="file" className="hidden" onChange={e => handleImageUpload(e, 'member')} />
                    </label>
                    <button onClick={handleAddMember} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold ml-auto">Agregar Miembro</button>
                 </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {contactInfo.teamMembers?.map(m => (
                    <div key={m.id} className="flex items-center gap-4 p-3 border rounded-xl bg-white shadow-sm">
                       <div className="w-10 h-10 rounded-full bg-gray-100 overflow-hidden">
                          {m.imageUrl && <img src={m.imageUrl} className="w-full h-full object-cover" />}
                       </div>
                       <div className="flex-1">
                          <p className="font-bold text-xs">{m.name}</p>
                          <p className="text-[10px] text-gray-500">{m.role}</p>
                       </div>
                       <button onClick={() => handleRemoveMember(m.id)} className="text-red-400 hover:text-red-600"><Trash2 size={14}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* GLOBAL SAVE ACTION */}
            <div className="sticky bottom-6 flex justify-center">
               <button onClick={handleSaveConfig} className="bg-green-600 text-white px-12 py-4 rounded-full font-black flex items-center justify-center gap-3 shadow-2xl hover:bg-green-700 transition-all hover:scale-105 active:scale-95 group">
                 <Save size={24} className="group-hover:rotate-12 transition-transform"/> GUARDAR TODA LA CONFIGURACIÓN
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminLogin;

import React, { useState, useEffect } from 'react';
import { Lock, LogOut, Settings, Newspaper, MessageSquare, FileText, Plus, Trash2, Edit2, Save, Image as ImageIcon, Briefcase, List, AlertCircle, User, ArrowUp, ArrowDown, Video, Facebook, Instagram, Youtube, Link as LinkIcon, Bell, Phone, Mail, MapPin, ArrowLeft } from 'lucide-react';
import { useNavigate, Link } from 'react-router-dom';
import { DEFAULT_CONTACT_INFO } from '../constants';
import { UserRole, NewsItem, EventType, Question, ContactInfo, ProtocolAlert, TeamMember, Step, PopupConfig, QuickLink } from '../types';
import { getNews, saveNews, getEvents, saveEvents, addEvent, deleteEvent, getContactInfo, saveContactInfo, authenticateUser, getPopups, savePopups, getQuickLinks, saveQuickLinks } from '../services/dataService';

const AdminLogin: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentRole, setCurrentRole] = useState<UserRole>('USER');
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState<'news' | 'protocols' | 'config'>('news');
  const [news, setNews] = useState<NewsItem[]>([]);
  const [events, setEvents] = useState<EventType[]>([]);
  const [contactInfo, setContactInfo] = useState<ContactInfo>(DEFAULT_CONTACT_INFO);
  const [popups, setPopups] = useState<PopupConfig[]>([]);
  const [quickLinks, setQuickLinks] = useState<QuickLink[]>([]);

  const [isEditingNews, setIsEditingNews] = useState(false);
  const [currentNews, setCurrentNews] = useState<Partial<NewsItem>>({});

  const [isEditingProtocol, setIsEditingProtocol] = useState(false);
  const [currentProtocol, setCurrentProtocol] = useState<Partial<EventType>>({ baseSteps: [], questions: [], alerts: [] });
  const [newQuestion, setNewQuestion] = useState<Partial<Question>>({ text: '', yesContent: '', noContent: '' });
  const [newAlert, setNewAlert] = useState<Partial<ProtocolAlert>>({ message: '', type: 'info', active: true });

  const [newMember, setNewMember] = useState<Partial<TeamMember>>({ name: '', role: '' });
  const [newPopup, setNewPopup] = useState<Partial<PopupConfig>>({ title: '', content: '', type: 'info', isEnabled: true });
  const [newQuickLink, setNewQuickLink] = useState<Partial<QuickLink>>({ title: '', url: '', isEnabled: true });

  useEffect(() => {
    const storedRole = localStorage.getItem('sepri_user_role');
    if (storedRole && (storedRole === 'ADMIN' || storedRole === 'CREATOR')) {
      setIsLoggedIn(true);
      setCurrentRole(storedRole as UserRole);
      loadData();
    }
  }, []);

  const loadData = async () => {
    setNews(await getNews());
    setEvents(await getEvents());
    setPopups(await getPopups());
    setQuickLinks(await getQuickLinks());
    const contact = await getContactInfo();
    if(contact) setContactInfo(contact);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const role = await authenticateUser(email, password);
    if (role) {
        localStorage.setItem('sepri_user_role', role);
        setCurrentRole(role);
        setIsLoggedIn(true);
        loadData();
    } else {
        alert("Credenciales incorrectas.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('sepri_user_role');
    setIsLoggedIn(false);
    navigate('/');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'news' | 'protocol' | 'logo' | 'member', memberId?: string) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        if (target === 'news') setCurrentNews(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'protocol') setCurrentProtocol(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'logo') setContactInfo(prev => ({ ...prev, logoUrl: result }));
        else if (target === 'member' && !memberId) setNewMember(prev => ({ ...prev, imageUrl: result }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveConfig = async () => {
    try {
      await saveContactInfo(contactInfo);
      await savePopups(popups);
      await saveQuickLinks(quickLinks);
      alert("Configuración institucional, popups y enlaces actualizados correctamente.");
    } catch (e) {
      alert("Error al guardar la configuración.");
    }
  };

  const handleAddMember = () => {
    if (!newMember.name || !newMember.role) return;
    const member: TeamMember = {
      id: `member-${Date.now()}`,
      name: newMember.name!,
      role: newMember.role!,
      imageUrl: newMember.imageUrl,
      order: contactInfo.teamMembers?.length || 0
    };
    setContactInfo(prev => ({ ...prev, teamMembers: [...(prev.teamMembers || []), member] }));
    setNewMember({ name: '', role: '' });
  };

  const handleRemoveMember = (id: string) => {
    setContactInfo(prev => ({ ...prev, teamMembers: prev.teamMembers?.filter(m => m.id !== id) }));
  };

  // Popup Management
  const handleAddPopup = () => {
    if (!newPopup.title || !newPopup.content) return;
    const p: PopupConfig = {
      id: `popup-${Date.now()}`,
      title: newPopup.title!,
      content: newPopup.content!,
      type: newPopup.type as any || 'info',
      isEnabled: true
    };
    setPopups([...popups, p]);
    setNewPopup({ title: '', content: '', type: 'info' });
  };

  const handleTogglePopup = (id: string) => {
    setPopups(popups.map(p => p.id === id ? { ...p, isEnabled: !p.isEnabled } : p));
  };

  const handleRemovePopup = (id: string) => {
    setPopups(popups.filter(p => p.id !== id));
  };

  // Quick Links Management
  const handleAddQuickLink = () => {
    if (!newQuickLink.title || !newQuickLink.url) return;
    const link: QuickLink = {
      id: `ql-${Date.now()}`,
      title: newQuickLink.title!,
      url: newQuickLink.url!,
      isEnabled: true
    };
    setQuickLinks([...quickLinks, link]);
    setNewQuickLink({ title: '', url: '' });
  };

  const handleToggleQuickLink = (id: string) => {
    setQuickLinks(quickLinks.map(l => l.id === id ? { ...l, isEnabled: !l.isEnabled } : l));
  };

  const handleRemoveQuickLink = (id: string) => {
    setQuickLinks(quickLinks.filter(l => l.id !== id));
  };

  const handleSaveNews = async () => {
    if (!currentNews.title || !currentNews.summary) return;
    let updatedNews = [...news];
    if (currentNews.id) {
      updatedNews = updatedNews.map(n => n.id === currentNews.id ? { ...n, ...currentNews } as NewsItem : n);
    } else {
      updatedNews.unshift({
        id: Date.now().toString(),
        title: currentNews.title!,
        summary: currentNews.summary!,
        category: (currentNews.category as any) || 'Novedad',
        date: new Date().toLocaleDateString('es-CO'),
        imageUrl: currentNews.imageUrl
      } as NewsItem);
    }
    await saveNews(updatedNews);
    setNews(updatedNews);
    setIsEditingNews(false);
    setCurrentNews({});
    alert("Noticia publicada.");
  };

  const handleDeleteNews = async (id: string) => {
    if (!confirm("¿Eliminar noticia?")) return;
    const updated = news.filter(n => n.id !== id);
    await saveNews(updated);
    setNews(updated);
  };

  const handleSaveProtocol = async () => {
    if (!currentProtocol.title?.trim() || !currentProtocol.description?.trim()) {
      alert("Título y descripción requeridos");
      return;
    }

    try {
      const protocolToSave: EventType = {
        id: currentProtocol.id || `evt-${Date.now()}`,
        title: currentProtocol.title!,
        description: currentProtocol.description!,
        iconName: currentProtocol.iconName || 'FileText',
        imageUrl: currentProtocol.imageUrl,
        documentUrl: currentProtocol.documentUrl,
        baseSteps: (currentProtocol.baseSteps || []).map((s, i) => ({ ...s, order: i })),
        questions: currentProtocol.questions || [],
        alerts: currentProtocol.alerts || []
      };

      if (currentProtocol.id) {
        const updatedEvents = events.map(e => e.id === currentProtocol.id ? protocolToSave : e);
        await saveEvents(updatedEvents);
        setEvents(updatedEvents);
      } else {
        await addEvent(protocolToSave);
        setEvents(await getEvents());
      }
      setIsEditingProtocol(false);
      setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] });
      alert("Protocolo guardado exitosamente.");
    } catch (error) {
      alert("Error al guardar.");
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-sepri-dark flex flex-col items-center justify-center p-4 relative">
        <div className="absolute top-6 left-6">
          <Link to="/" className="text-white/70 hover:text-white flex items-center gap-2 font-bold transition-colors">
            <ArrowLeft size={20} /> Volver al inicio
          </Link>
        </div>

        <form onSubmit={handleSubmit} className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-md animate-fade-in-up">
          <div className="text-center mb-8">
            <Settings className="w-12 h-12 text-sepri-yellow mx-auto mb-2" />
            <h1 className="text-2xl font-bold text-sepri-dark">Acceso Administrativo</h1>
          </div>
          <div className="space-y-4">
            <input 
              type="email" 
              placeholder="Email" 
              className="w-full border p-3 rounded-lg outline-none focus:ring-2 focus:ring-sepri-medium" 
              value={email} 
              onChange={e => setEmail(e.target.value)} 
              required 
            />
            <input 
              type="password" 
              placeholder="Contraseña" 
              className="w-full border p-3 rounded-lg outline-none focus:ring-2 focus:ring-sepri-medium" 
              value={password} 
              onChange={e => setPassword(e.target.value)} 
              required 
            />
            <button 
              type="submit" 
              className="w-full bg-sepri-medium text-white p-3 rounded-lg font-bold hover:bg-sepri-dark transition-colors shadow-lg"
            >
              Entrar al Panel
            </button>
          </div>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Sidebar */}
      <div className="w-64 bg-sepri-dark text-white p-6 hidden md:block">
        <div className="flex items-center gap-3 mb-8">
          <Settings className="text-sepri-yellow" />
          <h1 className="font-bold text-lg">Panel SEPRI</h1>
        </div>
        <nav className="space-y-2">
          <button onClick={() => setActiveTab('news')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'news' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Newspaper size={18} /> Noticias</button>
          <button onClick={() => setActiveTab('protocols')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'protocols' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Briefcase size={18} /> Protocolos</button>
          <button onClick={() => setActiveTab('config')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'config' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Settings size={18} /> Configuración</button>
        </nav>
        <button onClick={handleLogout} className="mt-8 text-red-400 flex items-center gap-2 hover:text-red-300 px-3"><LogOut size={18} /> Salir</button>
      </div>

      <div className="flex-1 p-8 overflow-y-auto">
        {/* News Tab */}
        {activeTab === 'news' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
               <h2 className="text-2xl font-bold">Gestión de Noticias</h2>
               <button onClick={() => { setCurrentNews({}); setIsEditingNews(true); }} className="bg-sepri-medium text-white px-6 py-2 rounded-lg flex items-center gap-2 shadow hover:bg-sepri-dark">
                  <Plus size={18} /> Nueva Noticia
               </button>
            </div>
            {isEditingNews && (
              <div className="bg-white p-6 rounded-xl shadow border">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                    <input type="text" placeholder="Título" className="w-full border p-2 rounded" value={currentNews.title || ''} onChange={e => setCurrentNews({...currentNews, title: e.target.value})} />
                    <select className="border p-2 rounded" value={currentNews.category || 'Novedad'} onChange={e => setCurrentNews({...currentNews, category: e.target.value as any})}>
                       <option value="Novedad">Novedad</option>
                       <option value="Evento">Evento</option>
                       <option value="Importante">Importante</option>
                    </select>
                 </div>
                 <textarea placeholder="Resumen" className="w-full border p-2 rounded mb-4" rows={3} value={currentNews.summary || ''} onChange={e => setCurrentNews({...currentNews, summary: e.target.value})} />
                 <div className="flex gap-4">
                    <label className="bg-gray-100 p-2 rounded cursor-pointer text-xs font-bold">
                       {currentNews.imageUrl ? "Cambiar Imagen" : "Subir Imagen"}
                       <input type="file" className="hidden" onChange={e => handleImageUpload(e, 'news')} />
                    </label>
                    <button onClick={handleSaveNews} className="bg-sepri-medium text-white px-4 py-2 rounded text-sm font-bold ml-auto">Publicar</button>
                    <button onClick={() => setIsEditingNews(false)} className="px-4 py-2 text-gray-500">Cancelar</button>
                 </div>
              </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               {news.map(n => (
                 <div key={n.id} className="bg-white p-4 rounded-xl border flex gap-4 items-center">
                    <div className="w-16 h-16 bg-gray-100 rounded overflow-hidden flex-shrink-0">
                       {n.imageUrl && <img src={n.imageUrl} className="w-full h-full object-cover" />}
                    </div>
                    <div className="flex-1">
                       <h4 className="font-bold text-sm line-clamp-1">{n.title}</h4>
                       <p className="text-xs text-gray-400">{n.date}</p>
                    </div>
                    <button onClick={() => handleDeleteNews(n.id)} className="text-red-400 p-2 hover:bg-red-50 rounded"><Trash2 size={16}/></button>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* Protocols Tab (Minimized for Brevity in this block, assumed same as previous working state) */}
        {activeTab === 'protocols' && (
          <div>
            <div className="mb-6 flex justify-between items-center">
               <h2 className="text-2xl font-bold">Gestión de Protocolos</h2>
               <button onClick={() => { setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] }); setIsEditingProtocol(true); }} className="bg-sepri-medium text-white px-4 py-2 rounded flex items-center gap-2 hover:bg-sepri-dark">
                  <Plus size={18} /> Nuevo Protocolo
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
               {events.map(event => (
                 <div key={event.id} className="bg-white p-4 rounded-xl border shadow-sm">
                    <h3 className="font-bold">{event.title}</h3>
                    <div className="flex justify-end gap-2 mt-4">
                       <button onClick={() => { setCurrentProtocol(event); setIsEditingProtocol(true); }} className="text-blue-500"><Edit2 size={16}/></button>
                       <button onClick={() => deleteEvent(event.id).then(loadData)} className="text-red-500"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* NEW CONFIGURATION SECTIONS */}
        {activeTab === 'config' && (
          <div className="max-w-4xl space-y-10 pb-20">
            <h2 className="text-3xl font-black text-sepri-dark border-b pb-4">Configuración del Sistema</h2>

            {/* Logo & Branding */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><ImageIcon size={20}/> Identidad Visual (Logo D22)</h3>
              <div className="flex items-center gap-6">
                 <div className="w-24 h-24 border rounded-xl overflow-hidden flex items-center justify-center bg-gray-50">
                    {contactInfo.logoUrl ? <img src={contactInfo.logoUrl} className="max-w-full max-h-full object-contain" /> : <ImageIcon className="text-gray-300" size={32}/>}
                 </div>
                 <label className="bg-sepri-bg text-sepri-dark px-4 py-2 rounded-lg cursor-pointer hover:bg-gray-200 font-bold text-sm">
                   Subir Logo Distrito
                   <input type="file" className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'logo')} />
                 </label>
              </div>
            </section>

            {/* Contacts & General Info */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Phone size={20}/> Información de Contacto</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Coordinador Principal</label>
                    <input type="text" placeholder="Nombre Coordinador" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorName || ''} onChange={e => setContactInfo({...contactInfo, coordinatorName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorPhone || ''} onChange={e => setContactInfo({...contactInfo, coordinatorPhone: e.target.value})} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Asistente de Coordinación</label>
                    <input type="text" placeholder="Nombre Asistente" className="w-full border p-3 rounded-lg" value={contactInfo.assistantName || ''} onChange={e => setContactInfo({...contactInfo, assistantName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.assistantPhone || ''} onChange={e => setContactInfo({...contactInfo, assistantPhone: e.target.value})} />
                 </div>
              </div>
              <div className="space-y-4">
                 <div className="flex flex-col gap-2">
                    <label className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2"><Mail size={14}/> Correo Institucional</label>
                    <input type="email" placeholder="email@ipuc.org.co" className="w-full border p-3 rounded-lg" value={contactInfo.email || ''} onChange={e => setContactInfo({...contactInfo, email: e.target.value})} />
                 </div>
                 <div className="flex flex-col gap-2">
                    <label className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2"><MapPin size={14}/> Dirección Administrativa</label>
                    <input type="text" placeholder="Dirección de la sede" className="w-full border p-3 rounded-lg" value={contactInfo.address || ''} onChange={e => setContactInfo({...contactInfo, address: e.target.value})} />
                 </div>
              </div>
            </section>

            {/* Social Media */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Facebook size={20}/> Redes Sociales</h3>
              <div className="space-y-4">
                 <div className="flex items-center gap-4">
                    <Facebook className="text-blue-600" />
                    <input type="text" placeholder="URL Facebook" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.facebookUrl || ''} onChange={e => setContactInfo({...contactInfo, facebookUrl: e.target.value})} />
                 </div>
                 <div className="flex items-center gap-4">
                    <Instagram className="text-pink-600" />
                    <input type="text" placeholder="URL Instagram" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.instagramUrl || ''} onChange={e => setContactInfo({...contactInfo, instagramUrl: e.target.value})} />
                 </div>
                 <div className="flex items-center gap-4">
                    <Youtube className="text-red-600" />
                    <input type="text" placeholder="URL YouTube" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.youtubeUrl || ''} onChange={e => setContactInfo({...contactInfo, youtubeUrl: e.target.value})} />
                 </div>
              </div>
            </section>

            {/* Quick Links Manager */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><LinkIcon size={20}/> Enlaces Rápidos (Footer)</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-3">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <input type="text" placeholder="Título del enlace" className="border p-2 rounded text-sm" value={newQuickLink.title || ''} onChange={e => setNewQuickLink({...newQuickLink, title: e.target.value})} />
                    <input type="text" placeholder="URL (/ruta o https://)" className="border p-2 rounded text-sm" value={newQuickLink.url || ''} onChange={e => setNewQuickLink({...newQuickLink, url: e.target.value})} />
                 </div>
                 <button onClick={handleAddQuickLink} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold hover:bg-sepri-dark">Agregar Enlace</button>
              </div>
              <div className="space-y-2">
                 {quickLinks.map(link => (
                    <div key={link.id} className="flex items-center justify-between p-3 border rounded-lg bg-white">
                       <div className="flex items-center gap-3">
                          <input type="checkbox" checked={link.isEnabled} onChange={() => handleToggleQuickLink(link.id)} className="w-4 h-4 accent-sepri-medium" />
                          <div>
                             <p className="text-sm font-bold">{link.title}</p>
                             <p className="text-[10px] text-gray-500">{link.url}</p>
                          </div>
                       </div>
                       <button onClick={() => handleRemoveQuickLink(link.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* Popups Manager */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Bell size={20}/> Ventanas Emergentes (Popups)</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-4">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <input type="text" placeholder="Título del aviso" className="border p-2 rounded text-sm" value={newPopup.title || ''} onChange={e => setNewPopup({...newPopup, title: e.target.value})} />
                    <select className="border p-2 rounded text-sm" value={newPopup.type || 'info'} onChange={e => setNewPopup({...newPopup, type: e.target.value as any})}>
                       <option value="info">Información (Azul)</option>
                       <option value="warning">Advertencia (Amarillo)</option>
                       <option value="alert">Alerta Crítica (Rojo)</option>
                    </select>
                 </div>
                 <textarea placeholder="Contenido del mensaje..." className="w-full border p-2 rounded text-sm" rows={2} value={newPopup.content || ''} onChange={e => setNewPopup({...newPopup, content: e.target.value})} />
                 <button onClick={handleAddPopup} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold hover:bg-sepri-dark">Crear Aviso</button>
              </div>
              <div className="space-y-3">
                 {popups.map(p => (
                    <div key={p.id} className="flex items-center justify-between p-4 border rounded-xl bg-white shadow-sm">
                       <div className="flex items-center gap-4">
                          <input type="checkbox" checked={p.isEnabled} onChange={() => handleTogglePopup(p.id)} className="w-5 h-5 accent-sepri-medium" />
                          <div>
                             <div className="flex items-center gap-2">
                                <span className={`w-2 h-2 rounded-full ${p.type === 'alert' ? 'bg-red-500' : p.type === 'warning' ? 'bg-yellow-500' : 'bg-blue-500'}`}></span>
                                <p className="text-sm font-bold">{p.title}</p>
                             </div>
                             <p className="text-xs text-gray-500 line-clamp-1">{p.content}</p>
                          </div>
                       </div>
                       <button onClick={() => handleRemovePopup(p.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* Privacy Policy */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Lock size={20}/> Políticas y Privacidad</h3>
              <textarea 
                className="w-full border p-4 rounded-xl min-h-[150px] text-sm leading-relaxed" 
                value={contactInfo.privacyPolicy || ''} 
                onChange={e => setContactInfo({...contactInfo, privacyPolicy: e.target.value})}
                placeholder="Escribe la política de privacidad oficial aquí..."
              />
            </section>

            {/* Team Members */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><User size={20}/> Equipo SEPRI</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-4">
                 <div className="grid grid-cols-2 gap-4">
                    <input type="text" placeholder="Nombre" className="border p-2 rounded text-sm" value={newMember.name || ''} onChange={e => setNewMember({...newMember, name: e.target.value})} />
                    <input type="text" placeholder="Cargo" className="border p-2 rounded text-sm" value={newMember.role || ''} onChange={e => setNewMember({...newMember, role: e.target.value})} />
                 </div>
                 <div className="flex gap-4">
                    <label className="bg-white px-4 py-2 border rounded cursor-pointer text-xs font-bold">
                       {newMember.imageUrl ? "Foto lista" : "Subir Foto"}
                       <input type="file" className="hidden" onChange={e => handleImageUpload(e, 'member')} />
                    </label>
                    <button onClick={handleAddMember} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold ml-auto">Agregar Miembro</button>
                 </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {contactInfo.teamMembers?.map(m => (
                    <div key={m.id} className="flex items-center gap-4 p-3 border rounded-xl bg-white shadow-sm">
                       <div className="w-10 h-10 rounded-full bg-gray-100 overflow-hidden">
                          {m.imageUrl && <img src={m.imageUrl} className="w-full h-full object-cover" />}
                       </div>
                       <div className="flex-1">
                          <p className="font-bold text-xs">{m.name}</p>
                          <p className="text-[10px] text-gray-500">{m.role}</p>
                       </div>
                       <button onClick={() => handleRemoveMember(m.id)} className="text-red-400 hover:text-red-600"><Trash2 size={14}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* GLOBAL SAVE ACTION */}
            <div className="sticky bottom-6 flex justify-center">
               <button onClick={handleSaveConfig} className="bg-green-600 text-white px-12 py-4 rounded-full font-black flex items-center justify-center gap-3 shadow-2xl hover:bg-green-700 transition-all hover:scale-105 active:scale-95 group">
                 <Save size={24} className="group-hover:rotate-12 transition-transform"/> GUARDAR TODA LA CONFIGURACIÓN
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminLogin;

import React, { useState, useEffect } from 'react';
import { Lock, LogOut, Settings, Newspaper, MessageSquare, FileText, Plus, Trash2, Edit2, Save, Image as ImageIcon, Briefcase, List, AlertCircle, User, ArrowUp, ArrowDown, Video, Facebook, Instagram, Youtube, Link as LinkIcon, Bell, Phone, Mail, MapPin, ArrowLeft } from 'lucide-react';
import { useNavigate, Link } from 'react-router-dom';
import { DEFAULT_CONTACT_INFO } from '../constants';
import { UserRole, NewsItem, EventType, Question, ContactInfo, ProtocolAlert, TeamMember, Step, PopupConfig, QuickLink } from '../types';
import { getNews, saveNews, getEvents, saveEvents, addEvent, deleteEvent, getContactInfo, saveContactInfo, authenticateUser, getPopups, savePopups, getQuickLinks, saveQuickLinks } from '../services/dataService';

const AdminLogin: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentRole, setCurrentRole] = useState<UserRole>('USER');
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState<'news' | 'protocols' | 'config'>('news');
  const [news, setNews] = useState<NewsItem[]>([]);
  const [events, setEvents] = useState<EventType[]>([]);
  const [contactInfo, setContactInfo] = useState<ContactInfo>(DEFAULT_CONTACT_INFO);
  const [popups, setPopups] = useState<PopupConfig[]>([]);
  const [quickLinks, setQuickLinks] = useState<QuickLink[]>([]);

  const [isEditingNews, setIsEditingNews] = useState(false);
  const [currentNews, setCurrentNews] = useState<Partial<NewsItem>>({});

  const [isEditingProtocol, setIsEditingProtocol] = useState(false);
  const [currentProtocol, setCurrentProtocol] = useState<Partial<EventType>>({ baseSteps: [], questions: [], alerts: [] });
  const [newQuestion, setNewQuestion] = useState<Partial<Question>>({ text: '', yesContent: '', noContent: '' });
  const [newAlert, setNewAlert] = useState<Partial<ProtocolAlert>>({ message: '', type: 'info', active: true });

  const [newMember, setNewMember] = useState<Partial<TeamMember>>({ name: '', role: '' });
  const [newPopup, setNewPopup] = useState<Partial<PopupConfig>>({ title: '', content: '', type: 'info', isEnabled: true });
  const [newQuickLink, setNewQuickLink] = useState<Partial<QuickLink>>({ title: '', url: '', isEnabled: true });

  useEffect(() => {
    const storedRole = localStorage.getItem('sepri_user_role');
    if (storedRole && (storedRole === 'ADMIN' || storedRole === 'CREATOR')) {
      setIsLoggedIn(true);
      setCurrentRole(storedRole as UserRole);
      loadData();
    }
  }, []);

  const loadData = async () => {
    setNews(await getNews());
    setEvents(await getEvents());
    setPopups(await getPopups());
    setQuickLinks(await getQuickLinks());
    const contact = await getContactInfo();
    if(contact) setContactInfo(contact);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const role = await authenticateUser(email, password);
    if (role) {
        localStorage.setItem('sepri_user_role', role);
        setCurrentRole(role);
        setIsLoggedIn(true);
        loadData();
    } else {
        alert("Credenciales incorrectas.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('sepri_user_role');
    setIsLoggedIn(false);
    navigate('/');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'news' | 'protocol' | 'logo' | 'member', memberId?: string) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        if (target === 'news') setCurrentNews(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'protocol') setCurrentProtocol(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'logo') setContactInfo(prev => ({ ...prev, logoUrl: result }));
        else if (target === 'member' && !memberId) setNewMember(prev => ({ ...prev, imageUrl: result }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveConfig = async () => {
    try {
      await saveContactInfo(contactInfo);
      await savePopups(popups);
      await saveQuickLinks(quickLinks);
      alert("Configuración institucional, popups y enlaces actualizados correctamente.");
    } catch (e) {
      alert("Error al guardar la configuración.");
    }
  };

  const handleAddMember = () => {
    if (!newMember.name || !newMember.role) return;
    const member: TeamMember = {
      id: `member-${Date.now()}`,
      name: newMember.name!,
      role: newMember.role!,
      imageUrl: newMember.imageUrl,
      order: contactInfo.teamMembers?.length || 0
    };
    setContactInfo(prev => ({ ...prev, teamMembers: [...(prev.teamMembers || []), member] }));
    setNewMember({ name: '', role: '' });
  };

  const handleRemoveMember = (id: string) => {
    setContactInfo(prev => ({ ...prev, teamMembers: prev.teamMembers?.filter(m => m.id !== id) }));
  };

  // Popup Management
  const handleAddPopup = () => {
    if (!newPopup.title || !newPopup.content) return;
    const p: PopupConfig = {
      id: `popup-${Date.now()}`,
      title: newPopup.title!,
      content: newPopup.content!,
      type: newPopup.type as any || 'info',
      isEnabled: true
    };
    setPopups([...popups, p]);
    setNewPopup({ title: '', content: '', type: 'info' });
  };

  const handleTogglePopup = (id: string) => {
    setPopups(popups.map(p => p.id === id ? { ...p, isEnabled: !p.isEnabled } : p));
  };

  const handleRemovePopup = (id: string) => {
    setPopups(popups.filter(p => p.id !== id));
  };

  // Quick Links Management
  const handleAddQuickLink = () => {
    if (!newQuickLink.title || !newQuickLink.url) return;
    const link: QuickLink = {
      id: `ql-${Date.now()}`,
      title: newQuickLink.title!,
      url: newQuickLink.url!,
      isEnabled: true
    };
    setQuickLinks([...quickLinks, link]);
    setNewQuickLink({ title: '', url: '' });
  };

  const handleToggleQuickLink = (id: string) => {
    setQuickLinks(quickLinks.map(l => l.id === id ? { ...l, isEnabled: !l.isEnabled } : l));
  };

  const handleRemoveQuickLink = (id: string) => {
    setQuickLinks(quickLinks.filter(l => l.id !== id));
  };

  const handleSaveNews = async () => {
    if (!currentNews.title || !currentNews.summary) return;
    let updatedNews = [...news];
    try {
      if (currentNews.id) {
        updatedNews = updatedNews.map(n => n.id === currentNews.id ? { ...n, ...currentNews } as NewsItem : n);
      } else {
        updatedNews.unshift({
          id: Date.now().toString(),
          title: currentNews.title!,
          summary: currentNews.summary!,
          category: (currentNews.category as any) || 'Novedad',
          date: new Date().toLocaleDateString('es-CO'),
          imageUrl: currentNews.imageUrl
        } as NewsItem);
      }
      await saveNews(updatedNews);
      setNews(updatedNews);
      setIsEditingNews(false);
      setCurrentNews({});
      alert(currentNews.id ? "Noticia actualizada." : "Noticia publicada.");
    } catch (e) {
      alert("Error al guardar la noticia. Por favor intente nuevamente.");
    }
  };

  const handleDeleteNews = async (id: string) => {
    if (!confirm("¿Eliminar noticia?")) return;
    const updated = news.filter(n => n.id !== id);
    await saveNews(updated);
    setNews(updated);
  };

  const handleSaveProtocol = async () => {
    if (!currentProtocol.title?.trim() || !currentProtocol.description?.trim()) {
      alert("Título y descripción requeridos");
      return;
    }

    try {
      const protocolToSave: EventType = {
        id: currentProtocol.id || `evt-${Date.now()}`,
        title: currentProtocol.title!,
        description: currentProtocol.description!,
        iconName: currentProtocol.iconName || 'FileText',
        imageUrl: currentProtocol.imageUrl,
        documentUrl: currentProtocol.documentUrl,
        baseSteps: (currentProtocol.baseSteps || []).map((s, i) => ({ ...s, order: i })),
        questions: currentProtocol.questions || [],
        alerts: currentProtocol.alerts || []
      };

      if (currentProtocol.id) {
        const updatedEvents = events.map(e => e.id === currentProtocol.id ? protocolToSave : e);
        await saveEvents(updatedEvents);
        setEvents(updatedEvents);
      } else {
        await addEvent(protocolToSave);
        setEvents(await getEvents());
      }
      setIsEditingProtocol(false);
      setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] });
      alert("Protocolo guardado exitosamente.");
    } catch (error) {
      alert("Error al guardar.");
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-sepri-dark flex flex-col items-center justify-center p-4 relative">
        <div className="absolute top-6 left-6">
          <Link to="/" className="text-white/70 hover:text-white flex items-center gap-2 font-bold transition-colors">
            <ArrowLeft size={20} /> Volver al inicio
          </Link>
        </div>

        <form onSubmit={handleSubmit} className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-md animate-fade-in-up">
          <div className="text-center mb-8">
            <Settings className="w-12 h-12 text-sepri-yellow mx-auto mb-2" />
            <h1 className="text-2xl font-bold text-sepri-dark">Acceso Administrativo</h1>
          </div>
          <div className="space-y-4">
            <input 
              type="email" 
              placeholder="Email" 
              className="w-full border p-3 rounded-lg outline-none focus:ring-2 focus:ring-sepri-medium" 
              value={email} 
              onChange={e => setEmail(e.target.value)} 
              required 
            />
            <input 
              type="password" 
              placeholder="Contraseña" 
              className="w-full border p-3 rounded-lg outline-none focus:ring-2 focus:ring-sepri-medium" 
              value={password} 
              onChange={e => setPassword(e.target.value)} 
              required 
            />
            <button 
              type="submit" 
              className="w-full bg-sepri-medium text-white p-3 rounded-lg font-bold hover:bg-sepri-dark transition-colors shadow-lg"
            >
              Entrar al Panel
            </button>
          </div>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Sidebar */}
      <div className="w-64 bg-sepri-dark text-white p-6 hidden md:block">
        <div className="flex items-center gap-3 mb-8">
          <Settings className="text-sepri-yellow" />
          <h1 className="font-bold text-lg">Panel SEPRI</h1>
        </div>
        <nav className="space-y-2">
          <button onClick={() => setActiveTab('news')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'news' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Newspaper size={18} /> Noticias</button>
          <button onClick={() => setActiveTab('protocols')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'protocols' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Briefcase size={18} /> Protocolos</button>
          <button onClick={() => setActiveTab('config')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'config' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Settings size={18} /> Configuración</button>
        </nav>
        <button onClick={handleLogout} className="mt-8 text-red-400 flex items-center gap-2 hover:text-red-300 px-3"><LogOut size={18} /> Salir</button>
      </div>

      <div className="flex-1 p-8 overflow-y-auto">
        {/* News Tab */}
        {activeTab === 'news' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
               <h2 className="text-2xl font-bold">Gestión de Noticias</h2>
               <button onClick={() => { setCurrentNews({}); setIsEditingNews(true); }} className="bg-sepri-medium text-white px-6 py-2 rounded-lg flex items-center gap-2 shadow hover:bg-sepri-dark">
                  <Plus size={18} /> Nueva Noticia
               </button>
            </div>
            {isEditingNews && (
              <div className="bg-white p-6 rounded-xl shadow border animate-fade-in">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                    <input type="text" placeholder="Título" className="w-full border p-2 rounded" value={currentNews.title || ''} onChange={e => setCurrentNews({...currentNews, title: e.target.value})} />
                    <select className="border p-2 rounded" value={currentNews.category || 'Novedad'} onChange={e => setCurrentNews({...currentNews, category: e.target.value as any})}>
                       <option value="Novedad">Novedad</option>
                       <option value="Evento">Evento</option>
                       <option value="Importante">Importante</option>
                    </select>
                 </div>
                 <textarea placeholder="Resumen" className="w-full border p-2 rounded mb-4" rows={6} value={currentNews.summary || ''} onChange={e => setCurrentNews({...currentNews, summary: e.target.value})} />
                 <div className="flex gap-4">
                    <label className="bg-gray-100 p-2 rounded cursor-pointer text-xs font-bold">
                       {currentNews.imageUrl ? "Cambiar Imagen" : "Subir Imagen"}
                       <input type="file" className="hidden" onChange={e => handleImageUpload(e, 'news')} />
                    </label>
                    <button onClick={handleSaveNews} className="bg-sepri-medium text-white px-4 py-2 rounded text-sm font-bold ml-auto">
                      {currentNews.id ? "Guardar Cambios" : "Publicar"}
                    </button>
                    <button onClick={() => { setIsEditingNews(false); setCurrentNews({}); }} className="px-4 py-2 text-gray-500">Cancelar</button>
                 </div>
              </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               {news.map(n => (
                 <div key={n.id} className="bg-white p-4 rounded-xl border flex gap-4 items-center group hover:border-sepri-medium transition-colors">
                    <div className="w-16 h-16 bg-gray-100 rounded overflow-hidden flex-shrink-0">
                       {n.imageUrl && <img src={n.imageUrl} className="w-full h-full object-cover" />}
                    </div>
                    <div className="flex-1">
                       <h4 className="font-bold text-sm line-clamp-1">{n.title}</h4>
                       <p className="text-xs text-gray-400">{n.date}</p>
                    </div>
                    <div className="flex gap-1">
                       <button onClick={() => { setCurrentNews(n); setIsEditingNews(true); }} className="text-blue-500 p-2 hover:bg-blue-50 rounded" title="Editar noticia"><Edit2 size={16}/></button>
                       <button onClick={() => handleDeleteNews(n.id)} className="text-red-400 p-2 hover:bg-red-50 rounded" title="Eliminar noticia"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* Protocols Tab (Minimized for Brevity in this block, assumed same as previous working state) */}
        {activeTab === 'protocols' && (
          <div>
            <div className="mb-6 flex justify-between items-center">
               <h2 className="text-2xl font-bold">Gestión de Protocolos</h2>
               <button onClick={() => { setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] }); setIsEditingProtocol(true); }} className="bg-sepri-medium text-white px-4 py-2 rounded flex items-center gap-2 hover:bg-sepri-dark">
                  <Plus size={18} /> Nuevo Protocolo
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
               {events.map(event => (
                 <div key={event.id} className="bg-white p-4 rounded-xl border shadow-sm">
                    <h3 className="font-bold">{event.title}</h3>
                    <div className="flex justify-end gap-2 mt-4">
                       <button onClick={() => { setCurrentProtocol(event); setIsEditingProtocol(true); }} className="text-blue-500"><Edit2 size={16}/></button>
                       <button onClick={() => deleteEvent(event.id).then(loadData)} className="text-red-500"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* NEW CONFIGURATION SECTIONS */}
        {activeTab === 'config' && (
          <div className="max-w-4xl space-y-10 pb-20">
            <h2 className="text-3xl font-black text-sepri-dark border-b pb-4">Configuración del Sistema</h2>

            {/* Logo & Branding */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><ImageIcon size={20}/> Identidad Visual (Logo D22)</h3>
              <div className="flex items-center gap-6">
                 <div className="w-24 h-24 border rounded-xl overflow-hidden flex items-center justify-center bg-gray-50">
                    {contactInfo.logoUrl ? <img src={contactInfo.logoUrl} className="max-w-full max-h-full object-contain" /> : <ImageIcon className="text-gray-300" size={32}/>}
                 </div>
                 <label className="bg-sepri-bg text-sepri-dark px-4 py-2 rounded-lg cursor-pointer hover:bg-gray-200 font-bold text-sm">
                   Subir Logo Distrito
                   <input type="file" className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'logo')} />
                 </label>
              </div>
            </section>

            {/* Contacts & General Info */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Phone size={20}/> Información de Contacto</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Coordinador Principal</label>
                    <input type="text" placeholder="Nombre Coordinador" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorName || ''} onChange={e => setContactInfo({...contactInfo, coordinatorName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorPhone || ''} onChange={e => setContactInfo({...contactInfo, coordinatorPhone: e.target.value})} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Asistente de Coordinación</label>
                    <input type="text" placeholder="Nombre Asistente" className="w-full border p-3 rounded-lg" value={contactInfo.assistantName || ''} onChange={e => setContactInfo({...contactInfo, assistantName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.assistantPhone || ''} onChange={e => setContactInfo({...contactInfo, assistantPhone: e.target.value})} />
                 </div>
              </div>
              <div className="space-y-4">
                 <div className="flex flex-col gap-2">
                    <label className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2"><Mail size={14}/> Correo Institucional</label>
                    <input type="email" placeholder="email@ipuc.org.co" className="w-full border p-3 rounded-lg" value={contactInfo.email || ''} onChange={e => setContactInfo({...contactInfo, email: e.target.value})} />
                 </div>
                 <div className="flex flex-col gap-2">
                    <label className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2"><MapPin size={14}/> Dirección Administrativa</label>
                    <input type="text" placeholder="Dirección de la sede" className="w-full border p-3 rounded-lg" value={contactInfo.address || ''} onChange={e => setContactInfo({...contactInfo, address: e.target.value})} />
                 </div>
              </div>
            </section>

            {/* Social Media */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Facebook size={20}/> Redes Sociales</h3>
              <div className="space-y-4">
                 <div className="flex items-center gap-4">
                    <Facebook className="text-blue-600" />
                    <input type="text" placeholder="URL Facebook" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.facebookUrl || ''} onChange={e => setContactInfo({...contactInfo, facebookUrl: e.target.value})} />
                 </div>
                 <div className="flex items-center gap-4">
                    <Instagram className="text-pink-600" />
                    <input type="text" placeholder="URL Instagram" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.instagramUrl || ''} onChange={e => setContactInfo({...contactInfo, instagramUrl: e.target.value})} />
                 </div>
                 <div className="flex items-center gap-4">
                    <Youtube className="text-red-600" />
                    <input type="text" placeholder="URL YouTube" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.youtubeUrl || ''} onChange={e => setContactInfo({...contactInfo, youtubeUrl: e.target.value})} />
                 </div>
              </div>
            </section>

            {/* Quick Links Manager */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><LinkIcon size={20}/> Enlaces Rápidos (Footer)</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-3">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <input type="text" placeholder="Título del enlace" className="border p-2 rounded text-sm" value={newQuickLink.title || ''} onChange={e => setNewQuickLink({...newQuickLink, title: e.target.value})} />
                    <input type="text" placeholder="URL (/ruta o https://)" className="border p-2 rounded text-sm" value={newQuickLink.url || ''} onChange={e => setNewQuickLink({...newQuickLink, url: e.target.value})} />
                 </div>
                 <button onClick={handleAddQuickLink} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold hover:bg-sepri-dark">Agregar Enlace</button>
              </div>
              <div className="space-y-2">
                 {quickLinks.map(link => (
                    <div key={link.id} className="flex items-center justify-between p-3 border rounded-lg bg-white">
                       <div className="flex items-center gap-3">
                          <input type="checkbox" checked={link.isEnabled} onChange={() => handleToggleQuickLink(link.id)} className="w-4 h-4 accent-sepri-medium" />
                          <div>
                             <p className="text-sm font-bold">{link.title}</p>
                             <p className="text-[10px] text-gray-500">{link.url}</p>
                          </div>
                       </div>
                       <button onClick={() => handleRemoveQuickLink(link.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* Popups Manager */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Bell size={20}/> Ventanas Emergentes (Popups)</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-4">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <input type="text" placeholder="Título del aviso" className="border p-2 rounded text-sm" value={newPopup.title || ''} onChange={e => setNewPopup({...newPopup, title: e.target.value})} />
                    <select className="border p-2 rounded text-sm" value={newPopup.type || 'info'} onChange={e => setNewPopup({...newPopup, type: e.target.value as any})}>
                       <option value="info">Información (Azul)</option>
                       <option value="warning">Advertencia (Amarillo)</option>
                       <option value="alert">Alerta Crítica (Rojo)</option>
                    </select>
                 </div>
                 <textarea placeholder="Contenido del mensaje..." className="w-full border p-2 rounded text-sm" rows={2} value={newPopup.content || ''} onChange={e => setNewPopup({...newPopup, content: e.target.value})} />
                 <button onClick={handleAddPopup} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold hover:bg-sepri-dark">Crear Aviso</button>
              </div>
              <div className="space-y-3">
                 {popups.map(p => (
                    <div key={p.id} className="flex items-center justify-between p-4 border rounded-xl bg-white shadow-sm">
                       <div className="flex items-center gap-4">
                          <input type="checkbox" checked={p.isEnabled} onChange={() => handleTogglePopup(p.id)} className="w-5 h-5 accent-sepri-medium" />
                          <div>
                             <div className="flex items-center gap-2">
                                <span className={`w-2 h-2 rounded-full ${p.type === 'alert' ? 'bg-red-500' : p.type === 'warning' ? 'bg-yellow-500' : 'bg-blue-500'}`}></span>
                                <p className="text-sm font-bold">{p.title}</p>
                             </div>
                             <p className="text-xs text-gray-500 line-clamp-1">{p.content}</p>
                          </div>
                       </div>
                       <button onClick={() => handleRemovePopup(p.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* Privacy Policy */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Lock size={20}/> Políticas y Privacidad</h3>
              <textarea 
                className="w-full border p-4 rounded-xl min-h-[150px] text-sm leading-relaxed" 
                value={contactInfo.privacyPolicy || ''} 
                onChange={e => setContactInfo({...contactInfo, privacyPolicy: e.target.value})}
                placeholder="Escribe la política de privacidad oficial aquí..."
              />
            </section>

            {/* Team Members */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><User size={20}/> Equipo SEPRI</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-4">
                 <div className="grid grid-cols-2 gap-4">
                    <input type="text" placeholder="Nombre" className="border p-2 rounded text-sm" value={newMember.name || ''} onChange={e => setNewMember({...newMember, name: e.target.value})} />
                    <input type="text" placeholder="Cargo" className="border p-2 rounded text-sm" value={newMember.role || ''} onChange={e => setNewMember({...newMember, role: e.target.value})} />
                 </div>
                 <div className="flex gap-4">
                    <label className="bg-white px-4 py-2 border rounded cursor-pointer text-xs font-bold">
                       {newMember.imageUrl ? "Foto lista" : "Subir Foto"}
                       <input type="file" className="hidden" onChange={e => handleImageUpload(e, 'member')} />
                    </label>
                    <button onClick={handleAddMember} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold ml-auto">Agregar Miembro</button>
                 </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {contactInfo.teamMembers?.map(m => (
                    <div key={m.id} className="flex items-center gap-4 p-3 border rounded-xl bg-white shadow-sm">
                       <div className="w-10 h-10 rounded-full bg-gray-100 overflow-hidden">
                          {m.imageUrl && <img src={m.imageUrl} className="w-full h-full object-cover" />}
                       </div>
                       <div className="flex-1">
                          <p className="font-bold text-xs">{m.name}</p>
                          <p className="text-[10px] text-gray-500">{m.role}</p>
                       </div>
                       <button onClick={() => handleRemoveMember(m.id)} className="text-red-400 hover:text-red-600"><Trash2 size={14}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* GLOBAL SAVE ACTION */}
            <div className="sticky bottom-6 flex justify-center">
               <button onClick={handleSaveConfig} className="bg-green-600 text-white px-12 py-4 rounded-full font-black flex items-center justify-center gap-3 shadow-2xl hover:bg-green-700 transition-all hover:scale-105 active:scale-95 group">
                 <Save size={24} className="group-hover:rotate-12 transition-transform"/> GUARDAR TODA LA CONFIGURACIÓN
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminLogin;

import React, { useState, useEffect } from 'react';
import { Lock, LogOut, Settings, Newspaper, MessageSquare, FileText, Plus, Trash2, Edit2, Save, Image as ImageIcon, Briefcase, List, AlertCircle, User, ArrowUp, ArrowDown, Video, Facebook, Instagram, Youtube, Link as LinkIcon, Bell, Phone, Mail, MapPin, ArrowLeft } from 'lucide-react';
import { useNavigate, Link } from 'react-router-dom';
import { DEFAULT_CONTACT_INFO } from '../constants';
import { UserRole, NewsItem, EventType, Question, ContactInfo, ProtocolAlert, TeamMember, Step, PopupConfig, QuickLink } from '../types';
import { getNews, saveNews, getEvents, saveEvents, addEvent, deleteEvent, getContactInfo, saveContactInfo, authenticateUser, getPopups, savePopups, getQuickLinks, saveQuickLinks } from '../services/dataService';

const AdminLogin: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentRole, setCurrentRole] = useState<UserRole>('USER');
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState<'news' | 'protocols' | 'config'>('news');
  const [news, setNews] = useState<NewsItem[]>([]);
  const [events, setEvents] = useState<EventType[]>([]);
  const [contactInfo, setContactInfo] = useState<ContactInfo>(DEFAULT_CONTACT_INFO);
  const [popups, setPopups] = useState<PopupConfig[]>([]);
  const [quickLinks, setQuickLinks] = useState<QuickLink[]>([]);

  const [isEditingNews, setIsEditingNews] = useState(false);
  const [currentNews, setCurrentNews] = useState<Partial<NewsItem>>({});

  const [isEditingProtocol, setIsEditingProtocol] = useState(false);
  const [currentProtocol, setCurrentProtocol] = useState<Partial<EventType>>({ baseSteps: [], questions: [], alerts: [] });
  const [newQuestion, setNewQuestion] = useState<Partial<Question>>({ text: '', yesContent: '', noContent: '' });
  const [newAlert, setNewAlert] = useState<Partial<ProtocolAlert>>({ message: '', type: 'info', active: true });

  const [newMember, setNewMember] = useState<Partial<TeamMember>>({ name: '', role: '' });
  const [newPopup, setNewPopup] = useState<Partial<PopupConfig>>({ title: '', content: '', type: 'info', isEnabled: true });
  const [newQuickLink, setNewQuickLink] = useState<Partial<QuickLink>>({ title: '', url: '', isEnabled: true });

  useEffect(() => {
    const storedRole = localStorage.getItem('sepri_user_role');
    if (storedRole && (storedRole === 'ADMIN' || storedRole === 'CREATOR')) {
      setIsLoggedIn(true);
      setCurrentRole(storedRole as UserRole);
      loadData();
    }
  }, []);

  const loadData = async () => {
    setNews(await getNews());
    setEvents(await getEvents());
    setPopups(await getPopups());
    setQuickLinks(await getQuickLinks());
    const contact = await getContactInfo();
    if(contact) setContactInfo(contact);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const role = await authenticateUser(email, password);
    if (role) {
        localStorage.setItem('sepri_user_role', role);
        setCurrentRole(role);
        setIsLoggedIn(true);
        loadData();
    } else {
        alert("Credenciales incorrectas.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('sepri_user_role');
    setIsLoggedIn(false);
    navigate('/');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'news' | 'protocol' | 'logo' | 'member', memberId?: string) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        if (target === 'news') setCurrentNews(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'protocol') setCurrentProtocol(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'logo') setContactInfo(prev => ({ ...prev, logoUrl: result }));
        else if (target === 'member' && !memberId) setNewMember(prev => ({ ...prev, imageUrl: result }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveConfig = async () => {
    try {
      await saveContactInfo(contactInfo);
      await savePopups(popups);
      await saveQuickLinks(quickLinks);
      alert("Configuración institucional, popups y enlaces actualizados correctamente.");
    } catch (e) {
      alert("Error al guardar la configuración.");
    }
  };

  const handleAddMember = () => {
    if (!newMember.name || !newMember.role) return;
    const member: TeamMember = {
      id: `member-${Date.now()}`,
      name: newMember.name!,
      role: newMember.role!,
      imageUrl: newMember.imageUrl,
      order: contactInfo.teamMembers?.length || 0
    };
    setContactInfo(prev => ({ ...prev, teamMembers: [...(prev.teamMembers || []), member] }));
    setNewMember({ name: '', role: '' });
  };

  const handleRemoveMember = (id: string) => {
    setContactInfo(prev => ({ ...prev, teamMembers: prev.teamMembers?.filter(m => m.id !== id) }));
  };

  // Popup Management
  const handleAddPopup = () => {
    if (!newPopup.title || !newPopup.content) return;
    const p: PopupConfig = {
      id: `popup-${Date.now()}`,
      title: newPopup.title!,
      content: newPopup.content!,
      type: newPopup.type as any || 'info',
      isEnabled: true
    };
    setPopups([...popups, p]);
    setNewPopup({ title: '', content: '', type: 'info' });
  };

  const handleTogglePopup = (id: string) => {
    setPopups(popups.map(p => p.id === id ? { ...p, isEnabled: !p.isEnabled } : p));
  };

  const handleRemovePopup = (id: string) => {
    setPopups(popups.filter(p => p.id !== id));
  };

  // Quick Links Management
  const handleAddQuickLink = () => {
    if (!newQuickLink.title || !newQuickLink.url) return;
    const link: QuickLink = {
      id: `ql-${Date.now()}`,
      title: newQuickLink.title!,
      url: newQuickLink.url!,
      isEnabled: true
    };
    setQuickLinks([...quickLinks, link]);
    setNewQuickLink({ title: '', url: '' });
  };

  const handleToggleQuickLink = (id: string) => {
    setQuickLinks(quickLinks.map(l => l.id === id ? { ...l, isEnabled: !l.isEnabled } : l));
  };

  const handleRemoveQuickLink = (id: string) => {
    setQuickLinks(quickLinks.filter(l => l.id !== id));
  };

  const handleSaveNews = async () => {
    if (!currentNews.title || !currentNews.summary) return;
    let updatedNews = [...news];
    try {
      if (currentNews.id) {
        updatedNews = updatedNews.map(n => n.id === currentNews.id ? { ...n, ...currentNews } as NewsItem : n);
      } else {
        updatedNews.unshift({
          id: Date.now().toString(),
          title: currentNews.title!,
          summary: currentNews.summary!,
          category: (currentNews.category as any) || 'Novedad',
          date: new Date().toLocaleDateString('es-CO'),
          imageUrl: currentNews.imageUrl
        } as NewsItem);
      }
      await saveNews(updatedNews);
      setNews(updatedNews);
      setIsEditingNews(false);
      setCurrentNews({});
      alert(currentNews.id ? "Noticia actualizada." : "Noticia publicada.");
    } catch (e) {
      alert("Error al guardar la noticia. Por favor intente nuevamente.");
    }
  };

  const handleDeleteNews = async (id: string) => {
    if (!confirm("¿Eliminar noticia?")) return;
    const updated = news.filter(n => n.id !== id);
    await saveNews(updated);
    setNews(updated);
  };

  const handleSaveProtocol = async () => {
    if (!currentProtocol.title?.trim() || !currentProtocol.description?.trim()) {
      alert("Título y descripción requeridos");
      return;
    }

    try {
      const protocolToSave: EventType = {
        id: currentProtocol.id || `evt-${Date.now()}`,
        title: currentProtocol.title!,
        description: currentProtocol.description!,
        iconName: currentProtocol.iconName || 'FileText',
        imageUrl: currentProtocol.imageUrl,
        documentUrl: currentProtocol.documentUrl,
        baseSteps: (currentProtocol.baseSteps || []).map((s, i) => ({ ...s, order: i })),
        questions: currentProtocol.questions || [],
        alerts: currentProtocol.alerts || []
      };

      if (currentProtocol.id) {
        const updatedEvents = events.map(e => e.id === currentProtocol.id ? protocolToSave : e);
        await saveEvents(updatedEvents);
        setEvents(updatedEvents);
      } else {
        await addEvent(protocolToSave);
        setEvents(await getEvents());
      }
      setIsEditingProtocol(false);
      setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] });
      alert("Protocolo guardado exitosamente.");
    } catch (error) {
      alert("Error al guardar.");
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-sepri-dark flex flex-col items-center justify-center p-4 relative">
        <div className="absolute top-6 left-6">
          <Link to="/" className="text-white/70 hover:text-white flex items-center gap-2 font-bold transition-colors">
            <ArrowLeft size={20} /> Volver al inicio
          </Link>
        </div>

        <form onSubmit={handleSubmit} className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-md animate-fade-in-up">
          <div className="text-center mb-8">
            <Settings className="w-12 h-12 text-sepri-yellow mx-auto mb-2" />
            <h1 className="text-2xl font-bold text-sepri-dark">Acceso Administrativo</h1>
          </div>
          <div className="space-y-4">
            <input 
              type="email" 
              placeholder="Email" 
              className="w-full border p-3 rounded-lg outline-none focus:ring-2 focus:ring-sepri-medium" 
              value={email} 
              onChange={e => setEmail(e.target.value)} 
              required 
            />
            <input 
              type="password" 
              placeholder="Contraseña" 
              className="w-full border p-3 rounded-lg outline-none focus:ring-2 focus:ring-sepri-medium" 
              value={password} 
              onChange={e => setPassword(e.target.value)} 
              required 
            />
            <button 
              type="submit" 
              className="w-full bg-sepri-medium text-white p-3 rounded-lg font-bold hover:bg-sepri-dark transition-colors shadow-lg"
            >
              Entrar al Panel
            </button>
          </div>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Sidebar */}
      <div className="w-64 bg-sepri-dark text-white p-6 hidden md:block">
        <div className="flex items-center gap-3 mb-8">
          <Settings className="text-sepri-yellow" />
          <h1 className="font-bold text-lg">Panel SEPRI</h1>
        </div>
        <nav className="space-y-2">
          <button onClick={() => setActiveTab('news')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'news' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Newspaper size={18} /> Noticias</button>
          <button onClick={() => setActiveTab('protocols')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'protocols' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Briefcase size={18} /> Protocolos</button>
          <button onClick={() => setActiveTab('config')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'config' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Settings size={18} /> Configuración</button>
        </nav>
        <button onClick={handleLogout} className="mt-8 text-red-400 flex items-center gap-2 hover:text-red-300 px-3"><LogOut size={18} /> Salir</button>
      </div>

      <div className="flex-1 p-8 overflow-y-auto">
        {/* News Tab */}
        {activeTab === 'news' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
               <h2 className="text-2xl font-bold">Gestión de Noticias</h2>
               <button onClick={() => { setCurrentNews({}); setIsEditingNews(true); }} className="bg-sepri-medium text-white px-6 py-2 rounded-lg flex items-center gap-2 shadow hover:bg-sepri-dark">
                  <Plus size={18} /> Nueva Noticia
               </button>
            </div>
            {isEditingNews && (
              <form 
                onSubmit={(e) => { e.preventDefault(); handleSaveNews(); }}
                className="bg-white p-6 rounded-xl shadow border animate-fade-in"
              >
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                    <input 
                      type="text" 
                      placeholder="Título" 
                      className="w-full border p-2 rounded focus:ring-2 focus:ring-sepri-medium outline-none" 
                      value={currentNews.title || ''} 
                      onChange={e => setCurrentNews(prev => ({...prev, title: e.target.value}))} 
                      required
                    />
                    <select 
                      className="border p-2 rounded" 
                      value={currentNews.category || 'Novedad'} 
                      onChange={e => setCurrentNews(prev => ({...prev, category: e.target.value as any}))}
                    >
                       <option value="Novedad">Novedad</option>
                       <option value="Evento">Evento</option>
                       <option value="Importante">Importante</option>
                    </select>
                 </div>
                 <textarea 
                   placeholder="Resumen de la noticia..." 
                   className="w-full border p-2 rounded mb-4 focus:ring-2 focus:ring-sepri-medium outline-none" 
                   rows={6} 
                   value={currentNews.summary || ''} 
                   onChange={e => setCurrentNews(prev => ({...prev, summary: e.target.value}))} 
                   required
                 />

                 {/* Preview and Upload Section */}
                 <div className="flex items-center gap-6 mb-6 p-4 bg-gray-50 rounded-lg border border-dashed">
                    <div className="w-24 h-24 bg-white border rounded overflow-hidden flex-shrink-0 flex items-center justify-center">
                       {currentNews.imageUrl ? (
                          <img src={currentNews.imageUrl} className="w-full h-full object-cover" alt="Preview" />
                       ) : (
                          <ImageIcon className="text-gray-300" size={32} />
                       )}
                    </div>
                    <div className="flex flex-col gap-2">
                       <p className="text-xs font-bold text-gray-500 uppercase tracking-tight">Imagen de Noticia</p>
                       <label className="bg-white border border-gray-300 px-4 py-2 rounded-lg cursor-pointer text-xs font-bold hover:bg-gray-100 transition-colors shadow-sm inline-block">
                          {currentNews.imageUrl ? "Cambiar Imagen" : "Subir Imagen"}
                          <input type="file" className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'news')} />
                       </label>
                    </div>
                 </div>

                 <div className="flex gap-4">
                    <button 
                      type="submit" 
                      className="bg-sepri-medium text-white px-6 py-2 rounded-lg font-bold ml-auto shadow-md hover:bg-sepri-dark transition-all active:scale-95"
                    >
                      {currentNews.id ? "Guardar Cambios" : "Publicar Noticia"}
                    </button>
                    <button 
                      type="button" 
                      onClick={() => { setIsEditingNews(false); setCurrentNews({}); }} 
                      className="px-4 py-2 text-gray-500 font-medium hover:text-gray-700"
                    >
                      Cancelar
                    </button>
                 </div>
              </form>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               {news.map(n => (
                 <div key={n.id} className="bg-white p-4 rounded-xl border flex gap-4 items-center group hover:border-sepri-medium transition-colors">
                    <div className="w-16 h-16 bg-gray-100 rounded overflow-hidden flex-shrink-0">
                       {n.imageUrl && <img src={n.imageUrl} className="w-full h-full object-cover" />}
                    </div>
                    <div className="flex-1">
                       <h4 className="font-bold text-sm line-clamp-1">{n.title}</h4>
                       <p className="text-xs text-gray-400">{n.date}</p>
                    </div>
                    <div className="flex gap-1">
                       <button onClick={() => { setCurrentNews(n); setIsEditingNews(true); }} className="text-blue-500 p-2 hover:bg-blue-50 rounded" title="Editar noticia"><Edit2 size={16}/></button>
                       <button onClick={() => handleDeleteNews(n.id)} className="text-red-400 p-2 hover:bg-red-50 rounded" title="Eliminar noticia"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* Protocols Tab (Minimized for Brevity in this block, assumed same as previous working state) */}
        {activeTab === 'protocols' && (
          <div>
            <div className="mb-6 flex justify-between items-center">
               <h2 className="text-2xl font-bold">Gestión de Protocolos</h2>
               <button onClick={() => { setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] }); setIsEditingProtocol(true); }} className="bg-sepri-medium text-white px-4 py-2 rounded flex items-center gap-2 hover:bg-sepri-dark">
                  <Plus size={18} /> Nuevo Protocolo
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
               {events.map(event => (
                 <div key={event.id} className="bg-white p-4 rounded-xl border shadow-sm">
                    <h3 className="font-bold">{event.title}</h3>
                    <div className="flex justify-end gap-2 mt-4">
                       <button onClick={() => { setCurrentProtocol(event); setIsEditingProtocol(true); }} className="text-blue-500"><Edit2 size={16}/></button>
                       <button onClick={() => deleteEvent(event.id).then(loadData)} className="text-red-500"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* NEW CONFIGURATION SECTIONS */}
        {activeTab === 'config' && (
          <div className="max-w-4xl space-y-10 pb-20">
            <h2 className="text-3xl font-black text-sepri-dark border-b pb-4">Configuración del Sistema</h2>

            {/* Logo & Branding */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><ImageIcon size={20}/> Identidad Visual (Logo D22)</h3>
              <div className="flex items-center gap-6">
                 <div className="w-24 h-24 border rounded-xl overflow-hidden flex items-center justify-center bg-gray-50">
                    {contactInfo.logoUrl ? <img src={contactInfo.logoUrl} className="max-w-full max-h-full object-contain" /> : <ImageIcon className="text-gray-300" size={32}/>}
                 </div>
                 <label className="bg-sepri-bg text-sepri-dark px-4 py-2 rounded-lg cursor-pointer hover:bg-gray-200 font-bold text-sm">
                   Subir Logo Distrito
                   <input type="file" className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'logo')} />
                 </label>
              </div>
            </section>

            {/* Contacts & General Info */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Phone size={20}/> Información de Contacto</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Coordinador Principal</label>
                    <input type="text" placeholder="Nombre Coordinador" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorName || ''} onChange={e => setContactInfo({...contactInfo, coordinatorName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorPhone || ''} onChange={e => setContactInfo({...contactInfo, coordinatorPhone: e.target.value})} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Asistente de Coordinación</label>
                    <input type="text" placeholder="Nombre Asistente" className="w-full border p-3 rounded-lg" value={contactInfo.assistantName || ''} onChange={e => setContactInfo({...contactInfo, assistantName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.assistantPhone || ''} onChange={e => setContactInfo({...contactInfo, assistantPhone: e.target.value})} />
                 </div>
              </div>
              <div className="space-y-4">
                 <div className="flex flex-col gap-2">
                    <label className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2"><Mail size={14}/> Correo Institucional</label>
                    <input type="email" placeholder="email@ipuc.org.co" className="w-full border p-3 rounded-lg" value={contactInfo.email || ''} onChange={e => setContactInfo({...contactInfo, email: e.target.value})} />
                 </div>
                 <div className="flex flex-col gap-2">
                    <label className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2"><MapPin size={14}/> Dirección Administrativa</label>
                    <input type="text" placeholder="Dirección de la sede" className="w-full border p-3 rounded-lg" value={contactInfo.address || ''} onChange={e => setContactInfo({...contactInfo, address: e.target.value})} />
                 </div>
              </div>
            </section>

            {/* Social Media */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Facebook size={20}/> Redes Sociales</h3>
              <div className="space-y-4">
                 <div className="flex items-center gap-4">
                    <Facebook className="text-blue-600" />
                    <input type="text" placeholder="URL Facebook" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.facebookUrl || ''} onChange={e => setContactInfo({...contactInfo, facebookUrl: e.target.value})} />
                 </div>
                 <div className="flex items-center gap-4">
                    <Instagram className="text-pink-600" />
                    <input type="text" placeholder="URL Instagram" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.instagramUrl || ''} onChange={e => setContactInfo({...contactInfo, instagramUrl: e.target.value})} />
                 </div>
                 <div className="flex items-center gap-4">
                    <Youtube className="text-red-600" />
                    <input type="text" placeholder="URL YouTube" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.youtubeUrl || ''} onChange={e => setContactInfo({...contactInfo, youtubeUrl: e.target.value})} />
                 </div>
              </div>
            </section>

            {/* Quick Links Manager */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><LinkIcon size={20}/> Enlaces Rápidos (Footer)</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-3">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <input type="text" placeholder="Título del enlace" className="border p-2 rounded text-sm" value={newQuickLink.title || ''} onChange={e => setNewQuickLink({...newQuickLink, title: e.target.value})} />
                    <input type="text" placeholder="URL (/ruta o https://)" className="border p-2 rounded text-sm" value={newQuickLink.url || ''} onChange={e => setNewQuickLink({...newQuickLink, url: e.target.value})} />
                 </div>
                 <button onClick={handleAddQuickLink} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold hover:bg-sepri-dark">Agregar Enlace</button>
              </div>
              <div className="space-y-2">
                 {quickLinks.map(link => (
                    <div key={link.id} className="flex items-center justify-between p-3 border rounded-lg bg-white">
                       <div className="flex items-center gap-3">
                          <input type="checkbox" checked={link.isEnabled} onChange={() => handleToggleQuickLink(link.id)} className="w-4 h-4 accent-sepri-medium" />
                          <div>
                             <p className="text-sm font-bold">{link.title}</p>
                             <p className="text-[10px] text-gray-500">{link.url}</p>
                          </div>
                       </div>
                       <button onClick={() => handleRemoveQuickLink(link.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* Popups Manager */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Bell size={20}/> Ventanas Emergentes (Popups)</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-4">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <input type="text" placeholder="Título del aviso" className="border p-2 rounded text-sm" value={newPopup.title || ''} onChange={e => setNewPopup({...newPopup, title: e.target.value})} />
                    <select className="border p-2 rounded text-sm" value={newPopup.type || 'info'} onChange={e => setNewPopup({...newPopup, type: e.target.value as any})}>
                       <option value="info">Información (Azul)</option>
                       <option value="warning">Advertencia (Amarillo)</option>
                       <option value="alert">Alerta Crítica (Rojo)</option>
                    </select>
                 </div>
                 <textarea placeholder="Contenido del mensaje..." className="w-full border p-2 rounded text-sm" rows={2} value={newPopup.content || ''} onChange={e => setNewPopup({...newPopup, content: e.target.value})} />
                 <button onClick={handleAddPopup} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold hover:bg-sepri-dark">Crear Aviso</button>
              </div>
              <div className="space-y-3">
                 {popups.map(p => (
                    <div key={p.id} className="flex items-center justify-between p-4 border rounded-xl bg-white shadow-sm">
                       <div className="flex items-center gap-4">
                          <input type="checkbox" checked={p.isEnabled} onChange={() => handleTogglePopup(p.id)} className="w-5 h-5 accent-sepri-medium" />
                          <div>
                             <div className="flex items-center gap-2">
                                <span className={`w-2 h-2 rounded-full ${p.type === 'alert' ? 'bg-red-500' : p.type === 'warning' ? 'bg-yellow-500' : 'bg-blue-500'}`}></span>
                                <p className="text-sm font-bold">{p.title}</p>
                             </div>
                             <p className="text-xs text-gray-500 line-clamp-1">{p.content}</p>
                          </div>
                       </div>
                       <button onClick={() => handleRemovePopup(p.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* Privacy Policy */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Lock size={20}/> Políticas y Privacidad</h3>
              <textarea 
                className="w-full border p-4 rounded-xl min-h-[150px] text-sm leading-relaxed" 
                value={contactInfo.privacyPolicy || ''} 
                onChange={e => setContactInfo({...contactInfo, privacyPolicy: e.target.value})}
                placeholder="Escribe la política de privacidad oficial aquí..."
              />
            </section>

            {/* Team Members */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><User size={20}/> Equipo SEPRI</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-4">
                 <div className="grid grid-cols-2 gap-4">
                    <input type="text" placeholder="Nombre" className="border p-2 rounded text-sm" value={newMember.name || ''} onChange={e => setNewMember({...newMember, name: e.target.value})} />
                    <input type="text" placeholder="Cargo" className="border p-2 rounded text-sm" value={newMember.role || ''} onChange={e => setNewMember({...newMember, role: e.target.value})} />
                 </div>
                 <div className="flex gap-4">
                    <label className="bg-white px-4 py-2 border rounded cursor-pointer text-xs font-bold">
                       {newMember.imageUrl ? "Foto lista" : "Subir Foto"}
                       <input type="file" className="hidden" onChange={e => handleImageUpload(e, 'member')} />
                    </label>
                    <button onClick={handleAddMember} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold ml-auto">Agregar Miembro</button>
                 </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {contactInfo.teamMembers?.map(m => (
                    <div key={m.id} className="flex items-center gap-4 p-3 border rounded-xl bg-white shadow-sm">
                       <div className="w-10 h-10 rounded-full bg-gray-100 overflow-hidden">
                          {m.imageUrl && <img src={m.imageUrl} className="w-full h-full object-cover" />}
                       </div>
                       <div className="flex-1">
                          <p className="font-bold text-xs">{m.name}</p>
                          <p className="text-[10px] text-gray-500">{m.role}</p>
                       </div>
                       <button onClick={() => handleRemoveMember(m.id)} className="text-red-400 hover:text-red-600"><Trash2 size={14}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* GLOBAL SAVE ACTION */}
            <div className="sticky bottom-6 flex justify-center">
               <button onClick={handleSaveConfig} className="bg-green-600 text-white px-12 py-4 rounded-full font-black flex items-center justify-center gap-3 shadow-2xl hover:bg-green-700 transition-all hover:scale-105 active:scale-95 group">
                 <Save size={24} className="group-hover:rotate-12 transition-transform"/> GUARDAR TODA LA CONFIGURACIÓN
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminLogin;

import React, { useState, useEffect } from 'react';
import { Lock, LogOut, Settings, Newspaper, MessageSquare, FileText, Plus, Trash2, Edit2, Save, Image as ImageIcon, Briefcase, List, AlertCircle, User, ArrowUp, ArrowDown, Video, Facebook, Instagram, Youtube, Link as LinkIcon, Bell, Phone, Mail, MapPin, ArrowLeft } from 'lucide-react';
import { useNavigate, Link } from 'react-router-dom';
import { DEFAULT_CONTACT_INFO } from '../constants';
import { UserRole, NewsItem, EventType, Question, ContactInfo, ProtocolAlert, TeamMember, Step, PopupConfig, QuickLink } from '../types';
import { getNews, saveNews, getEvents, saveEvents, addEvent, deleteEvent, getContactInfo, saveContactInfo, authenticateUser, getPopups, savePopups, getQuickLinks, saveQuickLinks } from '../services/dataService';

const AdminLogin: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentRole, setCurrentRole] = useState<UserRole>('USER');
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState<'news' | 'protocols' | 'config'>('news');
  const [news, setNews] = useState<NewsItem[]>([]);
  const [events, setEvents] = useState<EventType[]>([]);
  const [contactInfo, setContactInfo] = useState<ContactInfo>(DEFAULT_CONTACT_INFO);
  const [popups, setPopups] = useState<PopupConfig[]>([]);
  const [quickLinks, setQuickLinks] = useState<QuickLink[]>([]);

  const [isEditingNews, setIsEditingNews] = useState(false);
  const [currentNews, setCurrentNews] = useState<Partial<NewsItem>>({});

  const [isEditingProtocol, setIsEditingProtocol] = useState(false);
  const [currentProtocol, setCurrentProtocol] = useState<Partial<EventType>>({ baseSteps: [], questions: [], alerts: [] });
  const [newQuestion, setNewQuestion] = useState<Partial<Question>>({ text: '', yesContent: '', noContent: '' });
  const [newAlert, setNewAlert] = useState<Partial<ProtocolAlert>>({ message: '', type: 'info', active: true });

  const [newMember, setNewMember] = useState<Partial<TeamMember>>({ name: '', role: '' });
  const [newPopup, setNewPopup] = useState<Partial<PopupConfig>>({ title: '', content: '', type: 'info', isEnabled: true });
  const [newQuickLink, setNewQuickLink] = useState<Partial<QuickLink>>({ title: '', url: '', isEnabled: true });

  useEffect(() => {
    const storedRole = localStorage.getItem('sepri_user_role');
    if (storedRole && (storedRole === 'ADMIN' || storedRole === 'CREATOR')) {
      setIsLoggedIn(true);
      setCurrentRole(storedRole as UserRole);
      loadData();
    }
  }, []);

  const loadData = async () => {
    setNews(await getNews());
    setEvents(await getEvents());
    setPopups(await getPopups());
    setQuickLinks(await getQuickLinks());
    const contact = await getContactInfo();
    if(contact) setContactInfo(contact);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const role = await authenticateUser(email, password);
    if (role) {
        localStorage.setItem('sepri_user_role', role);
        setCurrentRole(role);
        setIsLoggedIn(true);
        loadData();
    } else {
        alert("Credenciales incorrectas.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('sepri_user_role');
    setIsLoggedIn(false);
    navigate('/');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'news' | 'protocol' | 'logo' | 'member', memberId?: string) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        if (target === 'news') setCurrentNews(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'protocol') setCurrentProtocol(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'logo') setContactInfo(prev => ({ ...prev, logoUrl: result }));
        else if (target === 'member' && !memberId) setNewMember(prev => ({ ...prev, imageUrl: result }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveConfig = async () => {
    try {
      await saveContactInfo(contactInfo);
      await savePopups(popups);
      await saveQuickLinks(quickLinks);
      alert("Configuración institucional, popups y enlaces actualizados correctamente.");
    } catch (e) {
      alert("Error al guardar la configuración.");
    }
  };

  const handleAddMember = () => {
    if (!newMember.name || !newMember.role) return;
    const member: TeamMember = {
      id: `member-${Date.now()}`,
      name: newMember.name!,
      role: newMember.role!,
      imageUrl: newMember.imageUrl,
      order: contactInfo.teamMembers?.length || 0
    };
    setContactInfo(prev => ({ ...prev, teamMembers: [...(prev.teamMembers || []), member] }));
    setNewMember({ name: '', role: '' });
  };

  const handleRemoveMember = (id: string) => {
    setContactInfo(prev => ({ ...prev, teamMembers: prev.teamMembers?.filter(m => m.id !== id) }));
  };

  // Popup Management
  const handleAddPopup = () => {
    if (!newPopup.title || !newPopup.content) return;
    const p: PopupConfig = {
      id: `popup-${Date.now()}`,
      title: newPopup.title!,
      content: newPopup.content!,
      type: newPopup.type as any || 'info',
      isEnabled: true
    };
    setPopups([...popups, p]);
    setNewPopup({ title: '', content: '', type: 'info' });
  };

  const handleTogglePopup = (id: string) => {
    setPopups(popups.map(p => p.id === id ? { ...p, isEnabled: !p.isEnabled } : p));
  };

  const handleRemovePopup = (id: string) => {
    setPopups(popups.filter(p => p.id !== id));
  };

  // Quick Links Management
  const handleAddQuickLink = () => {
    if (!newQuickLink.title || !newQuickLink.url) return;
    const link: QuickLink = {
      id: `ql-${Date.now()}`,
      title: newQuickLink.title!,
      url: newQuickLink.url!,
      isEnabled: true
    };
    setQuickLinks([...quickLinks, link]);
    setNewQuickLink({ title: '', url: '' });
  };

  const handleToggleQuickLink = (id: string) => {
    setQuickLinks(quickLinks.map(l => l.id === id ? { ...l, isEnabled: !l.isEnabled } : l));
  };

  const handleRemoveQuickLink = (id: string) => {
    setQuickLinks(quickLinks.filter(l => l.id !== id));
  };

  const handleSaveNews = async () => {
    // Diagnóstico inicial
    if (!currentNews.title?.trim() || !currentNews.summary?.trim()) {
      alert("El título y el resumen de la noticia son campos obligatorios.");
      return;
    }

    try {
      let updatedNewsList: NewsItem[] = [];

      if (currentNews.id) {
        // MODO EDICIÓN: Buscamos la noticia en la lista y actualizamos sus campos
        updatedNewsList = news.map(n => 
          n.id === currentNews.id 
            ? { ...n, ...currentNews } as NewsItem 
            : n
        );
      } else {
        // MODO CREACIÓN: Creamos un nuevo objeto NewsItem y lo insertamos al inicio
        const newItem: NewsItem = {
          id: Date.now().toString(),
          title: currentNews.title!,
          summary: currentNews.summary!,
          category: (currentNews.category as any) || 'Novedad',
          date: new Date().toLocaleDateString('es-CO'),
          imageUrl: currentNews.imageUrl
        };
        updatedNewsList = [newItem, ...news];
      }

      // Sincronización con el servidor (o localStorage fallback en dataService)
      await saveNews(updatedNewsList);

      // Actualización de estado local para reflejar cambios en la UI
      setNews(updatedNewsList);
      setIsEditingNews(false);
      setCurrentNews({});

      alert(currentNews.id ? "Noticia actualizada correctamente." : "Noticia publicada correctamente.");
    } catch (error) {
      console.error("Error crítico al guardar noticia:", error);
      alert("No se pudieron guardar los cambios. Intente de nuevo más tarde.");
    }
  };

  const handleDeleteNews = async (id: string) => {
    if (!confirm("¿Eliminar noticia?")) return;
    const updated = news.filter(n => n.id !== id);
    await saveNews(updated);
    setNews(updated);
  };

  const handleSaveProtocol = async () => {
    if (!currentProtocol.title?.trim() || !currentProtocol.description?.trim()) {
      alert("Título y descripción requeridos");
      return;
    }

    try {
      const protocolToSave: EventType = {
        id: currentProtocol.id || `evt-${Date.now()}`,
        title: currentProtocol.title!,
        description: currentProtocol.description!,
        iconName: currentProtocol.iconName || 'FileText',
        imageUrl: currentProtocol.imageUrl,
        documentUrl: currentProtocol.documentUrl,
        baseSteps: (currentProtocol.baseSteps || []).map((s, i) => ({ ...s, order: i })),
        questions: currentProtocol.questions || [],
        alerts: currentProtocol.alerts || []
      };

      if (currentProtocol.id) {
        const updatedEvents = events.map(e => e.id === currentProtocol.id ? protocolToSave : e);
        await saveEvents(updatedEvents);
        setEvents(updatedEvents);
      } else {
        await addEvent(protocolToSave);
        setEvents(await getEvents());
      }
      setIsEditingProtocol(false);
      setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] });
      alert("Protocolo guardado exitosamente.");
    } catch (error) {
      alert("Error al guardar.");
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-sepri-dark flex flex-col items-center justify-center p-4 relative">
        <div className="absolute top-6 left-6">
          <Link to="/" className="text-white/70 hover:text-white flex items-center gap-2 font-bold transition-colors">
            <ArrowLeft size={20} /> Volver al inicio
          </Link>
        </div>

        <form onSubmit={handleSubmit} className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-md animate-fade-in-up">
          <div className="text-center mb-8">
            <Settings className="w-12 h-12 text-sepri-yellow mx-auto mb-2" />
            <h1 className="text-2xl font-bold text-sepri-dark">Acceso Administrativo</h1>
          </div>
          <div className="space-y-4">
            <input 
              type="email" 
              placeholder="Email" 
              className="w-full border p-3 rounded-lg outline-none focus:ring-2 focus:ring-sepri-medium" 
              value={email} 
              onChange={e => setEmail(e.target.value)} 
              required 
            />
            <input 
              type="password" 
              placeholder="Contraseña" 
              className="w-full border p-3 rounded-lg outline-none focus:ring-2 focus:ring-sepri-medium" 
              value={password} 
              onChange={e => setPassword(e.target.value)} 
              required 
            />
            <button 
              type="submit" 
              className="w-full bg-sepri-medium text-white p-3 rounded-lg font-bold hover:bg-sepri-dark transition-colors shadow-lg"
            >
              Entrar al Panel
            </button>
          </div>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Sidebar */}
      <div className="w-64 bg-sepri-dark text-white p-6 hidden md:block">
        <div className="flex items-center gap-3 mb-8">
          <Settings className="text-sepri-yellow" />
          <h1 className="font-bold text-lg">Panel SEPRI</h1>
        </div>
        <nav className="space-y-2">
          <button onClick={() => setActiveTab('news')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'news' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Newspaper size={18} /> Noticias</button>
          <button onClick={() => setActiveTab('protocols')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'protocols' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Briefcase size={18} /> Protocolos</button>
          <button onClick={() => setActiveTab('config')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'config' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Settings size={18} /> Configuración</button>
        </nav>
        <button onClick={handleLogout} className="mt-8 text-red-400 flex items-center gap-2 hover:text-red-300 px-3"><LogOut size={18} /> Salir</button>
      </div>

      <div className="flex-1 p-8 overflow-y-auto">
        {/* News Tab */}
        {activeTab === 'news' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
               <h2 className="text-2xl font-bold">Gestión de Noticias</h2>
               <button onClick={() => { setCurrentNews({}); setIsEditingNews(true); }} className="bg-sepri-medium text-white px-6 py-2 rounded-lg flex items-center gap-2 shadow hover:bg-sepri-dark">
                  <Plus size={18} /> Nueva Noticia
               </button>
            </div>
            {isEditingNews && (
              <form 
                onSubmit={(e) => { e.preventDefault(); handleSaveNews(); }}
                className="bg-white p-6 rounded-xl shadow border animate-fade-in"
              >
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                    <input 
                      type="text" 
                      placeholder="Título" 
                      className="w-full border p-2 rounded focus:ring-2 focus:ring-sepri-medium outline-none" 
                      value={currentNews.title || ''} 
                      onChange={e => setCurrentNews(prev => ({...prev, title: e.target.value}))} 
                      required
                    />
                    <select 
                      className="border p-2 rounded" 
                      value={currentNews.category || 'Novedad'} 
                      onChange={e => setCurrentNews(prev => ({...prev, category: e.target.value as any}))}
                    >
                       <option value="Novedad">Novedad</option>
                       <option value="Evento">Evento</option>
                       <option value="Importante">Importante</option>
                    </select>
                 </div>
                 <textarea 
                   placeholder="Resumen de la noticia..." 
                   className="w-full border p-2 rounded mb-4 focus:ring-2 focus:ring-sepri-medium outline-none" 
                   rows={6} 
                   value={currentNews.summary || ''} 
                   onChange={e => setCurrentNews(prev => ({...prev, summary: e.target.value}))} 
                   required
                 />

                 {/* Preview and Upload Section */}
                 <div className="flex items-center gap-6 mb-6 p-4 bg-gray-50 rounded-lg border border-dashed">
                    <div className="w-24 h-24 bg-white border rounded overflow-hidden flex-shrink-0 flex items-center justify-center">
                       {currentNews.imageUrl ? (
                          <img src={currentNews.imageUrl} className="w-full h-full object-cover" alt="Preview" />
                       ) : (
                          <ImageIcon className="text-gray-300" size={32} />
                       )}
                    </div>
                    <div className="flex flex-col gap-2">
                       <p className="text-xs font-bold text-gray-500 uppercase tracking-tight">Imagen de Noticia</p>
                       <label className="bg-white border border-gray-300 px-4 py-2 rounded-lg cursor-pointer text-xs font-bold hover:bg-gray-100 transition-colors shadow-sm inline-block">
                          {currentNews.imageUrl ? "Cambiar Imagen" : "Subir Imagen"}
                          <input type="file" className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'news')} />
                       </label>
                    </div>
                 </div>

                 <div className="flex gap-4">
                    <button 
                      type="submit" 
                      className="bg-sepri-medium text-white px-6 py-2 rounded-lg font-bold ml-auto shadow-md hover:bg-sepri-dark transition-all active:scale-95"
                    >
                      {currentNews.id ? "Guardar Cambios" : "Publicar Noticia"}
                    </button>
                    <button 
                      type="button" 
                      onClick={() => { setIsEditingNews(false); setCurrentNews({}); }} 
                      className="px-4 py-2 text-gray-500 font-medium hover:text-gray-700"
                    >
                      Cancelar
                    </button>
                 </div>
              </form>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               {news.map(n => (
                 <div key={n.id} className="bg-white p-4 rounded-xl border flex gap-4 items-center group hover:border-sepri-medium transition-colors">
                    <div className="w-16 h-16 bg-gray-100 rounded overflow-hidden flex-shrink-0">
                       {n.imageUrl && <img src={n.imageUrl} className="w-full h-full object-cover" />}
                    </div>
                    <div className="flex-1">
                       <h4 className="font-bold text-sm line-clamp-1">{n.title}</h4>
                       <p className="text-xs text-gray-400">{n.date}</p>
                    </div>
                    <div className="flex gap-1">
                       <button onClick={() => { setCurrentNews(n); setIsEditingNews(true); }} className="text-blue-500 p-2 hover:bg-blue-50 rounded" title="Editar noticia"><Edit2 size={16}/></button>
                       <button onClick={() => handleDeleteNews(n.id)} className="text-red-400 p-2 hover:bg-red-50 rounded" title="Eliminar noticia"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* Protocols Tab (Minimized for Brevity in this block, assumed same as previous working state) */}
        {activeTab === 'protocols' && (
          <div>
            <div className="mb-6 flex justify-between items-center">
               <h2 className="text-2xl font-bold">Gestión de Protocolos</h2>
               <button onClick={() => { setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] }); setIsEditingProtocol(true); }} className="bg-sepri-medium text-white px-4 py-2 rounded flex items-center gap-2 hover:bg-sepri-dark">
                  <Plus size={18} /> Nuevo Protocolo
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
               {events.map(event => (
                 <div key={event.id} className="bg-white p-4 rounded-xl border shadow-sm">
                    <h3 className="font-bold">{event.title}</h3>
                    <div className="flex justify-end gap-2 mt-4">
                       <button onClick={() => { setCurrentProtocol(event); setIsEditingProtocol(true); }} className="text-blue-500"><Edit2 size={16}/></button>
                       <button onClick={() => deleteEvent(event.id).then(loadData)} className="text-red-500"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* NEW CONFIGURATION SECTIONS */}
        {activeTab === 'config' && (
          <div className="max-w-4xl space-y-10 pb-20">
            <h2 className="text-3xl font-black text-sepri-dark border-b pb-4">Configuración del Sistema</h2>

            {/* Logo & Branding */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><ImageIcon size={20}/> Identidad Visual (Logo D22)</h3>
              <div className="flex items-center gap-6">
                 <div className="w-24 h-24 border rounded-xl overflow-hidden flex items-center justify-center bg-gray-50">
                    {contactInfo.logoUrl ? <img src={contactInfo.logoUrl} className="max-w-full max-h-full object-contain" /> : <ImageIcon className="text-gray-300" size={32}/>}
                 </div>
                 <label className="bg-sepri-bg text-sepri-dark px-4 py-2 rounded-lg cursor-pointer hover:bg-gray-200 font-bold text-sm">
                   Subir Logo Distrito
                   <input type="file" className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'logo')} />
                 </label>
              </div>
            </section>

            {/* Contacts & General Info */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Phone size={20}/> Información de Contacto</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Coordinador Principal</label>
                    <input type="text" placeholder="Nombre Coordinador" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorName || ''} onChange={e => setContactInfo({...contactInfo, coordinatorName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorPhone || ''} onChange={e => setContactInfo({...contactInfo, coordinatorPhone: e.target.value})} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Asistente de Coordinación</label>
                    <input type="text" placeholder="Nombre Asistente" className="w-full border p-3 rounded-lg" value={contactInfo.assistantName || ''} onChange={e => setContactInfo({...contactInfo, assistantName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.assistantPhone || ''} onChange={e => setContactInfo({...contactInfo, assistantPhone: e.target.value})} />
                 </div>
              </div>
              <div className="space-y-4">
                 <div className="flex flex-col gap-2">
                    <label className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2"><Mail size={14}/> Correo Institucional</label>
                    <input type="email" placeholder="email@ipuc.org.co" className="w-full border p-3 rounded-lg" value={contactInfo.email || ''} onChange={e => setContactInfo({...contactInfo, email: e.target.value})} />
                 </div>
                 <div className="flex flex-col gap-2">
                    <label className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2"><MapPin size={14}/> Dirección Administrativa</label>
                    <input type="text" placeholder="Dirección de la sede" className="w-full border p-3 rounded-lg" value={contactInfo.address || ''} onChange={e => setContactInfo({...contactInfo, address: e.target.value})} />
                 </div>
              </div>
            </section>

            {/* Social Media */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Facebook size={20}/> Redes Sociales</h3>
              <div className="space-y-4">
                 <div className="flex items-center gap-4">
                    <Facebook className="text-blue-600" />
                    <input type="text" placeholder="URL Facebook" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.facebookUrl || ''} onChange={e => setContactInfo({...contactInfo, facebookUrl: e.target.value})} />
                 </div>
                 <div className="flex items-center gap-4">
                    <Instagram className="text-pink-600" />
                    <input type="text" placeholder="URL Instagram" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.instagramUrl || ''} onChange={e => setContactInfo({...contactInfo, instagramUrl: e.target.value})} />
                 </div>
                 <div className="flex items-center gap-4">
                    <Youtube className="text-red-600" />
                    <input type="text" placeholder="URL YouTube" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.youtubeUrl || ''} onChange={e => setContactInfo({...contactInfo, youtubeUrl: e.target.value})} />
                 </div>
              </div>
            </section>

            {/* Quick Links Manager */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><LinkIcon size={20}/> Enlaces Rápidos (Footer)</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-3">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <input type="text" placeholder="Título del enlace" className="border p-2 rounded text-sm" value={newQuickLink.title || ''} onChange={e => setNewQuickLink({...newQuickLink, title: e.target.value})} />
                    <input type="text" placeholder="URL (/ruta o https://)" className="border p-2 rounded text-sm" value={newQuickLink.url || ''} onChange={e => setNewQuickLink({...newQuickLink, url: e.target.value})} />
                 </div>
                 <button onClick={handleAddQuickLink} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold hover:bg-sepri-dark">Agregar Enlace</button>
              </div>
              <div className="space-y-2">
                 {quickLinks.map(link => (
                    <div key={link.id} className="flex items-center justify-between p-3 border rounded-lg bg-white">
                       <div className="flex items-center gap-3">
                          <input type="checkbox" checked={link.isEnabled} onChange={() => handleToggleQuickLink(link.id)} className="w-4 h-4 accent-sepri-medium" />
                          <div>
                             <p className="text-sm font-bold">{link.title}</p>
                             <p className="text-[10px] text-gray-500">{link.url}</p>
                          </div>
                       </div>
                       <button onClick={() => handleRemoveQuickLink(link.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* Popups Manager */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Bell size={20}/> Ventanas Emergentes (Popups)</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-4">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <input type="text" placeholder="Título del aviso" className="border p-2 rounded text-sm" value={newPopup.title || ''} onChange={e => setNewPopup({...newPopup, title: e.target.value})} />
                    <select className="border p-2 rounded text-sm" value={newPopup.type || 'info'} onChange={e => setNewPopup({...newPopup, type: e.target.value as any})}>
                       <option value="info">Información (Azul)</option>
                       <option value="warning">Advertencia (Amarillo)</option>
                       <option value="alert">Alerta Crítica (Rojo)</option>
                    </select>
                 </div>
                 <textarea placeholder="Contenido del mensaje..." className="w-full border p-2 rounded text-sm" rows={2} value={newPopup.content || ''} onChange={e => setNewPopup({...newPopup, content: e.target.value})} />
                 <button onClick={handleAddPopup} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold hover:bg-sepri-dark">Crear Aviso</button>
              </div>
              <div className="space-y-3">
                 {popups.map(p => (
                    <div key={p.id} className="flex items-center justify-between p-4 border rounded-xl bg-white shadow-sm">
                       <div className="flex items-center gap-4">
                          <input type="checkbox" checked={p.isEnabled} onChange={() => handleTogglePopup(p.id)} className="w-5 h-5 accent-sepri-medium" />
                          <div>
                             <div className="flex items-center gap-2">
                                <span className={`w-2 h-2 rounded-full ${p.type === 'alert' ? 'bg-red-500' : p.type === 'warning' ? 'bg-yellow-500' : 'bg-blue-500'}`}></span>
                                <p className="text-sm font-bold">{p.title}</p>
                             </div>
                             <p className="text-xs text-gray-500 line-clamp-1">{p.content}</p>
                          </div>
                       </div>
                       <button onClick={() => handleRemovePopup(p.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* Privacy Policy */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Lock size={20}/> Políticas y Privacidad</h3>
              <textarea 
                className="w-full border p-4 rounded-xl min-h-[150px] text-sm leading-relaxed" 
                value={contactInfo.privacyPolicy || ''} 
                onChange={e => setContactInfo({...contactInfo, privacyPolicy: e.target.value})}
                placeholder="Escribe la política de privacidad oficial aquí..."
              />
            </section>

            {/* Team Members */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><User size={20}/> Equipo SEPRI</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-4">
                 <div className="grid grid-cols-2 gap-4">
                    <input type="text" placeholder="Nombre" className="border p-2 rounded text-sm" value={newMember.name || ''} onChange={e => setNewMember({...newMember, name: e.target.value})} />
                    <input type="text" placeholder="Cargo" className="border p-2 rounded text-sm" value={newMember.role || ''} onChange={e => setNewMember({...newMember, role: e.target.value})} />
                 </div>
                 <div className="flex gap-4">
                    <label className="bg-white px-4 py-2 border rounded cursor-pointer text-xs font-bold">
                       {newMember.imageUrl ? "Foto lista" : "Subir Foto"}
                       <input type="file" className="hidden" onChange={e => handleImageUpload(e, 'member')} />
                    </label>
                    <button onClick={handleAddMember} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold ml-auto">Agregar Miembro</button>
                 </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {contactInfo.teamMembers?.map(m => (
                    <div key={m.id} className="flex items-center gap-4 p-3 border rounded-xl bg-white shadow-sm">
                       <div className="w-10 h-10 rounded-full bg-gray-100 overflow-hidden">
                          {m.imageUrl && <img src={m.imageUrl} className="w-full h-full object-cover" />}
                       </div>
                       <div className="flex-1">
                          <p className="font-bold text-xs">{m.name}</p>
                          <p className="text-[10px] text-gray-500">{m.role}</p>
                       </div>
                       <button onClick={() => handleRemoveMember(m.id)} className="text-red-400 hover:text-red-600"><Trash2 size={14}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* GLOBAL SAVE ACTION */}
            <div className="sticky bottom-6 flex justify-center">
               <button onClick={handleSaveConfig} className="bg-green-600 text-white px-12 py-4 rounded-full font-black flex items-center justify-center gap-3 shadow-2xl hover:bg-green-700 transition-all hover:scale-105 active:scale-95 group">
                 <Save size={24} className="group-hover:rotate-12 transition-transform"/> GUARDAR TODA LA CONFIGURACIÓN
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminLogin;
